insert into public.training_questions
  (module, card_key, locale, question, options, correct_index, explanation, hint, legal_ref)
values
  ('masses', 'masses.m1', 'fi', 'Mikä on vetävän akselin suurin sallittu massa Suomessa?', '["10 t","11,5 t","13 t","9 t"]'::jsonb, 1, 'Vetävän akselin suurin massa on 11,5 t, ei-vetävän 10 t.', 'Vetävä akseli saa kantaa enemmän kuin ei-vetävä.', 'VNa 1257/1992'),
  ('masses', 'masses.m1', 'en', 'What is the maximum permitted mass of a drive axle in Finland?', '["10 t","11.5 t","13 t","9 t"]'::jsonb, 1, 'A drive axle may carry up to 11.5 t, a non-driven axle 10 t.', 'The drive axle may carry more than a non-driven one.', 'VNa 1257/1992'),
  ('masses', 'masses.m1', 'et', 'Milline on veotelje suurim lubatud mass Soomes?', '["10 t","11,5 t","13 t","9 t"]'::jsonb, 1, 'Veotelje suurim mass on 11,5 t, mitteveotelje 10 t.', 'Veotelg tohib kanda rohkem kui mitteveotelg.', 'VNa 1257/1992'),
  ('masses', 'masses.m1', 'ru', 'Какая максимальная масса на ведущую ось в Финляндии?', '["10 т","11,5 т","13 т","9 т"]'::jsonb, 1, 'На ведущую ось — до 11,5 т, на неведущую — до 10 т.', 'Ведущая ось может нести больше, чем неведущая.', 'ПП 1257/1992 (Финляндия)'),
  ('masses', 'masses.m1', 'sv', 'Vilket är högsta tillåtna axeltryck för en drivaxel i Finland?', '["10 t","11,5 t","13 t","9 t"]'::jsonb, 1, 'En drivaxel får bära högst 11,5 t, en icke drivande axel 10 t.', 'Drivaxeln får bära mer än en icke drivande.', 'VNa 1257/1992'),
  ('masses', 'masses.m1', 'lv', 'Kāda ir dzenošās ass lielākā pieļaujamā masa Somijā?', '["10 t","11,5 t","13 t","9 t"]'::jsonb, 1, 'Dzenošajai asij līdz 11,5 t, nedzenošajai — 10 t.', 'Dzenošā ass drīkst nest vairāk nekā nedzenošā.', 'VNa 1257/1992'),
  ('masses', 'masses.m1', 'lt', 'Kokia didžiausia leidžiama varančiosios ašies masė Suomijoje?', '["10 t","11,5 t","13 t","9 t"]'::jsonb, 1, 'Varančiajai ašiai — iki 11,5 t, nevarančiajai — 10 t.', 'Varančioji ašis gali nešti daugiau nei nevaranti.', 'VNa 1257/1992'),
  ('masses', 'masses.m1', 'pl', 'Jaki jest maksymalny dopuszczalny nacisk osi napędowej w Finlandii?', '["10 t","11,5 t","13 t","9 t"]'::jsonb, 1, 'Oś napędowa — do 11,5 t, oś nienapędowa — 10 t.', 'Oś napędowa może przenosić więcej niż nienapędowa.', 'VNa 1257/1992'),
  ('masses', 'masses.m1', 'nb', 'Hva er høyeste tillatte akseltrykk for en drivaksel i Finland?', '["10 t","11,5 t","13 t","9 t"]'::jsonb, 1, 'En drivaksel kan bære opptil 11,5 t, en ikke-drivende aksel 10 t.', 'Drivakselen kan bære mer enn en ikke-drivende.', 'VNa 1257/1992'),
  ('masses', 'masses.m1', 'da', 'Hvad er det største tilladte akseltryk for en drivaksel i Finland?', '["10 t","11,5 t","13 t","9 t"]'::jsonb, 1, 'En drivaksel må bære op til 11,5 t, en ikke-trækkende aksel 10 t.', 'Drivakslen må bære mere end en ikke-trækkende.', 'VNa 1257/1992'),
  ('masses', 'masses.m2', 'fi', 'Mikä on ei-vetävän yksittäisen akselin suurin sallittu massa?', '["8 t","10 t","11,5 t","12 t"]'::jsonb, 1, 'Ei-vetävän yksittäisen akselin suurin massa on 10 t.', 'Pienempi kuin vetävällä akselilla.', 'VNa 1257/1992'),
  ('masses', 'masses.m2', 'en', 'What is the maximum permitted mass of a single non-driven axle?', '["8 t","10 t","11.5 t","12 t"]'::jsonb, 1, 'A single non-driven axle may carry up to 10 t.', 'Less than a drive axle.', 'VNa 1257/1992'),
  ('masses', 'masses.m2', 'et', 'Milline on üksiku mitteveotelje suurim lubatud mass?', '["8 t","10 t","11,5 t","12 t"]'::jsonb, 1, 'Üksiku mitteveotelje suurim mass on 10 t.', 'Väiksem kui veoteljel.', 'VNa 1257/1992'),
  ('masses', 'masses.m2', 'ru', 'Какая максимальная масса на одиночную неведущую ось?', '["8 т","10 т","11,5 т","12 т"]'::jsonb, 1, 'Одиночная неведущая ось — до 10 т.', 'Меньше, чем у ведущей.', 'ПП 1257/1992 (Финляндия)'),
  ('masses', 'masses.m2', 'sv', 'Vilket är högsta tillåtna axeltryck för en enkel icke drivande axel?', '["8 t","10 t","11,5 t","12 t"]'::jsonb, 1, 'En enkel icke drivande axel får bära högst 10 t.', 'Mindre än för en drivaxel.', 'VNa 1257/1992'),
  ('masses', 'masses.m2', 'lv', 'Kāda ir atsevišķas nedzenošās ass lielākā pieļaujamā masa?', '["8 t","10 t","11,5 t","12 t"]'::jsonb, 1, 'Atsevišķai nedzenošajai asij — līdz 10 t.', 'Mazāk nekā dzenošajai.', 'VNa 1257/1992'),
  ('masses', 'masses.m2', 'lt', 'Kokia didžiausia leidžiama pavienės nevarančiosios ašies masė?', '["8 t","10 t","11,5 t","12 t"]'::jsonb, 1, 'Pavienei nevarančiajai ašiai — iki 10 t.', 'Mažiau nei varančiajai.', 'VNa 1257/1992'),
  ('masses', 'masses.m2', 'pl', 'Jaki jest maksymalny dopuszczalny nacisk pojedynczej osi nienapędowej?', '["8 t","10 t","11,5 t","12 t"]'::jsonb, 1, 'Pojedyncza oś nienapędowa — do 10 t.', 'Mniej niż oś napędowa.', 'VNa 1257/1992'),
  ('masses', 'masses.m2', 'nb', 'Hva er høyeste tillatte akseltrykk for en enkelt ikke-drivende aksel?', '["8 t","10 t","11,5 t","12 t"]'::jsonb, 1, 'En enkelt ikke-drivende aksel kan bære opptil 10 t.', 'Mindre enn en drivaksel.', 'VNa 1257/1992'),
  ('masses', 'masses.m2', 'da', 'Hvad er det største tilladte akseltryk for en enkelt ikke-trækkende aksel?', '["8 t","10 t","11,5 t","12 t"]'::jsonb, 1, 'En enkelt ikke-trækkende aksel må bære op til 10 t.', 'Mindre end en drivaksel.', 'VNa 1257/1992'),
  ('masses', 'masses.m3', 'fi', 'Mikä on 5-akselisen ajoneuvoyhdistelmän suurin sallittu massa?', '["40 t","42 t","44 t","48 t"]'::jsonb, 2, 'Viisiakselinen yhdistelmä saa painaa enintään 44 t.', 'Yli 40, alle 48.', 'VNa 1257/1992'),
  ('masses', 'masses.m3', 'en', 'What is the maximum permitted mass of a 5-axle combination?', '["40 t","42 t","44 t","48 t"]'::jsonb, 2, 'A five-axle combination may weigh up to 44 t.', 'Over 40, under 48.', 'VNa 1257/1992'),
  ('masses', 'masses.m3', 'et', 'Milline on 5-teljelise autorongi suurim lubatud mass?', '["40 t","42 t","44 t","48 t"]'::jsonb, 2, 'Viieteljeline autorong tohib kaaluda kuni 44 t.', 'Üle 40, alla 48.', 'VNa 1257/1992'),
  ('masses', 'masses.m3', 'ru', 'Какая максимальная масса пятиосного автопоезда?', '["40 т","42 т","44 т","48 т"]'::jsonb, 2, 'Пятиосный автопоезд — до 44 т.', 'Больше 40, меньше 48.', 'ПП 1257/1992 (Финляндия)'),
  ('masses', 'masses.m3', 'sv', 'Vilken är högsta tillåtna vikt för ett femaxligt ekipage?', '["40 t","42 t","44 t","48 t"]'::jsonb, 2, 'Ett femaxligt ekipage får väga högst 44 t.', 'Över 40, under 48.', 'VNa 1257/1992'),
  ('masses', 'masses.m3', 'lv', 'Kāda ir 5 asu autovilciena lielākā pieļaujamā masa?', '["40 t","42 t","44 t","48 t"]'::jsonb, 2, 'Piecu asu autovilciens drīkst svērt līdz 44 t.', 'Virs 40, zem 48.', 'VNa 1257/1992'),
  ('masses', 'masses.m3', 'lt', 'Kokia didžiausia leidžiama 5 ašių autotraukinio masė?', '["40 t","42 t","44 t","48 t"]'::jsonb, 2, 'Penkių ašių autotraukinys gali sverti iki 44 t.', 'Daugiau nei 40, mažiau nei 48.', 'VNa 1257/1992'),
  ('masses', 'masses.m3', 'pl', 'Jaka jest maksymalna dopuszczalna masa zestawu pięcioosiowego?', '["40 t","42 t","44 t","48 t"]'::jsonb, 2, 'Zestaw pięcioosiowy może ważyć do 44 t.', 'Więcej niż 40, mniej niż 48.', 'VNa 1257/1992'),
  ('masses', 'masses.m3', 'nb', 'Hva er høyeste tillatte totalvekt for et femakslet vogntog?', '["40 t","42 t","44 t","48 t"]'::jsonb, 2, 'Et femakslet vogntog kan veie opptil 44 t.', 'Over 40, under 48.', 'VNa 1257/1992'),
  ('masses', 'masses.m3', 'da', 'Hvad er den største tilladte vægt for et femakslet vogntog?', '["40 t","42 t","44 t","48 t"]'::jsonb, 2, 'Et femakslet vogntog må veje op til 44 t.', 'Over 40, under 48.', 'VNa 1257/1992'),
  ('masses', 'masses.m4', 'fi', 'Mikä on 9-akselisen yhdistelmän suurin sallittu massa Suomessa?', '["60 t","68 t","76 t","84 t"]'::jsonb, 2, 'Yhdeksänakselinen yhdistelmä saa painaa Suomessa enintään 76 t, kun akselivälit ja rakenne täyttävät vaatimukset.', 'Euroopan suurin sallittu kokonaismassa.', 'VNa 1257/1992'),
  ('masses', 'masses.m4', 'en', 'What is the maximum permitted mass of a 9-axle combination in Finland?', '["60 t","68 t","76 t","84 t"]'::jsonb, 2, 'In Finland a nine-axle combination may weigh up to 76 t when its axle spacings and design meet the requirements.', 'The highest general limit in Europe.', 'VNa 1257/1992'),
  ('masses', 'masses.m4', 'et', 'Milline on 9-teljelise autorongi suurim lubatud mass Soomes?', '["60 t","68 t","76 t","84 t"]'::jsonb, 2, 'Soomes tohib üheksateljeline autorong kaaluda kuni 76 t, kui teljevahed ja konstruktsioon vastavad nõuetele.', 'Euroopa suurim üldine piir.', 'VNa 1257/1992'),
  ('masses', 'masses.m4', 'ru', 'Какая максимальная масса девятиосного автопоезда в Финляндии?', '["60 т","68 т","76 т","84 т"]'::jsonb, 2, 'В Финляндии девятиосный автопоезд — до 76 т, если межосевые расстояния и конструкция соответствуют требованиям.', 'Самый высокий общий предел в Европе.', 'ПП 1257/1992 (Финляндия)'),
  ('masses', 'masses.m4', 'sv', 'Vilken är högsta tillåtna vikt för ett nioaxligt ekipage i Finland?', '["60 t","68 t","76 t","84 t"]'::jsonb, 2, 'I Finland får ett nioaxligt ekipage väga högst 76 t när axelavstånd och konstruktion uppfyller kraven.', 'Den högsta allmänna gränsen i Europa.', 'VNa 1257/1992'),
  ('masses', 'masses.m4', 'lv', 'Kāda ir 9 asu autovilciena lielākā pieļaujamā masa Somijā?', '["60 t","68 t","76 t","84 t"]'::jsonb, 2, 'Somijā deviņu asu autovilciens drīkst svērt līdz 76 t, ja asu attālumi un konstrukcija atbilst prasībām.', 'Lielākā vispārējā robeža Eiropā.', 'VNa 1257/1992'),
  ('masses', 'masses.m4', 'lt', 'Kokia didžiausia leidžiama 9 ašių autotraukinio masė Suomijoje?', '["60 t","68 t","76 t","84 t"]'::jsonb, 2, 'Suomijoje devynių ašių autotraukinys gali sverti iki 76 t, jei tarpašiai ir konstrukcija atitinka reikalavimus.', 'Didžiausia bendra riba Europoje.', 'VNa 1257/1992'),
  ('masses', 'masses.m4', 'pl', 'Jaka jest maksymalna dopuszczalna masa zestawu dziewięcioosiowego w Finlandii?', '["60 t","68 t","76 t","84 t"]'::jsonb, 2, 'W Finlandii zestaw dziewięcioosiowy może ważyć do 76 t, jeśli rozstawy osi i konstrukcja spełniają wymagania.', 'Najwyższy ogólny limit w Europie.', 'VNa 1257/1992'),
  ('masses', 'masses.m4', 'nb', 'Hva er høyeste tillatte totalvekt for et niakslet vogntog i Finland?', '["60 t","68 t","76 t","84 t"]'::jsonb, 2, 'I Finland kan et niakslet vogntog veie opptil 76 t når akselavstander og konstruksjon oppfyller kravene.', 'Den høyeste generelle grensen i Europa.', 'VNa 1257/1992'),
  ('masses', 'masses.m4', 'da', 'Hvad er den største tilladte vægt for et niakslet vogntog i Finland?', '["60 t","68 t","76 t","84 t"]'::jsonb, 2, 'I Finland må et niakslet vogntog veje op til 76 t, når akselafstande og konstruktion opfylder kravene.', 'Den højeste generelle grænse i Europa.', 'VNa 1257/1992'),
  ('masses', 'masses.m5', 'fi', 'Mikä on ajoneuvoyhdistelmän suurin sallittu pituus Suomessa?', '["18,75 m","25,25 m","34,5 m","40 m"]'::jsonb, 2, 'Yhdistelmän suurin sallittu pituus on 34,5 m.', 'Suomessa sallitaan pitkät HCT-yhdistelmät.', 'VNa 1257/1992'),
  ('masses', 'masses.m5', 'en', 'What is the maximum permitted length of a combination in Finland?', '["18.75 m","25.25 m","34.5 m","40 m"]'::jsonb, 2, 'The maximum permitted length of a combination is 34.5 m.', 'Finland allows long HCT combinations.', 'VNa 1257/1992'),
  ('masses', 'masses.m5', 'et', 'Milline on autorongi suurim lubatud pikkus Soomes?', '["18,75 m","25,25 m","34,5 m","40 m"]'::jsonb, 2, 'Autorongi suurim lubatud pikkus on 34,5 m.', 'Soomes on lubatud pikad HCT-autorongid.', 'VNa 1257/1992'),
  ('masses', 'masses.m5', 'ru', 'Какая максимальная длина автопоезда в Финляндии?', '["18,75 м","25,25 м","34,5 м","40 м"]'::jsonb, 2, 'Максимальная длина автопоезда — 34,5 м.', 'В Финляндии разрешены длинные поезда HCT.', 'ПП 1257/1992 (Финляндия)'),
  ('masses', 'masses.m5', 'sv', 'Vilken är den högsta tillåtna längden för ett ekipage i Finland?', '["18,75 m","25,25 m","34,5 m","40 m"]'::jsonb, 2, 'Ett ekipage får vara högst 34,5 m långt.', 'Finland tillåter långa HCT-ekipage.', 'VNa 1257/1992'),
  ('masses', 'masses.m5', 'lv', 'Kāds ir autovilciena lielākais pieļaujamais garums Somijā?', '["18,75 m","25,25 m","34,5 m","40 m"]'::jsonb, 2, 'Autovilciena lielākais garums ir 34,5 m.', 'Somijā atļauti gari HCT autovilcieni.', 'VNa 1257/1992'),
  ('masses', 'masses.m5', 'lt', 'Koks didžiausias leidžiamas autotraukinio ilgis Suomijoje?', '["18,75 m","25,25 m","34,5 m","40 m"]'::jsonb, 2, 'Didžiausias leidžiamas autotraukinio ilgis — 34,5 m.', 'Suomijoje leidžiami ilgi HCT autotraukiniai.', 'VNa 1257/1992'),
  ('masses', 'masses.m5', 'pl', 'Jaka jest maksymalna dopuszczalna długość zestawu w Finlandii?', '["18,75 m","25,25 m","34,5 m","40 m"]'::jsonb, 2, 'Maksymalna długość zestawu to 34,5 m.', 'Finlandia dopuszcza długie zestawy HCT.', 'VNa 1257/1992'),
  ('masses', 'masses.m5', 'nb', 'Hva er største tillatte lengde for et vogntog i Finland?', '["18,75 m","25,25 m","34,5 m","40 m"]'::jsonb, 2, 'Et vogntog kan være opptil 34,5 m langt.', 'Finland tillater lange HCT-vogntog.', 'VNa 1257/1992'),
  ('masses', 'masses.m5', 'da', 'Hvad er den største tilladte længde for et vogntog i Finland?', '["18,75 m","25,25 m","34,5 m","40 m"]'::jsonb, 2, 'Et vogntog må højst være 34,5 m langt.', 'Finland tillader lange HCT-vogntog.', 'VNa 1257/1992'),
  ('masses', 'masses.m6', 'fi', 'Mikä on ajoneuvon suurin sallittu korkeus Suomessa?', '["4,0 m","4,2 m","4,4 m","4,6 m"]'::jsonb, 2, 'Suurin sallittu korkeus on 4,4 m. Silloissa ja alikulkukäytävissä korkeus on silti aina tarkistettava merkeistä.', 'Korkeampi kuin monessa muussa EU-maassa.', 'VNa 1257/1992'),
  ('masses', 'masses.m6', 'en', 'What is the maximum permitted vehicle height in Finland?', '["4.0 m","4.2 m","4.4 m","4.6 m"]'::jsonb, 2, 'The maximum permitted height is 4.4 m. At bridges and underpasses, always check the signed clearance anyway.', 'Higher than in many other EU countries.', 'VNa 1257/1992'),
  ('masses', 'masses.m6', 'et', 'Milline on sõiduki suurim lubatud kõrgus Soomes?', '["4,0 m","4,2 m","4,4 m","4,6 m"]'::jsonb, 2, 'Suurim lubatud kõrgus on 4,4 m. Sildade ja viaduktide juures kontrolli kõrgust siiski märkidelt.', 'Kõrgem kui paljudes teistes ELi riikides.', 'VNa 1257/1992'),
  ('masses', 'masses.m6', 'ru', 'Какая максимальная высота транспортного средства в Финляндии?', '["4,0 м","4,2 м","4,4 м","4,6 м"]'::jsonb, 2, 'Максимальная высота — 4,4 м. У мостов и путепроводов всё равно проверяйте высоту по знакам.', 'Выше, чем во многих странах ЕС.', 'ПП 1257/1992 (Финляндия)'),
  ('masses', 'masses.m6', 'sv', 'Vilken är den högsta tillåtna fordonshöjden i Finland?', '["4,0 m","4,2 m","4,4 m","4,6 m"]'::jsonb, 2, 'Högsta tillåtna höjd är 4,4 m. Vid broar och viadukter ska höjden ändå alltid kontrolleras på skyltarna.', 'Högre än i många andra EU-länder.', 'VNa 1257/1992'),
  ('masses', 'masses.m6', 'lv', 'Kāds ir transportlīdzekļa lielākais pieļaujamais augstums Somijā?', '["4,0 m","4,2 m","4,4 m","4,6 m"]'::jsonb, 2, 'Lielākais pieļaujamais augstums ir 4,4 m. Pie tiltiem un satiksmes pārvadiem augstumu tik un tā pārbaudi pēc zīmēm.', 'Augstāks nekā daudzās citās ES valstīs.', 'VNa 1257/1992'),
  ('masses', 'masses.m6', 'lt', 'Koks didžiausias leidžiamas transporto priemonės aukštis Suomijoje?', '["4,0 m","4,2 m","4,4 m","4,6 m"]'::jsonb, 2, 'Didžiausias leidžiamas aukštis — 4,4 m. Prie tiltų ir viadukų aukštį vis tiek tikrink pagal ženklus.', 'Aukščiau nei daugelyje kitų ES šalių.', 'VNa 1257/1992'),
  ('masses', 'masses.m6', 'pl', 'Jaka jest maksymalna dopuszczalna wysokość pojazdu w Finlandii?', '["4,0 m","4,2 m","4,4 m","4,6 m"]'::jsonb, 2, 'Maksymalna wysokość to 4,4 m. Przy mostach i wiaduktach i tak zawsze sprawdzaj wysokość na znakach.', 'Wyższa niż w wielu innych krajach UE.', 'VNa 1257/1992'),
  ('masses', 'masses.m6', 'nb', 'Hva er største tillatte kjøretøyhøyde i Finland?', '["4,0 m","4,2 m","4,4 m","4,6 m"]'::jsonb, 2, 'Største tillatte høyde er 4,4 m. Ved bruer og undergangar skal skiltet høyde likevel alltid sjekkes.', 'Høyere enn i mange andre EU-land.', 'VNa 1257/1992'),
  ('masses', 'masses.m6', 'da', 'Hvad er den største tilladte køretøjshøjde i Finland?', '["4,0 m","4,2 m","4,4 m","4,6 m"]'::jsonb, 2, 'Den største tilladte højde er 4,4 m. Ved broer og viadukter skal den skiltede højde alligevel altid kontrolleres.', 'Højere end i mange andre EU-lande.', 'VNa 1257/1992'),
  ('masses', 'masses.m7', 'fi', 'Täydestä perävaunusta purettiin takaosa välipisteellä. Kokonaismassa pieneni. Mitä voi tapahtua?', '["Ei mitään, massa pieneni","Vetävä akseli voi ylikuormittua","Perävaunun teli ylikuormittuu","Ohjaava akseli nousee irti"]'::jsonb, 1, 'Jäljelle jäänyt kuorma on nyt lähempänä vetopöytää, joten suurempi osa siitä siirtyy vetoautolle ja erityisesti vetävälle akselille.', 'Mieti, mihin kuorman painopiste siirtyi.', 'VNa 1257/1992'),
  ('masses', 'masses.m7', 'en', 'The rear part of a full trailer was unloaded at a drop. The total mass fell. What can happen?', '["Nothing, the mass fell","The drive axle can be overloaded","The trailer bogie is overloaded","The steer axle lifts off"]'::jsonb, 1, 'The remaining load is now nearer the fifth wheel, so a bigger share of it goes to the tractor, especially the drive axle.', 'Think where the load’s centre of gravity moved.', 'VNa 1257/1992'),
  ('masses', 'masses.m7', 'et', 'Täis haagisest laaditi vahepunktis maha tagumine osa. Mass vähenes. Mis võib juhtuda?', '["Mitte midagi, mass vähenes","Veotelg võib üle koormuda","Haagise telik koormub üle","Juhttelg tõuseb lahti"]'::jsonb, 1, 'Allesjäänud koorem on nüüd sadulale lähemal, seega suurem osa sellest läheb vedukile, eriti veoteljele.', 'Mõtle, kuhu koorma raskuskese liikus.', 'VNa 1257/1992'),
  ('masses', 'masses.m7', 'ru', 'На промежуточной точке из полного прицепа выгрузили заднюю часть. Масса упала. Что может случиться?', '["Ничего, масса же упала","Перегрузится ведущая ось","Перегрузится тележка прицепа","Управляемая ось оторвётся"]'::jsonb, 1, 'Оставшийся груз теперь ближе к седлу, поэтому большая его доля приходится на тягач, прежде всего на ведущую ось.', 'Подумайте, куда сместился центр тяжести груза.', 'ПП 1257/1992 (Финляндия)'),
  ('masses', 'masses.m7', 'sv', 'Den bakre delen av en full trailer lossades vid ett stopp. Totalvikten minskade. Vad kan hända?', '["Inget, vikten minskade","Drivaxeln kan bli överlastad","Trailerns boggi blir överlastad","Styraxeln lyfter"]'::jsonb, 1, 'Den kvarvarande lasten ligger nu närmare vändskivan, så en större del av den hamnar på dragbilen, särskilt drivaxeln.', 'Tänk på var lastens tyngdpunkt hamnade.', 'VNa 1257/1992'),
  ('masses', 'masses.m7', 'lv', 'No pilnas piekabes starppunktā izkrāva aizmugurējo daļu. Masa samazinājās. Kas var notikt?', '["Nekas, masa samazinājās","Dzenošā ass var pārslogoties","Pārslogojas piekabes ratiņi","Stūrējamā ass paceļas"]'::jsonb, 1, 'Atlikusī krava tagad ir tuvāk seglu sakabei, tāpēc lielāka tās daļa nonāk uz vilcēja, īpaši uz dzenošās ass.', 'Padomā, kur pārvietojās kravas smaguma centrs.', 'VNa 1257/1992'),
  ('masses', 'masses.m7', 'lt', 'Tarpiniame taške iš pilnos priekabos iškrovė galinę dalį. Masė sumažėjo. Kas gali nutikti?', '["Nieko, masė sumažėjo","Gali būti perkrauta varančioji ašis","Perkraunamas priekabos vežimėlis","Vairuojamoji ašis pakyla"]'::jsonb, 1, 'Likęs krovinys dabar arčiau balno, todėl didesnė jo dalis tenka vilkikui, ypač varančiajai ašiai.', 'Pagalvok, kur pasislinko krovinio svorio centras.', 'VNa 1257/1992'),
  ('masses', 'masses.m7', 'pl', 'W punkcie pośrednim z pełnej naczepy rozładowano tylną część. Masa spadła. Co może się stać?', '["Nic, masa spadła","Oś napędowa może być przeciążona","Wózek naczepy jest przeciążony","Oś kierowana się uniesie"]'::jsonb, 1, 'Pozostały ładunek jest teraz bliżej siodła, więc większa jego część przypada na ciągnik, zwłaszcza na oś napędową.', 'Pomyśl, gdzie przesunął się środek ciężkości ładunku.', 'VNa 1257/1992'),
  ('masses', 'masses.m7', 'nb', 'Den bakre delen av en full trailer ble losset på et stopp. Totalvekten gikk ned. Hva kan skje?', '["Ingenting, vekten gikk ned","Drivakselen kan bli overlastet","Trailerens boggi blir overlastet","Styreakselen løfter seg"]'::jsonb, 1, 'Den gjenværende lasten ligger nå nærmere skjøten, så en større del av den havner på trekkvognen, særlig drivakselen.', 'Tenk på hvor lastens tyngdepunkt flyttet seg.', 'VNa 1257/1992'),
  ('masses', 'masses.m7', 'da', 'Den bageste del af en fuld trailer blev losset ved et stop. Totalvægten faldt. Hvad kan der ske?', '["Ingenting, vægten faldt","Drivakslen kan blive overlæsset","Trailerens boggi bliver overlæsset","Styreakslen løfter sig"]'::jsonb, 1, 'Den resterende last ligger nu tættere på koblingen, så en større del af den ender på trækkeren, især drivakslen.', 'Tænk på, hvor lastens tyngdepunkt flyttede sig.', 'VNa 1257/1992'),
  ('masses', 'masses.m8', 'fi', 'Kuorma punnittiin lähettäjän ilmoituksen mukaan. Tarkastuksessa auto on ylikuormattu. Kuka vastaa?', '["Vain lähettäjä","Vain kuljetusliike","Myös kuljettaja","Ei kukaan, jos rahtikirjassa on paino"]'::jsonb, 2, 'Kuljettaja vastaa ajoneuvon kuormituksesta tiellä. Seuraamus voi kohdistua myös kuljetusliikkeeseen ja lähettäjään.', 'Tarkastuksessa kysytään ensin kuljettajalta.', 'Tieliikennelaki 729/2018'),
  ('masses', 'masses.m8', 'en', 'The load was declared by the shipper. At a check the truck is overloaded. Who is responsible?', '["Only the shipper","Only the carrier","The driver too","No one, if the weight is on the CMR"]'::jsonb, 2, 'The driver is responsible for the vehicle’s loading on the road. Sanctions can also hit the carrier and the shipper.', 'At a check, the driver is asked first.', 'Tieliikennelaki 729/2018'),
  ('masses', 'masses.m8', 'et', 'Koorma kaalu teatas saatja. Kontrollis on auto üle koormatud. Kes vastutab?', '["Ainult saatja","Ainult vedaja","Ka juht","Mitte keegi, kui kaal on CMR-is"]'::jsonb, 2, 'Juht vastutab sõiduki koormamise eest teel. Sanktsioonid võivad puudutada ka vedajat ja saatjat.', 'Kontrollis küsitakse kõigepealt juhilt.', 'Tieliikennelaki 729/2018'),
  ('masses', 'masses.m8', 'ru', 'Вес груза указал отправитель. На проверке машина перегружена. Кто отвечает?', '["Только отправитель","Только перевозчик","Водитель тоже","Никто, если вес указан в CMR"]'::jsonb, 2, 'Водитель отвечает за загрузку машины на дороге. Санкции могут коснуться также перевозчика и отправителя.', 'На проверке спрашивают сначала с водителя.', 'Закон о дорожном движении 729/2018'),
  ('masses', 'masses.m8', 'sv', 'Vikten uppgavs av avsändaren. Vid en kontroll är bilen överlastad. Vem ansvarar?', '["Bara avsändaren","Bara åkeriet","Även föraren","Ingen, om vikten står i CMR"]'::jsonb, 2, 'Föraren ansvarar för fordonets lastning på vägen. Påföljder kan också drabba åkeriet och avsändaren.', 'Vid en kontroll frågar man först föraren.', 'Tieliikennelaki 729/2018'),
  ('masses', 'masses.m8', 'lv', 'Kravas svaru norādīja nosūtītājs. Pārbaudē auto ir pārslogots. Kas atbild?', '["Tikai nosūtītājs","Tikai pārvadātājs","Arī vadītājs","Neviens, ja svars ir CMR"]'::jsonb, 2, 'Vadītājs atbild par transportlīdzekļa noslodzi uz ceļa. Sankcijas var skart arī pārvadātāju un nosūtītāju.', 'Pārbaudē vispirms jautā vadītājam.', 'Tieliikennelaki 729/2018'),
  ('masses', 'masses.m8', 'lt', 'Krovinio svorį nurodė siuntėjas. Patikrinimo metu automobilis perkrautas. Kas atsako?', '["Tik siuntėjas","Tik vežėjas","Ir vairuotojas","Niekas, jei svoris nurodytas CMR"]'::jsonb, 2, 'Vairuotojas atsako už transporto priemonės pakrovimą kelyje. Sankcijos gali paliesti ir vežėją bei siuntėją.', 'Patikrinimo metu pirmiausia klausia vairuotojo.', 'Tieliikennelaki 729/2018'),
  ('masses', 'masses.m8', 'pl', 'Masę ładunku podał nadawca. Na kontroli auto jest przeciążone. Kto odpowiada?', '["Tylko nadawca","Tylko przewoźnik","Również kierowca","Nikt, jeśli masa jest w CMR"]'::jsonb, 2, 'Kierowca odpowiada za obciążenie pojazdu na drodze. Sankcje mogą dotknąć też przewoźnika i nadawcę.', 'Na kontroli najpierw pyta się kierowcę.', 'Tieliikennelaki 729/2018'),
  ('masses', 'masses.m8', 'nb', 'Vekten ble oppgitt av avsenderen. På en kontroll er bilen overlastet. Hvem har ansvaret?', '["Bare avsenderen","Bare transportøren","Også sjåføren","Ingen, hvis vekten står i CMR"]'::jsonb, 2, 'Sjåføren har ansvar for kjøretøyets last på veien. Reaksjoner kan også ramme transportøren og avsenderen.', 'På en kontroll spør de sjåføren først.', 'Tieliikennelaki 729/2018'),
  ('masses', 'masses.m8', 'da', 'Vægten blev oplyst af afsenderen. Ved en kontrol er bilen overlæsset. Hvem har ansvaret?', '["Kun afsenderen","Kun vognmanden","Også chaufføren","Ingen, hvis vægten står i CMR"]'::jsonb, 2, 'Chaufføren har ansvaret for køretøjets last på vejen. Sanktioner kan også ramme vognmanden og afsenderen.', 'Ved en kontrol spørger man chaufføren først.', 'Tieliikennelaki 729/2018'),
  ('masses', 'masses.m9', 'fi', 'Rekisteriotteen kokonaismassa on pienempi kuin laissa sallittu. Kumpaa noudatat?', '["Laissa sallittua","Pienempää, rekisteriotteen massaa","Suurempaa","Niiden keskiarvoa"]'::jsonb, 1, 'Aina noudatetaan pienintä rajaa: lakia, rekisteriotteen massaa tai tien painorajoitusta.', 'Ajoneuvo ei voi kantaa enempää kuin sille on hyväksytty.', 'VNa 1257/1992'),
  ('masses', 'masses.m9', 'en', 'The registered maximum mass is lower than the legal limit. Which do you follow?', '["The legal limit","The lower, registered mass","The higher one","Their average"]'::jsonb, 1, 'The lowest limit always applies: the law, the registered mass or the road’s weight restriction.', 'A vehicle cannot carry more than it is approved for.', 'VNa 1257/1992'),
  ('masses', 'masses.m9', 'et', 'Registreerimistunnistuse täismass on väiksem kui seadusega lubatud. Kumba järgid?', '["Seadusega lubatut","Väiksemat, tunnistuse massi","Suuremat","Nende keskmist"]'::jsonb, 1, 'Alati kehtib väikseim piir: seadus, registreeritud mass või tee massipiirang.', 'Sõiduk ei saa kanda rohkem, kui talle on heaks kiidetud.', 'VNa 1257/1992'),
  ('masses', 'masses.m9', 'ru', 'Масса по свидетельству о регистрации меньше разрешённой законом. Что соблюдать?', '["Предел по закону","Меньшую, по свидетельству","Большую","Среднее"]'::jsonb, 1, 'Всегда действует наименьший предел: закон, масса по свидетельству или ограничение на дороге.', 'Машина не может везти больше, чем на неё одобрено.', 'ПП 1257/1992 (Финляндия)'),
  ('masses', 'masses.m9', 'sv', 'Registreringsbevisets totalvikt är lägre än den lagliga gränsen. Vilken följer du?', '["Den lagliga gränsen","Den lägre, registrerade vikten","Den högre","Genomsnittet"]'::jsonb, 1, 'Den lägsta gränsen gäller alltid: lagen, den registrerade vikten eller vägens viktbegränsning.', 'Ett fordon får inte bära mer än det är godkänt för.', 'VNa 1257/1992'),
  ('masses', 'masses.m9', 'lv', 'Reģistrācijas apliecības pilnā masa ir mazāka par likumā atļauto. Ko ievēro?', '["Likumā atļauto","Mazāko, apliecības masu","Lielāko","To vidējo"]'::jsonb, 1, 'Vienmēr piemēro mazāko robežu: likumu, reģistrēto masu vai ceļa masas ierobežojumu.', 'Transportlīdzeklis nevar nest vairāk, nekā tam apstiprināts.', 'VNa 1257/1992'),
  ('masses', 'masses.m9', 'lt', 'Registracijos liudijime nurodyta masė mažesnė nei leidžia įstatymas. Kurios laikaisi?', '["Įstatyme leidžiamos","Mažesnės, liudijimo masės","Didesnės","Jų vidurkio"]'::jsonb, 1, 'Visada taikoma mažiausia riba: įstatymas, registruota masė ar kelio masės ribojimas.', 'Transporto priemonė negali vežti daugiau, nei jai patvirtinta.', 'VNa 1257/1992'),
  ('masses', 'masses.m9', 'pl', 'Masa w dowodzie rejestracyjnym jest mniejsza niż dopuszczalna prawem. Której przestrzegasz?', '["Dopuszczalnej prawem","Mniejszej, z dowodu","Większej","Ich średniej"]'::jsonb, 1, 'Zawsze obowiązuje najniższy limit: prawo, masa z dowodu lub ograniczenie na drodze.', 'Pojazd nie może przewieźć więcej, niż mu dopuszczono.', 'VNa 1257/1992'),
  ('masses', 'masses.m9', 'nb', 'Vognkortets totalvekt er lavere enn den lovlige grensen. Hvilken følger du?', '["Den lovlige grensen","Den lavere, vognkortets vekt","Den høyeste","Gjennomsnittet"]'::jsonb, 1, 'Den laveste grensen gjelder alltid: loven, registrert vekt eller veiens vektbegrensning.', 'Et kjøretøy kan ikke bære mer enn det er godkjent for.', 'VNa 1257/1992'),
  ('masses', 'masses.m9', 'da', 'Registreringsattestens totalvægt er lavere end den lovlige grænse. Hvilken følger du?', '["Den lovlige grænse","Den lavere, registrerede vægt","Den højeste","Gennemsnittet"]'::jsonb, 1, 'Den laveste grænse gælder altid: loven, den registrerede vægt eller vejens vægtbegrænsning.', 'Et køretøj må ikke bære mere, end det er godkendt til.', 'VNa 1257/1992'),
  ('masses', 'masses.m10', 'fi', 'Miksi ylikuormitus on vaarallinen, vaikka auto jaksaisi vetää?', '["Se kuluttaa vain polttoainetta","Se on vaarallinen vain sakon takia","Jarrutusmatka pitenee ja renkaat ja jarrut ylikuormittuvat","Se ei ole vaarallinen alle 10 %"]'::jsonb, 2, 'Ylimääräinen massa pidentää jarrutusmatkaa, kuumentaa jarruja ja ylikuormittaa renkaita. Tie ja sillat kuluvat nopeammin.', 'Mieti jarrutusta alamäessä.', 'VNa 1257/1992'),
  ('masses', 'masses.m10', 'en', 'Why is overloading dangerous even if the truck can still pull it?', '["It only uses more fuel","It is dangerous only because of the fine","Braking distance grows and tyres and brakes are overloaded","It is not dangerous under 10%"]'::jsonb, 2, 'Extra mass lengthens the braking distance, overheats the brakes and overloads the tyres. Roads and bridges wear faster.', 'Think of braking downhill.', 'VNa 1257/1992'),
  ('masses', 'masses.m10', 'et', 'Miks on ülekoormus ohtlik, isegi kui auto jõuab vedada?', '["See kulutab ainult kütust","See on ohtlik ainult trahvi pärast","Pidurdusteekond pikeneb ning rehvid ja pidurid koormuvad üle","Alla 10% pole see ohtlik"]'::jsonb, 2, 'Lisamass pikendab pidurdusteekonda, kuumutab pidureid ja koormab rehve üle. Teed ja sillad kuluvad kiiremini.', 'Mõtle pidurdamisele allamäge.', 'VNa 1257/1992'),
  ('masses', 'masses.m10', 'ru', 'Почему перегруз опасен, даже если машина тянет?', '["Только расход топлива","Опасен только штрафом","Растёт тормозной путь, перегружаются шины и тормоза","Не опасен до 10 %"]'::jsonb, 2, 'Лишняя масса удлиняет тормозной путь, перегревает тормоза и перегружает шины. Дороги и мосты изнашиваются быстрее.', 'Подумайте о торможении на спуске.', 'ПП 1257/1992 (Финляндия)'),
  ('masses', 'masses.m10', 'sv', 'Varför är överlast farlig även om bilen orkar dra?', '["Den drar bara mer bränsle","Den är farlig bara på grund av böterna","Bromssträckan blir längre och däck och bromsar överbelastas","Den är inte farlig under 10 %"]'::jsonb, 2, 'Extra vikt förlänger bromssträckan, överhettar bromsarna och överbelastar däcken. Vägar och broar slits fortare.', 'Tänk på inbromsning i nedförsbacke.', 'VNa 1257/1992'),
  ('masses', 'masses.m10', 'lv', 'Kāpēc pārslodze ir bīstama, pat ja auto spēj vilkt?', '["Tā tikai patērē degvielu","Tā ir bīstama tikai soda dēļ","Bremzēšanas ceļš pagarinās, riepas un bremzes pārslogojas","Līdz 10% tā nav bīstama"]'::jsonb, 2, 'Liekā masa pagarina bremzēšanas ceļu, pārkarsē bremzes un pārslogo riepas. Ceļi un tilti nolietojas ātrāk.', 'Padomā par bremzēšanu nogāzē.', 'VNa 1257/1992'),
  ('masses', 'masses.m10', 'lt', 'Kodėl perkrova pavojinga, net jei automobilis tempia?', '["Tik daugiau kuro","Pavojinga tik dėl baudos","Ilgėja stabdymo kelias, perkraunamos padangos ir stabdžiai","Iki 10 % nepavojinga"]'::jsonb, 2, 'Papildoma masė pailgina stabdymo kelią, perkaitina stabdžius ir perkrauna padangas. Keliai ir tiltai dėvisi greičiau.', 'Pagalvok apie stabdymą nuokalnėje.', 'VNa 1257/1992'),
  ('masses', 'masses.m10', 'pl', 'Dlaczego przeciążenie jest niebezpieczne, nawet jeśli auto ciągnie?', '["Zużywa tylko więcej paliwa","Groźne tylko przez mandat","Wydłuża się droga hamowania, opony i hamulce są przeciążone","Nie jest groźne poniżej 10%"]'::jsonb, 2, 'Dodatkowa masa wydłuża drogę hamowania, przegrzewa hamulce i przeciąża opony. Drogi i mosty szybciej się zużywają.', 'Pomyśl o hamowaniu na zjeździe.', 'VNa 1257/1992'),
  ('masses', 'masses.m10', 'nb', 'Hvorfor er overlast farlig selv om bilen klarer å trekke?', '["Den bruker bare mer drivstoff","Den er farlig bare på grunn av boten","Bremselengden øker og dekk og bremser overbelastes","Den er ikke farlig under 10 %"]'::jsonb, 2, 'Ekstra vekt gir lengre bremselengde, overoppheter bremsene og overbelaster dekkene. Veier og bruer slites raskere.', 'Tenk på bremsing i nedoverbakke.', 'VNa 1257/1992'),
  ('masses', 'masses.m10', 'da', 'Hvorfor er overlæs farligt, selvom bilen kan trække det?', '["Det bruger kun mere brændstof","Det er kun farligt på grund af bøden","Bremselængden øges, og dæk og bremser overbelastes","Det er ikke farligt under 10 %"]'::jsonb, 2, 'Ekstra vægt forlænger bremselængden, overopheder bremserne og overbelaster dækkene. Veje og broer slides hurtigere.', 'Tænk på opbremsning ned ad bakke.', 'VNa 1257/1992'),
  ('tech', 'tech.t1', 'fi', 'Milloin ajoneuvon lähtötarkastus tehdään?', '["Kerran viikossa","Ennen lähtöä joka päivä ja aina kytkennän jälkeen","Vain katsastuksen yhteydessä","Vain, jos varoitusvalo palaa"]'::jsonb, 1, 'Kuljettajan on varmistettava ajoneuvon kunto ennen ajoa. Päivittäinen tarkastus tehdään ennen lähtöä ja aina, kun perävaunu kytketään.', 'Katsastus kerran vuodessa ei riitä päivittäiseen ajoon.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t1', 'en', 'When is the pre-departure check done?', '["Once a week","Before departure every day and after every coupling","Only at the annual inspection","Only if a warning light is on"]'::jsonb, 1, 'The driver must make sure the vehicle is roadworthy before driving. The daily check is done before departure and whenever a trailer is coupled.', 'An annual inspection is not enough for daily driving.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t1', 'et', 'Millal tehakse väljasõidueelne kontroll?', '["Kord nädalas","Iga päev enne väljasõitu ja pärast igat haakimist","Ainult tehnoülevaatusel","Ainult siis, kui hoiatustuli põleb"]'::jsonb, 1, 'Juht peab enne sõitu veenduma sõiduki korrasolekus. Igapäevane kontroll tehakse enne väljasõitu ja alati pärast haagise haakimist.', 'Iga-aastasest ülevaatusest igapäevaseks sõiduks ei piisa.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t1', 'ru', 'Когда проводят осмотр перед выездом?', '["Раз в неделю","Каждый день перед выездом и после каждой сцепки","Только на техосмотре","Только если горит лампа"]'::jsonb, 1, 'Водитель обязан убедиться в исправности машины перед поездкой. Ежедневный осмотр делают перед выездом и после каждой сцепки с прицепом.', 'Ежегодного техосмотра для ежедневной работы мало.', 'Закон о дорожном движении 729/2018 (Финляндия)'),
  ('tech', 'tech.t1', 'sv', 'När görs kontrollen före avfärd?', '["En gång i veckan","Före avfärd varje dag och efter varje koppling","Bara vid besiktningen","Bara om en varningslampa lyser"]'::jsonb, 1, 'Föraren ska försäkra sig om att fordonet är i trafikdugligt skick före körning. Den dagliga kontrollen görs före avfärd och varje gång en släpvagn kopplas.', 'En årlig besiktning räcker inte för daglig körning.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t1', 'lv', 'Kad veic apskati pirms izbraukšanas?', '["Reizi nedēļā","Katru dienu pirms izbraukšanas un pēc katras sakabināšanas","Tikai tehniskajā apskatē","Tikai tad, ja deg brīdinājuma lampiņa"]'::jsonb, 1, 'Vadītājam pirms brauciena jāpārliecinās par transportlīdzekļa tehnisko stāvokli. Ikdienas apskati veic pirms izbraukšanas un katru reizi, kad piekabina piekabi.', 'Ikgadējā apskate ikdienas braukšanai nepietiek.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t1', 'lt', 'Kada atliekama apžiūra prieš išvykstant?', '["Kartą per savaitę","Kasdien prieš išvykstant ir po kiekvieno sukabinimo","Tik techninės apžiūros metu","Tik jei dega įspėjamoji lemputė"]'::jsonb, 1, 'Vairuotojas prieš važiuodamas turi įsitikinti, kad transporto priemonė tvarkinga. Kasdienė apžiūra atliekama prieš išvykstant ir visada prikabinus priekabą.', 'Metinės apžiūros kasdieniam važiavimui nepakanka.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t1', 'pl', 'Kiedy wykonuje się kontrolę przed wyjazdem?', '["Raz w tygodniu","Codziennie przed wyjazdem i po każdym sprzęgnięciu","Tylko przy przeglądzie","Tylko gdy świeci kontrolka"]'::jsonb, 1, 'Kierowca musi upewnić się przed jazdą, że pojazd jest sprawny. Codzienna kontrola odbywa się przed wyjazdem i za każdym razem po sprzęgnięciu naczepy.', 'Coroczny przegląd nie wystarcza do codziennej jazdy.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t1', 'nb', 'Når gjøres kontrollen før avreise?', '["Én gang i uken","Før avreise hver dag og etter hver kopling","Bare ved EU-kontrollen","Bare hvis en varsellampe lyser"]'::jsonb, 1, 'Sjåføren skal forsikre seg om at kjøretøyet er i forsvarlig stand før kjøring. Den daglige kontrollen gjøres før avreise og hver gang en tilhenger koples.', 'En årlig kontroll holder ikke for daglig kjøring.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t1', 'da', 'Hvornår laves eftersynet før afgang?', '["Én gang om ugen","Før afgang hver dag og efter hver kobling","Kun ved synet","Kun hvis en advarselslampe lyser"]'::jsonb, 1, 'Chaufføren skal sikre sig, at køretøjet er i forsvarlig stand før kørsel. Det daglige eftersyn laves før afgang og hver gang en påhængsvogn kobles på.', 'Et årligt syn er ikke nok til daglig kørsel.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t2', 'fi', 'Pyöränmuttereiden kiristysosoittimista yksi osoittaa eri suuntaan kuin muut. Mitä se tarkoittaa?', '["Osoitin on vain koriste","Mutteri on liian tiukalla","Mutteri on voinut löystyä","Rengas on vaihdettava"]'::jsonb, 2, 'Osoittimet asennetaan samaan linjaan. Jos yksi on kääntynyt, mutteri on voinut löystyä. Tarkista kiristys ennen ajoa.', 'Osoitin kääntyy mutterin mukana.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t2', 'en', 'One wheel nut indicator points in a different direction from the others. What does it mean?', '["The indicator is just decoration","The nut is too tight","The nut may have loosened","The tyre must be replaced"]'::jsonb, 2, 'The indicators are fitted in line. If one has turned, the nut may have loosened. Check the torque before driving.', 'The indicator turns with the nut.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t2', 'et', 'Üks rattamutri pingutusnäidik näitab teistest erinevas suunas. Mida see tähendab?', '["Näidik on lihtsalt kaunistus","Mutter on liiga pingul","Mutter võib olla lõdvenenud","Rehv tuleb vahetada"]'::jsonb, 2, 'Näidikud paigaldatakse ühele joonele. Kui üks on pöördunud, võib mutter olla lõdvenenud. Kontrolli pingutust enne sõitu.', 'Näidik pöörleb koos mutriga.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t2', 'ru', 'Один указатель затяжки колёсных гаек смотрит в другую сторону. Что это значит?', '["Указатель — просто украшение","Гайка перетянута","Гайка могла ослабнуть","Шину нужно менять"]'::jsonb, 2, 'Указатели ставят по одной линии. Если один повернулся, гайка могла открутиться. Проверьте затяжку до выезда.', 'Указатель поворачивается вместе с гайкой.', 'Закон о дорожном движении 729/2018 (Финляндия)'),
  ('tech', 'tech.t2', 'sv', 'En av muttermarkörerna pekar åt ett annat håll än de andra. Vad betyder det?', '["Markören är bara dekoration","Muttern är för hårt åtdragen","Muttern kan ha lossnat","Däcket måste bytas"]'::jsonb, 2, 'Markörerna monteras i linje. Har en vridit sig kan muttern ha lossnat. Kontrollera åtdragningen före körning.', 'Markören vrids med muttern.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t2', 'lv', 'Viens riteņa uzgriežņa indikators rāda citā virzienā nekā pārējie. Ko tas nozīmē?', '["Indikators ir tikai rotājums","Uzgrieznis pievilkts par stipru","Uzgrieznis var būt atskrūvējies","Riepa jāmaina"]'::jsonb, 2, 'Indikatorus uzstāda vienā līnijā. Ja viens pagriezies, uzgrieznis var būt atskrūvējies. Pārbaudi pievilkšanu pirms brauciena.', 'Indikators griežas kopā ar uzgriezni.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t2', 'lt', 'Vienas rato veržlės indikatorius rodo kita kryptimi nei kiti. Ką tai reiškia?', '["Indikatorius tik puošmena","Veržlė per stipriai priveržta","Veržlė galėjo atsilaisvinti","Padangą reikia keisti"]'::jsonb, 2, 'Indikatoriai montuojami vienoje linijoje. Jei vienas pasisuko, veržlė galėjo atsilaisvinti. Patikrink priveržimą prieš važiuojant.', 'Indikatorius sukasi kartu su veržle.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t2', 'pl', 'Jeden wskaźnik nakrętki koła wskazuje inny kierunek niż pozostałe. Co to znaczy?', '["Wskaźnik to tylko ozdoba","Nakrętka jest za mocno dokręcona","Nakrętka mogła się poluzować","Oponę trzeba wymienić"]'::jsonb, 2, 'Wskaźniki montuje się w jednej linii. Jeśli jeden się obrócił, nakrętka mogła się poluzować. Sprawdź dokręcenie przed jazdą.', 'Wskaźnik obraca się razem z nakrętką.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t2', 'nb', 'En av mutterindikatorene peker en annen vei enn de andre. Hva betyr det?', '["Indikatoren er bare pynt","Mutteren er for hardt tiltrukket","Mutteren kan ha løsnet","Dekket må byttes"]'::jsonb, 2, 'Indikatorene monteres på linje. Har én vridd seg, kan mutteren ha løsnet. Sjekk tiltrekkingen før kjøring.', 'Indikatoren vrir seg med mutteren.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t2', 'da', 'En af møtrikindikatorerne peger en anden vej end de andre. Hvad betyder det?', '["Indikatoren er bare pynt","Møtrikken er spændt for hårdt","Møtrikken kan være løsnet","Dækket skal skiftes"]'::jsonb, 2, 'Indikatorerne monteres på linje. Er én drejet, kan møtrikken være løsnet. Kontrollér tilspændingen før kørsel.', 'Indikatoren drejer med møtrikken.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t3', 'fi', 'Pyöränmutterin ympäriltä valuu ruskea raita. Mitä se kertoo?', '["Vanteen maali on kulunut","Mutteri voi olla löysällä","Jarrut ovat kuumat","Ei mitään, se on normaalia"]'::jsonb, 1, 'Ruosteraita mutterin ympärillä syntyy, kun mutteri liikkuu. Kiristä ja tarkista pyörä ennen ajoa.', 'Liike synnyttää hankaumaa ja ruostetta.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t3', 'en', 'A brown streak runs from around a wheel nut. What does it tell you?', '["The rim paint is worn","The nut may be loose","The brakes are hot","Nothing, it is normal"]'::jsonb, 1, 'A rust streak around a nut appears when the nut moves. Tighten and check the wheel before driving.', 'Movement causes wear and rust.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t3', 'et', 'Rattamutri ümbert jookseb pruun triip. Mida see näitab?', '["Velje värv on kulunud","Mutter võib olla lõtv","Pidurid on kuumad","Mitte midagi, see on normaalne"]'::jsonb, 1, 'Roostetriip mutri ümber tekib, kui mutter liigub. Pinguta ja kontrolli ratast enne sõitu.', 'Liikumine tekitab hõõrdumist ja roostet.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t3', 'ru', 'От колёсной гайки тянется рыжий подтёк. О чём это говорит?', '["Стёрлась краска диска","Гайка может быть ослаблена","Тормоза горячие","Ни о чём, это нормально"]'::jsonb, 1, 'Ржавый подтёк вокруг гайки появляется, когда гайка двигается. Подтяните и проверьте колесо до выезда.', 'Движение даёт трение и ржавчину.', 'Закон о дорожном движении 729/2018 (Финляндия)'),
  ('tech', 'tech.t3', 'sv', 'En brun rand rinner från en hjulmutter. Vad säger den?', '["Fälgens färg är nött","Muttern kan vara lös","Bromsarna är varma","Ingenting, det är normalt"]'::jsonb, 1, 'En roststrimma runt en mutter uppstår när muttern rör sig. Dra åt och kontrollera hjulet före körning.', 'Rörelse ger nötning och rost.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t3', 'lv', 'No riteņa uzgriežņa tek brūna strīpa. Ko tā nozīmē?', '["Diska krāsa nodilusi","Uzgrieznis var būt vaļīgs","Bremzes ir karstas","Neko, tas ir normāli"]'::jsonb, 1, 'Rūsas strīpa ap uzgriezni rodas, kad uzgrieznis kustas. Pievelc un pārbaudi riteni pirms brauciena.', 'Kustība rada berzi un rūsu.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t3', 'lt', 'Nuo rato veržlės teka ruda juosta. Ką ji rodo?', '["Nusitrynė ratlankio dažai","Veržlė gali būti atsilaisvinusi","Stabdžiai karšti","Nieko, tai normalu"]'::jsonb, 1, 'Rūdžių juosta aplink veržlę atsiranda, kai veržlė juda. Priveržk ir patikrink ratą prieš važiuojant.', 'Judėjimas sukelia trintį ir rūdis.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t3', 'pl', 'Wokół nakrętki koła spływa brązowa smuga. Co to oznacza?', '["Wytarła się farba felgi","Nakrętka może być luźna","Hamulce są gorące","Nic, to normalne"]'::jsonb, 1, 'Rdzawa smuga wokół nakrętki pojawia się, gdy nakrętka się rusza. Dokręć i sprawdź koło przed jazdą.', 'Ruch powoduje tarcie i rdzę.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t3', 'nb', 'En brun stripe renner fra en hjulmutter. Hva forteller den?', '["Felgmalingen er slitt","Mutteren kan være løs","Bremsene er varme","Ingenting, det er normalt"]'::jsonb, 1, 'En ruststripe rundt en mutter oppstår når mutteren beveger seg. Trekk til og sjekk hjulet før kjøring.', 'Bevegelse gir slitasje og rust.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t3', 'da', 'En brun stribe løber fra en hjulmøtrik. Hvad fortæller den?', '["Fælgens maling er slidt","Møtrikken kan være løs","Bremserne er varme","Ingenting, det er normalt"]'::jsonb, 1, 'En ruststribe omkring en møtrik opstår, når møtrikken bevæger sig. Spænd og kontrollér hjulet før kørsel.', 'Bevægelse giver slid og rust.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t4', 'fi', 'Kun moottori sammuu, kuulet jatkuvan sihinän perävaunun kohdalta. Mitä teet?', '["Selvitän vuodon ennen lähtöä","Lähden, paine riittää kyllä","Nostan moottorin kierroksia","Ilmoitan asiasta viikon lopussa"]'::jsonb, 0, 'Sihinä on ilmavuoto. Jarruilman vuoto voi estää perävaunun jarrujen toiminnan. Vika selvitetään ennen lähtöä.', 'Jarrut toimivat paineilmalla.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t4', 'en', 'When the engine stops you hear continuous hissing at the trailer. What do you do?', '["Find the leak before departure","Leave, the pressure will do","Raise the engine revs","Report it at the end of the week"]'::jsonb, 0, 'Hissing is an air leak. A brake air leak can stop the trailer brakes working. The fault is found before departure.', 'The brakes work on compressed air.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t4', 'et', 'Mootori seiskudes kuuled haagise juurest pidevat sisinat. Mida teed?', '["Selgitan lekke enne väljasõitu välja","Sõidan, rõhku piisab","Tõstan pöördeid","Teatan nädala lõpus"]'::jsonb, 0, 'Sisin on õhuleke. Piduriõhu leke võib haagise pidurid rivist välja viia. Rike selgitatakse enne väljasõitu.', 'Pidurid töötavad suruõhuga.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t4', 'ru', 'Когда двигатель заглох, у прицепа слышно постоянное шипение. Что делаете?', '["Ищу утечку до выезда","Еду, давления хватит","Поднимаю обороты","Сообщу в конце недели"]'::jsonb, 0, 'Шипение — утечка воздуха. Утечка в тормозной системе может вывести из строя тормоза прицепа. Неисправность выясняют до выезда.', 'Тормоза работают на сжатом воздухе.', 'Закон о дорожном движении 729/2018 (Финляндия)'),
  ('tech', 'tech.t4', 'sv', 'När motorn stängs av hör du ett konstant väsande vid trailern. Vad gör du?', '["Letar upp läckan före avfärd","Kör, trycket räcker","Varvar upp motorn","Rapporterar i slutet av veckan"]'::jsonb, 0, 'Väsandet är en luftläcka. En läcka i bromsluften kan göra att trailerns bromsar slutar fungera. Felet utreds före avfärd.', 'Bromsarna fungerar med tryckluft.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t4', 'lv', 'Kad dzinējs apstājas, pie piekabes dzirdama nepārtraukta šņākšana. Ko dari?', '["Atrodu noplūdi pirms izbraukšanas","Braucu, spiediena pietiks","Palielinu apgriezienus","Paziņošu nedēļas beigās"]'::jsonb, 0, 'Šņākšana ir gaisa noplūde. Bremžu gaisa noplūde var atslēgt piekabes bremzes. Bojājumu noskaidro pirms izbraukšanas.', 'Bremzes darbojas ar saspiestu gaisu.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t4', 'lt', 'Išjungus variklį prie priekabos girdisi nuolatinis šnypštimas. Ką darai?', '["Surandu nuotėkį prieš išvykdamas","Važiuoju, slėgio užteks","Padidinu apsukas","Pranešiu savaitės pabaigoje"]'::jsonb, 0, 'Šnypštimas — oro nuotėkis. Stabdžių oro nuotėkis gali išjungti priekabos stabdžius. Gedimas išsiaiškinamas prieš išvykstant.', 'Stabdžiai veikia suslėgtu oru.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t4', 'pl', 'Po zgaszeniu silnika przy naczepie słychać ciągły syk. Co robisz?', '["Szukam wycieku przed wyjazdem","Jadę, ciśnienia wystarczy","Podnoszę obroty","Zgłoszę pod koniec tygodnia"]'::jsonb, 0, 'Syk to wyciek powietrza. Wyciek powietrza hamulcowego może wyłączyć hamulce naczepy. Usterkę wyjaśnia się przed wyjazdem.', 'Hamulce działają na sprężone powietrze.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t4', 'nb', 'Når motoren stopper, hører du en konstant susing ved traileren. Hva gjør du?', '["Finner lekkasjen før avreise","Kjører, trykket holder","Øker turtallet","Melder fra i slutten av uken"]'::jsonb, 0, 'Susingen er en luftlekkasje. En lekkasje i bremseluften kan sette trailerens bremser ut av funksjon. Feilen finnes før avreise.', 'Bremsene virker med trykkluft.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t4', 'da', 'Når motoren stopper, hører du en konstant hvislen ved traileren. Hvad gør du?', '["Finder lækagen før afgang","Kører, trykket rækker","Øger omdrejningerne","Melder det i slutningen af ugen"]'::jsonb, 0, 'Hvislen er en luftlækage. En lækage i bremseluften kan sætte trailerens bremser ud af drift. Fejlen findes før afgang.', 'Bremserne virker med trykluft.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t5', 'fi', 'Kytkit puoliperävaunun. Mitä tarkistat ennen lähtöä?', '["Vain valot","Vain rekisterikilven","Lukituksen, varmistimen, letkut ja kokeilun vetämällä perävaunun jarrut päällä","Ei mitään, jos kytkentä kuulosti oikealta"]'::jsonb, 2, 'Kytkennän jälkeen tarkistetaan vetopöydän lukitus ja varmistin, ilma- ja sähköliitännät, tukijalat ja kokeillaan kytkentä vetämällä perävaunun jarrut päällä.', 'Ääni ei todista, että lukitus on kiinni.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t5', 'en', 'You have coupled a semi-trailer. What do you check before departure?', '["Only the lights","Only the number plate","Lock, safety catch, lines, and a tug test with the trailer brakes on","Nothing, if the coupling sounded right"]'::jsonb, 2, 'After coupling, check the fifth wheel lock and safety catch, air and electric connections, landing legs, and do a tug test with the trailer brakes applied.', 'A sound does not prove the lock is closed.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t5', 'et', 'Haakisid poolhaagise. Mida kontrollid enne väljasõitu?', '["Ainult tulesid","Ainult numbrimärki","Lukku, kaitset, voolikuid ja katset tõmbega, haagise pidurid peal","Mitte midagi, kui haakimine kõlas õigesti"]'::jsonb, 2, 'Pärast haakimist kontrollitakse sadula lukku ja kaitset, õhu- ja elektriühendusi, tugijalgu ning tehakse tõmbekatse haagise piduritega.', 'Heli ei tõesta, et lukk on kinni.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t5', 'ru', 'Вы сцепили полуприцеп. Что проверяете до выезда?', '["Только свет","Только номер","Замок, предохранитель, шланги и пробный рывок с заторможенным прицепом","Ничего, если щелчок был правильный"]'::jsonb, 2, 'После сцепки проверяют замок седла и предохранитель, воздушные и электрические разъёмы, опоры и делают пробный рывок при заторможенном прицепе.', 'Щелчок не доказывает, что замок закрыт.', 'Закон о дорожном движении 729/2018 (Финляндия)'),
  ('tech', 'tech.t5', 'sv', 'Du har kopplat en påhängsvagn. Vad kontrollerar du före avfärd?', '["Bara belysningen","Bara registreringsskylten","Låset, spärren, slangarna och ett dragprov med trailerns bromsar i","Ingenting, om kopplingen lät rätt"]'::jsonb, 2, 'Efter kopplingen kontrolleras vändskivans lås och spärr, luft- och elanslutningar, stödben, och ett dragprov görs med trailerns bromsar ansatta.', 'Ett ljud bevisar inte att låset är stängt.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t5', 'lv', 'Tu sakabināji puspiekabi. Ko pārbaudi pirms izbraukšanas?', '["Tikai gaismas","Tikai numura zīmi","Slēdzeni, drošinātāju, šļūtenes un vilkšanas pārbaudi ar ieslēgtām piekabes bremzēm","Neko, ja sakabināšana izklausījās pareizi"]'::jsonb, 2, 'Pēc sakabināšanas pārbauda seglu sakabes slēdzeni un drošinātāju, gaisa un elektrības savienojumus, balstus un veic vilkšanas pārbaudi ar ieslēgtām piekabes bremzēm.', 'Skaņa nepierāda, ka slēdzene ir aizvērta.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t5', 'lt', 'Sukabinai puspriekabę. Ką tikrini prieš išvykdamas?', '["Tik žibintus","Tik numerį","Spyną, fiksatorių, žarnas ir tempimo bandymą su įjungtais priekabos stabdžiais","Nieko, jei sukabinimas skambėjo teisingai"]'::jsonb, 2, 'Po sukabinimo tikrinama balno spyna ir fiksatorius, oro ir elektros jungtys, atramos ir atliekamas tempimo bandymas su įjungtais priekabos stabdžiais.', 'Garsas neįrodo, kad spyna užsidarė.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t5', 'pl', 'Sprzęgnąłeś naczepę. Co sprawdzasz przed wyjazdem?', '["Tylko światła","Tylko tablicę","Zamek, zabezpieczenie, przewody i próbę szarpnięciem przy zahamowanej naczepie","Nic, jeśli sprzęgnięcie dobrze brzmiało"]'::jsonb, 2, 'Po sprzęgnięciu sprawdza się zamek siodła i zabezpieczenie, złącza powietrzne i elektryczne, podpory oraz robi próbę szarpnięciem przy zahamowanej naczepie.', 'Dźwięk nie dowodzi, że zamek się zamknął.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t5', 'nb', 'Du har koplet en semitrailer. Hva sjekker du før avreise?', '["Bare lysene","Bare kjennemerket","Låsen, sikringen, slangene og en dra-test med trailerbremsene på","Ingenting, hvis koplingen hørtes riktig ut"]'::jsonb, 2, 'Etter kopling sjekkes skjøtens lås og sikring, luft- og elektriske tilkoblinger, støttebein, og det gjøres en dra-test med trailerbremsene på.', 'En lyd beviser ikke at låsen er stengt.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t5', 'da', 'Du har koblet en sættevogn på. Hvad kontrollerer du før afgang?', '["Kun lyset","Kun nummerpladen","Låsen, sikringen, slangerne og en trækprøve med trailerens bremser på","Ingenting, hvis koblingen lød rigtig"]'::jsonb, 2, 'Efter kobling kontrolleres koblingens lås og sikring, luft- og elforbindelser, støtteben, og der laves en trækprøve med trailerens bremser aktiveret.', 'En lyd beviser ikke, at låsen er lukket.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t6', 'fi', 'Renkaan kyljessä on pullistuma. Mitä teet?', '["Ajan varovasti perille","Lisään painetta","Ajan kunnes rengas tyhjenee","Vaihdan renkaan ennen ajoa"]'::jsonb, 3, 'Pullistuma kertoo kudosvauriosta. Rengas voi räjähtää ajossa, joten sillä ei lähdetä.', 'Pullistuma ei korjaannu itsestään.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t6', 'en', 'There is a bulge in the tyre wall. What do you do?', '["Drive carefully to the destination","Add pressure","Drive until the tyre goes flat","Replace the tyre before driving"]'::jsonb, 3, 'A bulge means carcass damage. The tyre can burst while driving, so you do not leave with it.', 'A bulge does not fix itself.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t6', 'et', 'Rehvi küljel on mõhk. Mida teed?', '["Sõidan ettevaatlikult kohale","Lisan rõhku","Sõidan, kuni rehv tühjeneb","Vahetan rehvi enne sõitu"]'::jsonb, 3, 'Mõhk tähendab karkassi kahjustust. Rehv võib sõidu ajal lõhkeda, sellega ei sõideta.', 'Mõhk ise ei parane.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t6', 'ru', 'На боковине шины грыжа. Что делаете?', '["Аккуратно доезжаю","Подкачиваю","Еду, пока не спустит","Меняю шину до выезда"]'::jsonb, 3, 'Грыжа означает повреждение каркаса. Шина может взорваться на ходу, с ней не выезжают.', 'Грыжа сама не пройдёт.', 'Закон о дорожном движении 729/2018 (Финляндия)'),
  ('tech', 'tech.t6', 'sv', 'Det finns en bula på däcksidan. Vad gör du?', '["Kör försiktigt fram","Fyller på luft","Kör tills däcket är tomt","Byter däcket före körning"]'::jsonb, 3, 'En bula betyder skada i stommen. Däcket kan explodera under körning, så du kör inte med det.', 'En bula läker inte av sig själv.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t6', 'lv', 'Riepas sānos ir izcilnis. Ko dari?', '["Uzmanīgi aizbraucu līdz galam","Piepumpēju","Braucu, līdz riepa saplok","Nomainu riepu pirms brauciena"]'::jsonb, 3, 'Izcilnis nozīmē karkasa bojājumu. Riepa var pārsprāgt braucot, ar to nebrauc.', 'Izcilnis pats nepazudīs.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t6', 'lt', 'Padangos šone išsipūtimas. Ką darai?', '["Atsargiai nuvažiuoju","Pripučiu","Važiuoju, kol nuleis","Pakeičiu padangą prieš važiuodamas"]'::jsonb, 3, 'Išsipūtimas reiškia pažeistą karkasą. Padanga gali sprogti važiuojant, su ja nevažiuojama.', 'Išsipūtimas pats nepranyks.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t6', 'pl', 'Na boku opony jest wybrzuszenie. Co robisz?', '["Ostrożnie dojeżdżam","Dopompowuję","Jadę, aż zejdzie powietrze","Wymieniam oponę przed jazdą"]'::jsonb, 3, 'Wybrzuszenie oznacza uszkodzoną osnowę. Opona może pęknąć w czasie jazdy, więc się z nią nie jeździ.', 'Wybrzuszenie samo nie zniknie.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t6', 'nb', 'Det er en bule på dekksiden. Hva gjør du?', '["Kjører forsiktig fram","Fyller luft","Kjører til dekket er flatt","Bytter dekket før kjøring"]'::jsonb, 3, 'En bule betyr skade i stammen. Dekket kan eksplodere under kjøring, så du kjører ikke med det.', 'En bule går ikke over av seg selv.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t6', 'da', 'Der er en bule på dæksiden. Hvad gør du?', '["Kører forsigtigt frem","Fylder luft på","Kører, til dækket er fladt","Skifter dækket før kørsel"]'::jsonb, 3, 'En bule betyder skade i karkassen. Dækket kan eksplodere under kørsel, så du kører ikke med det.', 'En bule forsvinder ikke af sig selv.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t7', 'fi', 'Ajon aikana syttyy jarrupaineen varoitusvalo. Mitä teet?', '["Jatkan, jos jarrut tuntuvat toimivan","Pysähdyn turvalliseen paikkaan enkä jatka ennen kuin vika on selvitetty","Ajan kovempaa, jotta kompressori ehtii","Kytken varoitusvalon pois"]'::jsonb, 1, 'Matala jarrupaine voi johtaa jarrujen toiminnan heikkenemiseen tai jousijarrujen lukkiutumiseen. Pysähdy turvallisesti ja selvitä vika.', 'Varoitusvalo on viimeinen varoitus ennen vikaa.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t7', 'en', 'While driving the brake pressure warning light comes on. What do you do?', '["Continue if the brakes feel fine","Stop in a safe place and do not continue until the fault is found","Drive faster so the compressor keeps up","Switch off the warning light"]'::jsonb, 1, 'Low brake pressure can weaken the brakes or lock the spring brakes. Stop safely and find the fault.', 'The light is the last warning before failure.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t7', 'et', 'Sõidu ajal süttib piduri rõhu hoiatustuli. Mida teed?', '["Jätkan, kui pidurid tunduvad töötavat","Peatun ohutus kohas ega jätka enne, kui rike on selge","Sõidan kiiremini, et kompressor jõuaks","Lülitan hoiatustule välja"]'::jsonb, 1, 'Madal pidurirõhk võib nõrgendada pidureid või lukustada vedrupidurid. Peatu ohutult ja selgita rike välja.', 'Tuli on viimane hoiatus enne riket.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t7', 'ru', 'В пути загорается лампа давления в тормозах. Что делаете?', '["Еду дальше, если тормоза вроде работают","Останавливаюсь в безопасном месте и не еду, пока не выясню причину","Еду быстрее, чтобы компрессор успевал","Отключаю лампу"]'::jsonb, 1, 'Низкое давление может ослабить тормоза или заблокировать пружинные энергоаккумуляторы. Остановитесь безопасно и найдите неисправность.', 'Лампа — последнее предупреждение перед отказом.', 'Закон о дорожном движении 729/2018 (Финляндия)'),
  ('tech', 'tech.t7', 'sv', 'Under körning tänds varningslampan för bromstryck. Vad gör du?', '["Fortsätter om bromsarna känns bra","Stannar på en säker plats och fortsätter inte förrän felet är utrett","Kör fortare så kompressorn hinner","Stänger av varningslampan"]'::jsonb, 1, 'Lågt bromstryck kan försvaga bromsarna eller låsa fjäderbromsarna. Stanna säkert och ta reda på felet.', 'Lampan är sista varningen före fel.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t7', 'lv', 'Braucot iedegas bremžu spiediena brīdinājuma lampiņa. Ko dari?', '["Turpinu, ja bremzes šķiet darbojamies","Apstājos drošā vietā un neturpinu, kamēr bojājums nav noskaidrots","Braucu ātrāk, lai kompresors paspētu","Izslēdzu lampiņu"]'::jsonb, 1, 'Zems bremžu spiediens var vājināt bremzes vai nobloķēt atsperu bremzes. Apstājies droši un noskaidro bojājumu.', 'Lampiņa ir pēdējais brīdinājums pirms atteices.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t7', 'lt', 'Važiuojant užsidega stabdžių slėgio įspėjamoji lemputė. Ką darai?', '["Važiuoju toliau, jei stabdžiai atrodo veikiantys","Sustoju saugioje vietoje ir nevažiuoju, kol neišsiaiškinu gedimo","Važiuoju greičiau, kad kompresorius spėtų","Išjungiu lemputę"]'::jsonb, 1, 'Žemas stabdžių slėgis gali susilpninti stabdžius arba užblokuoti spyruoklinius stabdžius. Saugiai sustok ir išsiaiškink gedimą.', 'Lemputė — paskutinis įspėjimas prieš gedimą.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t7', 'pl', 'W czasie jazdy zapala się kontrolka ciśnienia w hamulcach. Co robisz?', '["Jadę dalej, jeśli hamulce działają","Zatrzymuję się w bezpiecznym miejscu i nie jadę, dopóki nie wyjaśnię usterki","Jadę szybciej, żeby sprężarka nadążyła","Wyłączam kontrolkę"]'::jsonb, 1, 'Niskie ciśnienie może osłabić hamulce lub zablokować hamulce sprężynowe. Zatrzymaj się bezpiecznie i znajdź usterkę.', 'Kontrolka to ostatnie ostrzeżenie przed awarią.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t7', 'nb', 'Under kjøring tennes varsellampen for bremsetrykk. Hva gjør du?', '["Fortsetter hvis bremsene kjennes greie","Stopper på et trygt sted og fortsetter ikke før feilen er funnet","Kjører fortere så kompressoren henger med","Slår av varsellampen"]'::jsonb, 1, 'Lavt bremsetrykk kan svekke bremsene eller låse fjærbremsene. Stopp trygt og finn feilen.', 'Lampen er siste varsel før feil.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t7', 'da', 'Under kørsel tændes advarselslampen for bremsetryk. Hvad gør du?', '["Fortsætter, hvis bremserne føles fine","Stopper et sikkert sted og fortsætter ikke, før fejlen er fundet","Kører hurtigere, så kompressoren kan følge med","Slukker advarselslampen"]'::jsonb, 1, 'Lavt bremsetryk kan svække bremserne eller låse fjederbremserne. Stop sikkert og find fejlen.', 'Lampen er den sidste advarsel før fejl.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t8', 'fi', 'Mikä on kesärenkaan kulutuspinnan vähimmäissyvyys?', '["1,0 mm","1,6 mm","3,0 mm","5,0 mm"]'::jsonb, 1, 'Kesärenkaan kulutuspinnan on oltava vähintään 1,6 mm. Talvirenkaille on omat, suuremmat vaatimukset.', 'Sama raja kuin henkilöautoilla kesällä.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t8', 'en', 'What is the minimum tread depth of a summer tyre?', '["1.0 mm","1.6 mm","3.0 mm","5.0 mm"]'::jsonb, 1, 'A summer tyre must have at least 1.6 mm of tread. Winter tyres have their own, higher requirements.', 'The same limit as for cars in summer.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t8', 'et', 'Milline on suverehvi turvise minimaalne sügavus?', '["1,0 mm","1,6 mm","3,0 mm","5,0 mm"]'::jsonb, 1, 'Suverehvi turvis peab olema vähemalt 1,6 mm. Talverehvidel on omad, suuremad nõuded.', 'Sama piir mis sõiduautodel suvel.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t8', 'ru', 'Какая минимальная глубина протектора летней шины?', '["1,0 мм","1,6 мм","3,0 мм","5,0 мм"]'::jsonb, 1, 'У летней шины протектор должен быть не меньше 1,6 мм. Для зимних шин — свои, более высокие требования.', 'Тот же предел, что у легковых летом.', 'Закон о дорожном движении 729/2018 (Финляндия)'),
  ('tech', 'tech.t8', 'sv', 'Vilket är minsta mönsterdjup för ett sommardäck?', '["1,0 mm","1,6 mm","3,0 mm","5,0 mm"]'::jsonb, 1, 'Ett sommardäck ska ha minst 1,6 mm mönsterdjup. För vinterdäck gäller egna, högre krav.', 'Samma gräns som för personbilar på sommaren.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t8', 'lv', 'Kāds ir vasaras riepas protektora minimālais dziļums?', '["1,0 mm","1,6 mm","3,0 mm","5,0 mm"]'::jsonb, 1, 'Vasaras riepas protektoram jābūt vismaz 1,6 mm. Ziemas riepām ir savas, augstākas prasības.', 'Tā pati robeža kā vieglajiem auto vasarā.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t8', 'lt', 'Koks mažiausias vasarinės padangos protektoriaus gylis?', '["1,0 mm","1,6 mm","3,0 mm","5,0 mm"]'::jsonb, 1, 'Vasarinės padangos protektorius turi būti ne mažesnis kaip 1,6 mm. Žieminėms padangoms taikomi atskiri, didesni reikalavimai.', 'Ta pati riba kaip lengviesiems vasarą.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t8', 'pl', 'Jaka jest minimalna głębokość bieżnika opony letniej?', '["1,0 mm","1,6 mm","3,0 mm","5,0 mm"]'::jsonb, 1, 'Opona letnia musi mieć co najmniej 1,6 mm bieżnika. Opony zimowe mają własne, wyższe wymagania.', 'Ten sam limit co dla osobówek latem.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t8', 'nb', 'Hva er minste mønsterdybde for et sommerdekk?', '["1,0 mm","1,6 mm","3,0 mm","5,0 mm"]'::jsonb, 1, 'Et sommerdekk skal ha minst 1,6 mm mønster. For vinterdekk gjelder egne, høyere krav.', 'Samme grense som for personbiler om sommeren.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t8', 'da', 'Hvad er den mindste mønsterdybde for et sommerdæk?', '["1,0 mm","1,6 mm","3,0 mm","5,0 mm"]'::jsonb, 1, 'Et sommerdæk skal have mindst 1,6 mm mønster. For vinterdæk gælder egne, højere krav.', 'Samme grænse som for personbiler om sommeren.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t9', 'fi', 'Illalla huomaat, että perävaunun takavalo ei pala. Mitä teet?', '["Jatkan, koska muut valot palavat","Laitan hätävilkut päälle koko matkaksi","Korjaan tai vaihdan valon ennen kuin jatkan pimeässä","Ilmoitan korjaamolle seuraavalla viikolla"]'::jsonb, 2, 'Ajoneuvoa ei saa käyttää puutteellisin valoin. Takana tuleva ei näe sinua ajoissa pimeässä.', 'Ajattele takana tulevaa pimeällä tiellä.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t9', 'en', 'In the evening you notice a trailer rear light is out. What do you do?', '["Continue, the other lights work","Put the hazard lights on for the whole trip","Fix or replace the light before continuing in the dark","Tell the workshop next week"]'::jsonb, 2, 'A vehicle must not be used with faulty lights. Traffic behind will not see you in time in the dark.', 'Think of the driver behind on a dark road.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t9', 'et', 'Õhtul märkad, et haagise tagatuli ei põle. Mida teed?', '["Jätkan, teised tuled põlevad","Panen ohutuled kogu sõiduks põlema","Parandan või vahetan tule enne, kui pimedas jätkan","Teatan töökojale järgmisel nädalal"]'::jsonb, 2, 'Sõidukit ei tohi kasutada puudulike tuledega. Taga tulev ei näe sind pimedas õigel ajal.', 'Mõtle taga tulevale juhile pimedal teel.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t9', 'ru', 'Вечером вы замечаете, что не горит задний фонарь прицепа. Что делаете?', '["Еду, другие фонари горят","Включаю аварийку на всю дорогу","Чиню или меняю фонарь, прежде чем ехать в темноте","Сообщу в мастерскую на следующей неделе"]'::jsonb, 2, 'Машину нельзя эксплуатировать с неисправным светом. Сзади вас не увидят вовремя в темноте.', 'Подумайте о водителе сзади на тёмной дороге.', 'Закон о дорожном движении 729/2018 (Финляндия)'),
  ('tech', 'tech.t9', 'sv', 'På kvällen märker du att en baklykta på trailern inte lyser. Vad gör du?', '["Fortsätter, de andra lamporna lyser","Slår på varningsblinkers hela vägen","Lagar eller byter lampan innan jag fortsätter i mörker","Säger till verkstaden nästa vecka"]'::jsonb, 2, 'Ett fordon får inte användas med bristfällig belysning. Den bakom ser dig inte i tid i mörker.', 'Tänk på föraren bakom på en mörk väg.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t9', 'lv', 'Vakarā pamani, ka piekabes aizmugures lukturis nedeg. Ko dari?', '["Turpinu, citi lukturi deg","Ieslēdzu avārijas gaismas visam ceļam","Salaboju vai nomainu lukturi, pirms turpinu tumsā","Paziņošu servisam nākamnedēļ"]'::jsonb, 2, 'Transportlīdzekli nedrīkst lietot ar bojātām gaismām. Aizmugurē braucošais tevi tumsā laikus neredzēs.', 'Padomā par vadītāju aiz tevis uz tumša ceļa.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t9', 'lt', 'Vakare pastebi, kad nedega priekabos galinis žibintas. Ką darai?', '["Važiuoju, kiti žibintai dega","Visam keliui įjungiu avarinę signalizaciją","Pataisau ar pakeičiu žibintą prieš važiuodamas tamsoje","Pranešiu servisui kitą savaitę"]'::jsonb, 2, 'Transporto priemonės negalima naudoti su netvarkingais žibintais. Iš paskos važiuojantis tamsoje tavęs laiku nepamatys.', 'Pagalvok apie vairuotoją už tavęs tamsiame kelyje.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t9', 'pl', 'Wieczorem zauważasz, że nie świeci tylna lampa naczepy. Co robisz?', '["Jadę dalej, inne lampy świecą","Włączam awaryjne na całą drogę","Naprawiam lub wymieniam lampę, zanim pojadę po ciemku","Zgłoszę w warsztacie w przyszłym tygodniu"]'::jsonb, 2, 'Pojazdu nie wolno używać z niesprawnymi światłami. Jadący z tyłu nie zobaczy cię w porę w ciemności.', 'Pomyśl o kierowcy za tobą na ciemnej drodze.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t9', 'nb', 'Om kvelden merker du at en baklykt på traileren ikke lyser. Hva gjør du?', '["Fortsetter, de andre lysene virker","Slår på nødblink hele veien","Reparerer eller bytter lykten før jeg fortsetter i mørket","Sier fra til verkstedet neste uke"]'::jsonb, 2, 'Et kjøretøy skal ikke brukes med mangelfulle lys. Den bak ser deg ikke i tide i mørket.', 'Tenk på sjåføren bak på en mørk vei.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t9', 'da', 'Om aftenen opdager du, at en baglygte på traileren ikke lyser. Hvad gør du?', '["Fortsætter, de andre lygter virker","Tænder katastrofeblink hele vejen","Reparerer eller skifter lygten, før jeg fortsætter i mørke","Siger det til værkstedet i næste uge"]'::jsonb, 2, 'Et køretøj må ikke bruges med mangelfuldt lys. Den bagved ser dig ikke i tide i mørke.', 'Tænk på chaufføren bagved på en mørk vej.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t10', 'fi', 'Kuka vastaa siitä, että ajoneuvo on liikennekelpoinen, kun ajat?', '["Vain korjaamo","Kuljettaja, ja lisäksi omistaja tai haltija","Vain katsastusasema","Vain työnantaja"]'::jsonb, 1, 'Kuljettaja ei saa lähteä ajoneuvolla, jonka hän tietää tai jonka hänen pitäisi tietää olevan viallinen. Vastuu on myös ajoneuvon omistajalla ja haltijalla.', 'Ratissa istuu yksi ihminen.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t10', 'en', 'Who is responsible for the vehicle being roadworthy when you drive?', '["Only the workshop","The driver, and also the owner or keeper","Only the inspection station","Only the employer"]'::jsonb, 1, 'The driver must not set off in a vehicle they know, or should know, to be faulty. The owner and keeper are responsible too.', 'One person sits at the wheel.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t10', 'et', 'Kes vastutab sõiduki liikluskõlblikkuse eest, kui sa sõidad?', '["Ainult töökoda","Juht ning lisaks omanik või valdaja","Ainult ülevaatuspunkt","Ainult tööandja"]'::jsonb, 1, 'Juht ei tohi sõita sõidukiga, mille rikkest ta teab või peaks teadma. Vastutus on ka omanikul ja valdajal.', 'Roolis istub üks inimene.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t10', 'ru', 'Кто отвечает за исправность машины, когда вы едете?', '["Только мастерская","Водитель, а также владелец или держатель","Только станция техосмотра","Только работодатель"]'::jsonb, 1, 'Водитель не должен выезжать на машине, о неисправности которой знает или должен знать. Ответственность несут также владелец и держатель.', 'За рулём сидит один человек.', 'Закон о дорожном движении 729/2018 (Финляндия)'),
  ('tech', 'tech.t10', 'sv', 'Vem ansvarar för att fordonet är trafikdugligt när du kör?', '["Bara verkstaden","Föraren, och även ägaren eller innehavaren","Bara besiktningsstationen","Bara arbetsgivaren"]'::jsonb, 1, 'Föraren får inte köra iväg med ett fordon som hen vet, eller borde veta, är felaktigt. Ägaren och innehavaren ansvarar också.', 'En person sitter vid ratten.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t10', 'lv', 'Kas atbild par transportlīdzekļa tehnisko kārtību, kad tu brauc?', '["Tikai serviss","Vadītājs, un arī īpašnieks vai turētājs","Tikai apskates stacija","Tikai darba devējs"]'::jsonb, 1, 'Vadītājs nedrīkst izbraukt ar transportlīdzekli, par kura bojājumu zina vai tam vajadzētu zināt. Atbild arī īpašnieks un turētājs.', 'Pie stūres sēž viens cilvēks.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t10', 'lt', 'Kas atsako už transporto priemonės techninę būklę, kai tu vairuoji?', '["Tik servisas","Vairuotojas, taip pat savininkas ar valdytojas","Tik apžiūros stotis","Tik darbdavys"]'::jsonb, 1, 'Vairuotojas negali išvažiuoti transporto priemone, kuri, jo žiniomis ar turėtų žinoti, yra netvarkinga. Atsako ir savininkas bei valdytojas.', 'Prie vairo sėdi vienas žmogus.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t10', 'pl', 'Kto odpowiada za sprawność pojazdu, gdy jedziesz?', '["Tylko warsztat","Kierowca, a także właściciel lub posiadacz","Tylko stacja kontroli","Tylko pracodawca"]'::jsonb, 1, 'Kierowca nie może wyruszyć pojazdem, o którego niesprawności wie lub powinien wiedzieć. Odpowiadają też właściciel i posiadacz.', 'Za kierownicą siedzi jedna osoba.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t10', 'nb', 'Hvem har ansvaret for at kjøretøyet er i forsvarlig stand når du kjører?', '["Bare verkstedet","Sjåføren, og i tillegg eieren eller innehaveren","Bare kontrollstasjonen","Bare arbeidsgiveren"]'::jsonb, 1, 'Sjåføren skal ikke kjøre av gårde med et kjøretøy hen vet, eller burde vite, er feil. Eieren og innehaveren har også ansvar.', 'Én person sitter bak rattet.', 'Tieliikennelaki 729/2018'),
  ('tech', 'tech.t10', 'da', 'Hvem har ansvaret for, at køretøjet er i forsvarlig stand, når du kører?', '["Kun værkstedet","Chaufføren og desuden ejeren eller brugeren","Kun synshallen","Kun arbejdsgiveren"]'::jsonb, 1, 'Chaufføren må ikke køre af sted i et køretøj, som vedkommende ved eller burde vide er defekt. Ejeren og brugeren har også ansvar.', 'Én person sidder bag rattet.', 'Tieliikennelaki 729/2018'),
  ('adr', 'adr.a1', 'fi', 'Mitä oranssin kilven ylempi numero tarkoittaa?', '["Vaaran tunnusnumeroa","Kuljetettavan aineen massaa","Kuljetusliikkeen numeroa","Tunnelirajoituskoodia"]'::jsonb, 0, 'Ylempi numero on vaaran tunnusnumero, alempi on aineen YK-numero.', 'Alempi numero kertoo aineen.', 'ADR 5.3.2'),
  ('adr', 'adr.a1', 'en', 'What does the upper number on the orange plate mean?', '["The hazard identification number","The mass of the goods","The carrier’s number","The tunnel restriction code"]'::jsonb, 0, 'The upper number is the hazard identification number, the lower one is the UN number of the substance.', 'The lower number names the substance.', 'ADR 5.3.2'),
  ('adr', 'adr.a1', 'et', 'Mida tähendab oranži tahvli ülemine number?', '["Ohu tunnusnumbrit","Veose massi","Vedaja numbrit","Tunnelipiirangu koodi"]'::jsonb, 0, 'Ülemine number on ohu tunnusnumber, alumine aine ÜRO number.', 'Alumine number nimetab aine.', 'ADR 5.3.2'),
  ('adr', 'adr.a1', 'ru', 'Что означает верхнее число оранжевой таблички?', '["Номер опасности","Массу груза","Номер перевозчика","Код ограничения для тоннелей"]'::jsonb, 0, 'Верхнее число — номер опасности, нижнее — номер ООН вещества.', 'Нижнее число называет вещество.', 'ДОПОГ (ADR) 5.3.2'),
  ('adr', 'adr.a1', 'sv', 'Vad betyder det övre numret på den orange skylten?', '["Farlighetsnumret","Godsets vikt","Åkeriets nummer","Tunnelrestriktionskoden"]'::jsonb, 0, 'Det övre numret är farlighetsnumret, det nedre ämnets UN-nummer.', 'Det nedre numret anger ämnet.', 'ADR 5.3.2'),
  ('adr', 'adr.a1', 'lv', 'Ko nozīmē oranžās plāksnes augšējais numurs?', '["Bīstamības numuru","Kravas masu","Pārvadātāja numuru","Tuneļu ierobežojuma kodu"]'::jsonb, 0, 'Augšējais numurs ir bīstamības numurs, apakšējais — vielas ANO numurs.', 'Apakšējais numurs nosauc vielu.', 'ADR 5.3.2'),
  ('adr', 'adr.a1', 'lt', 'Ką reiškia viršutinis oranžinės lentelės numeris?', '["Pavojaus identifikavimo numerį","Krovinio masę","Vežėjo numerį","Tunelių apribojimo kodą"]'::jsonb, 0, 'Viršutinis numeris — pavojaus numeris, apatinis — medžiagos JT numeris.', 'Apatinis numeris įvardija medžiagą.', 'ADR 5.3.2'),
  ('adr', 'adr.a1', 'pl', 'Co oznacza górny numer pomarańczowej tablicy?', '["Numer rozpoznawczy zagrożenia","Masę ładunku","Numer przewoźnika","Kod ograniczenia przejazdu przez tunele"]'::jsonb, 0, 'Górny numer to numer rozpoznawczy zagrożenia, dolny — numer UN materiału.', 'Dolny numer wskazuje materiał.', 'ADR 5.3.2'),
  ('adr', 'adr.a1', 'nb', 'Hva betyr det øvre nummeret på det oransje skiltet?', '["Farenummeret","Godsets vekt","Transportørens nummer","Tunnelrestriksjonskoden"]'::jsonb, 0, 'Det øvre nummeret er farenummeret, det nedre stoffets UN-nummer.', 'Det nedre nummeret angir stoffet.', 'ADR 5.3.2'),
  ('adr', 'adr.a1', 'da', 'Hvad betyder det øverste nummer på det orange skilt?', '["Farenummeret","Godsets vægt","Vognmandens nummer","Tunnelrestriktionskoden"]'::jsonb, 0, 'Det øverste nummer er farenummeret, det nederste stoffets UN-nummer.', 'Det nederste nummer angiver stoffet.', 'ADR 5.3.2'),
  ('adr', 'adr.a2', 'fi', 'Mitä vaaran tunnusnumero 33 tarkoittaa?', '["Myrkyllinen kaasu","Syövyttävä neste","Helposti syttyvä neste","Radioaktiivinen aine"]'::jsonb, 2, '3 on syttyvä neste, ja tuplattu numero tarkoittaa voimistunutta vaaraa: helposti syttyvä neste, esimerkiksi bensiini.', 'Tuplattu numero voimistaa vaaraa.', 'ADR 5.3.2.3'),
  ('adr', 'adr.a2', 'en', 'What does hazard number 33 mean?', '["Toxic gas","Corrosive liquid","Highly flammable liquid","Radioactive material"]'::jsonb, 2, '3 is a flammable liquid, and a doubled digit means an intensified hazard: a highly flammable liquid, such as petrol.', 'A doubled digit intensifies the hazard.', 'ADR 5.3.2.3'),
  ('adr', 'adr.a2', 'et', 'Mida tähendab ohu tunnusnumber 33?', '["Mürgine gaas","Söövitav vedelik","Väga tuleohtlik vedelik","Radioaktiivne aine"]'::jsonb, 2, '3 on tuleohtlik vedelik ja kahekordne number tähendab suurenenud ohtu: väga tuleohtlik vedelik, näiteks bensiin.', 'Kahekordne number suurendab ohtu.', 'ADR 5.3.2.3'),
  ('adr', 'adr.a2', 'ru', 'Что означает номер опасности 33?', '["Токсичный газ","Коррозионная жидкость","Легковоспламеняющаяся жидкость (высокая опасность)","Радиоактивное вещество"]'::jsonb, 2, '3 — горючая жидкость, удвоение — усиленная опасность: легковоспламеняющаяся жидкость, например бензин.', 'Удвоенная цифра усиливает опасность.', 'ДОПОГ (ADR) 5.3.2.3'),
  ('adr', 'adr.a2', 'sv', 'Vad betyder farlighetsnummer 33?', '["Giftig gas","Frätande vätska","Mycket brandfarlig vätska","Radioaktivt ämne"]'::jsonb, 2, '3 är brandfarlig vätska, och en dubbel siffra betyder förstärkt fara: mycket brandfarlig vätska, till exempel bensin.', 'En dubbel siffra förstärker faran.', 'ADR 5.3.2.3'),
  ('adr', 'adr.a2', 'lv', 'Ko nozīmē bīstamības numurs 33?', '["Toksiska gāze","Kodīgs šķidrums","Viegli uzliesmojošs šķidrums","Radioaktīva viela"]'::jsonb, 2, '3 ir uzliesmojošs šķidrums, un dubultots cipars nozīmē pastiprinātu bīstamību: viegli uzliesmojošs šķidrums, piemēram, benzīns.', 'Dubultots cipars pastiprina bīstamību.', 'ADR 5.3.2.3'),
  ('adr', 'adr.a2', 'lt', 'Ką reiškia pavojaus numeris 33?', '["Toksiškos dujos","Ėsdinantis skystis","Labai degusis skystis","Radioaktyvioji medžiaga"]'::jsonb, 2, '3 — degusis skystis, o dvigubas skaitmuo reiškia sustiprintą pavojų: labai degusis skystis, pavyzdžiui, benzinas.', 'Dvigubas skaitmuo sustiprina pavojų.', 'ADR 5.3.2.3'),
  ('adr', 'adr.a2', 'pl', 'Co oznacza numer zagrożenia 33?', '["Gaz trujący","Ciecz żrąca","Ciecz bardzo łatwo zapalna","Materiał promieniotwórczy"]'::jsonb, 2, '3 to ciecz zapalna, a podwojona cyfra oznacza zwiększone zagrożenie: ciecz bardzo łatwo zapalna, np. benzyna.', 'Podwojona cyfra zwiększa zagrożenie.', 'ADR 5.3.2.3'),
  ('adr', 'adr.a2', 'nb', 'Hva betyr farenummer 33?', '["Giftig gass","Etsende væske","Meget brannfarlig væske","Radioaktivt stoff"]'::jsonb, 2, '3 er brannfarlig væske, og et doblet siffer betyr forsterket fare: meget brannfarlig væske, for eksempel bensin.', 'Et doblet siffer forsterker faren.', 'ADR 5.3.2.3'),
  ('adr', 'adr.a2', 'da', 'Hvad betyder farenummer 33?', '["Giftig gas","Ætsende væske","Meget brandfarlig væske","Radioaktivt stof"]'::jsonb, 2, '3 er brandfarlig væske, og et dobbelt ciffer betyder forstærket fare: meget brandfarlig væske, fx benzin.', 'Et dobbelt ciffer forstærker faren.', 'ADR 5.3.2.3'),
  ('adr', 'adr.a3', 'fi', 'Vaaran tunnusnumeron edessä on X. Mitä se tarkoittaa?', '["Aine on räjähtävä","Aine reagoi vaarallisesti veden kanssa — ei vettä","Aine on jäähdytettävä","Kuljetus on kielletty tunneleissa"]'::jsonb, 1, 'X tarkoittaa, että aine reagoi vaarallisesti veden kanssa. Vettä saa käyttää vain asiantuntijan luvalla.', 'Ajattele sammutusta.', 'ADR 5.3.2.3'),
  ('adr', 'adr.a3', 'en', 'There is an X in front of the hazard number. What does it mean?', '["The substance is explosive","It reacts dangerously with water — no water","It must be kept cool","Tunnels are forbidden"]'::jsonb, 1, 'X means the substance reacts dangerously with water. Water may be used only with the approval of experts.', 'Think of firefighting.', 'ADR 5.3.2.3'),
  ('adr', 'adr.a3', 'et', 'Ohu tunnusnumbri ees on X. Mida see tähendab?', '["Aine on plahvatusohtlik","Aine reageerib ohtlikult veega — vett mitte","Ainet tuleb jahutada","Tunnelid on keelatud"]'::jsonb, 1, 'X tähendab, et aine reageerib ohtlikult veega. Vett võib kasutada ainult ekspertide loal.', 'Mõtle kustutamisele.', 'ADR 5.3.2.3'),
  ('adr', 'adr.a3', 'ru', 'Перед номером опасности стоит X. Что это значит?', '["Вещество взрывчатое","Опасно реагирует с водой — воду не применять","Вещество нужно охлаждать","Проезд через тоннели запрещён"]'::jsonb, 1, 'X означает опасную реакцию с водой. Воду применяют только с разрешения специалистов.', 'Подумайте о тушении.', 'ДОПОГ (ADR) 5.3.2.3'),
  ('adr', 'adr.a3', 'sv', 'Det står ett X före farlighetsnumret. Vad betyder det?', '["Ämnet är explosivt","Det reagerar farligt med vatten — inget vatten","Det ska hållas kallt","Tunnlar är förbjudna"]'::jsonb, 1, 'X betyder att ämnet reagerar farligt med vatten. Vatten får användas bara med experters godkännande.', 'Tänk på brandsläckning.', 'ADR 5.3.2.3'),
  ('adr', 'adr.a3', 'lv', 'Pirms bīstamības numura ir X. Ko tas nozīmē?', '["Viela ir sprāgstoša","Bīstami reaģē ar ūdeni — ūdeni nelietot","Viela jāatdzesē","Tuneļi ir aizliegti"]'::jsonb, 1, 'X nozīmē, ka viela bīstami reaģē ar ūdeni. Ūdeni drīkst lietot tikai ar ekspertu atļauju.', 'Padomā par dzēšanu.', 'ADR 5.3.2.3'),
  ('adr', 'adr.a3', 'lt', 'Prieš pavojaus numerį yra X. Ką tai reiškia?', '["Medžiaga sprogi","Pavojingai reaguoja su vandeniu — vandens nenaudoti","Medžiagą reikia vėsinti","Tuneliai draudžiami"]'::jsonb, 1, 'X reiškia, kad medžiaga pavojingai reaguoja su vandeniu. Vandenį galima naudoti tik ekspertams leidus.', 'Pagalvok apie gesinimą.', 'ADR 5.3.2.3'),
  ('adr', 'adr.a3', 'pl', 'Przed numerem zagrożenia jest X. Co to oznacza?', '["Materiał jest wybuchowy","Reaguje niebezpiecznie z wodą — bez wody","Trzeba go chłodzić","Tunele są zakazane"]'::jsonb, 1, 'X oznacza, że materiał niebezpiecznie reaguje z wodą. Wodę można stosować tylko za zgodą ekspertów.', 'Pomyśl o gaszeniu.', 'ADR 5.3.2.3'),
  ('adr', 'adr.a3', 'nb', 'Det står en X foran farenummeret. Hva betyr det?', '["Stoffet er eksplosivt","Det reagerer farlig med vann — ikke vann","Det må holdes kaldt","Tunneler er forbudt"]'::jsonb, 1, 'X betyr at stoffet reagerer farlig med vann. Vann kan bare brukes etter godkjenning fra eksperter.', 'Tenk på slokking.', 'ADR 5.3.2.3'),
  ('adr', 'adr.a3', 'da', 'Der står et X foran farenummeret. Hvad betyder det?', '["Stoffet er eksplosivt","Det reagerer farligt med vand — intet vand","Det skal holdes koldt","Tunneler er forbudt"]'::jsonb, 1, 'X betyder, at stoffet reagerer farligt med vand. Vand må kun bruges med eksperters godkendelse.', 'Tænk på slukning.', 'ADR 5.3.2.3'),
  ('adr', 'adr.a4', 'fi', 'Mikä asiakirja kertoo, mitä kuljettaja tekee onnettomuudessa ja mitä varusteita tarvitaan?', '["Rahtikirja","Kirjalliset turvallisuusohjeet","Ajoneuvon rekisteriote","Kuljettajan ADR-todistus"]'::jsonb, 1, 'Kirjalliset turvallisuusohjeet ovat ohjaamossa kuljettajan ymmärtämällä kielellä. Niissä on toimintaohjeet ja tarvittavat varusteet.', 'Se on ohjaamossa helposti saatavilla.', 'ADR 5.4.3'),
  ('adr', 'adr.a4', 'en', 'Which document tells the driver what to do in an accident and what equipment is needed?', '["The consignment note","The instructions in writing","The vehicle registration document","The driver’s ADR certificate"]'::jsonb, 1, 'The instructions in writing are kept in the cab in a language the driver understands. They give the actions and the equipment needed.', 'It is kept within easy reach in the cab.', 'ADR 5.4.3'),
  ('adr', 'adr.a4', 'et', 'Milline dokument ütleb juhile, mida õnnetuse korral teha ja millist varustust vaja on?', '["Veoseleht","Kirjalikud juhised","Registreerimistunnistus","Juhi ADR-tunnistus"]'::jsonb, 1, 'Kirjalikud juhised on kabiinis juhile arusaadavas keeles. Neis on tegevused ja vajalik varustus.', 'See on kabiinis käepärast.', 'ADR 5.4.3'),
  ('adr', 'adr.a4', 'ru', 'Какой документ говорит водителю, что делать при аварии и какое оснащение нужно?', '["Транспортная накладная","Письменные инструкции","Свидетельство о регистрации","Свидетельство ДОПОГ водителя"]'::jsonb, 1, 'Письменные инструкции лежат в кабине на понятном водителю языке. В них действия и нужное оснащение.', 'Он лежит в кабине под рукой.', 'ДОПОГ (ADR) 5.4.3'),
  ('adr', 'adr.a4', 'sv', 'Vilket dokument säger vad föraren gör vid en olycka och vilken utrustning som behövs?', '["Fraktsedeln","De skriftliga instruktionerna","Registreringsbeviset","Förarens ADR-intyg"]'::jsonb, 1, 'De skriftliga instruktionerna finns i hytten på ett språk föraren förstår. De anger åtgärderna och utrustningen som behövs.', 'Det finns lätt åtkomligt i hytten.', 'ADR 5.4.3'),
  ('adr', 'adr.a4', 'lv', 'Kurš dokuments nosaka, kas vadītājam jādara negadījumā un kāds aprīkojums vajadzīgs?', '["Pavadzīme","Rakstiskās instrukcijas","Reģistrācijas apliecība","Vadītāja ADR apliecība"]'::jsonb, 1, 'Rakstiskās instrukcijas atrodas kabīnē vadītājam saprotamā valodā. Tajās ir rīcība un vajadzīgais aprīkojums.', 'Tas ir kabīnē viegli pieejams.', 'ADR 5.4.3'),
  ('adr', 'adr.a4', 'lt', 'Kuris dokumentas nurodo, ką vairuotojas daro avarijos atveju ir kokios įrangos reikia?', '["Važtaraštis","Rašytinės instrukcijos","Registracijos liudijimas","Vairuotojo ADR pažymėjimas"]'::jsonb, 1, 'Rašytinės instrukcijos laikomos kabinoje vairuotojui suprantama kalba. Jose nurodyti veiksmai ir reikalinga įranga.', 'Jos laikomos kabinoje po ranka.', 'ADR 5.4.3'),
  ('adr', 'adr.a4', 'pl', 'Który dokument mówi kierowcy, co robić w razie wypadku i jakie wyposażenie jest potrzebne?', '["List przewozowy","Instrukcje pisemne","Dowód rejestracyjny","Zaświadczenie ADR kierowcy"]'::jsonb, 1, 'Instrukcje pisemne są w kabinie w języku zrozumiałym dla kierowcy. Zawierają działania i potrzebne wyposażenie.', 'Są w kabinie pod ręką.', 'ADR 5.4.3'),
  ('adr', 'adr.a4', 'nb', 'Hvilket dokument forteller sjåføren hva hen skal gjøre ved en ulykke og hvilket utstyr som trengs?', '["Fraktbrevet","De skriftlige instruksene","Vognkortet","Sjåførens ADR-kompetansebevis"]'::jsonb, 1, 'De skriftlige instruksene ligger i førerhuset på et språk sjåføren forstår. De angir tiltak og nødvendig utstyr.', 'Det ligger lett tilgjengelig i førerhuset.', 'ADR 5.4.3'),
  ('adr', 'adr.a4', 'da', 'Hvilket dokument fortæller chaufføren, hvad der skal gøres ved en ulykke, og hvilket udstyr der skal bruges?', '["Fragtbrevet","De skriftlige anvisninger","Registreringsattesten","Chaufførens ADR-bevis"]'::jsonb, 1, 'De skriftlige anvisninger ligger i førerhuset på et sprog, chaufføren forstår. De angiver handlinger og det nødvendige udstyr.', 'Det ligger let tilgængeligt i førerhuset.', 'ADR 5.4.3'),
  ('adr', 'adr.a5', 'fi', 'Kuinka kauan kuljettajan ADR-ajolupa on voimassa?', '["1 vuoden","3 vuotta","5 vuotta","Toistaiseksi"]'::jsonb, 2, 'ADR-ajolupa on voimassa viisi vuotta. Se uusitaan kertauskoulutuksella ja kokeella.', 'Sama kuin useimmissa kuljettajan pätevyyksissä.', 'ADR 8.2.2.8'),
  ('adr', 'adr.a5', 'en', 'How long is the driver’s ADR certificate valid?', '["1 year","3 years","5 years","Indefinitely"]'::jsonb, 2, 'The ADR driver certificate is valid for five years. It is renewed with a refresher course and an exam.', 'The same as most driver qualifications.', 'ADR 8.2.2.8'),
  ('adr', 'adr.a5', 'et', 'Kui kaua kehtib juhi ADR-tunnistus?', '["1 aasta","3 aastat","5 aastat","Tähtajatult"]'::jsonb, 2, 'ADR-tunnistus kehtib viis aastat. See uuendatakse täienduskoolituse ja eksamiga.', 'Sama kui enamikul juhi pädevustel.', 'ADR 8.2.2.8'),
  ('adr', 'adr.a5', 'ru', 'Сколько действует свидетельство ДОПОГ водителя?', '["1 год","3 года","5 лет","Бессрочно"]'::jsonb, 2, 'Свидетельство ДОПОГ действует пять лет. Его продлевают после курса повышения квалификации и экзамена.', 'Как большинство квалификаций водителя.', 'ДОПОГ (ADR) 8.2.2.8'),
  ('adr', 'adr.a5', 'sv', 'Hur länge gäller förarens ADR-intyg?', '["1 år","3 år","5 år","Tills vidare"]'::jsonb, 2, 'ADR-intyget gäller i fem år. Det förnyas med en repetitionsutbildning och ett prov.', 'Samma som för de flesta förarbehörigheter.', 'ADR 8.2.2.8'),
  ('adr', 'adr.a5', 'lv', 'Cik ilgi ir derīga vadītāja ADR apliecība?', '["1 gadu","3 gadus","5 gadus","Beztermiņa"]'::jsonb, 2, 'ADR apliecība ir derīga piecus gadus. To atjauno ar kvalifikācijas celšanas kursu un eksāmenu.', 'Tāpat kā lielākā daļa vadītāja kvalifikāciju.', 'ADR 8.2.2.8'),
  ('adr', 'adr.a5', 'lt', 'Kiek galioja vairuotojo ADR pažymėjimas?', '["1 metus","3 metus","5 metus","Neterminuotai"]'::jsonb, 2, 'ADR pažymėjimas galioja penkerius metus. Jis pratęsiamas po kvalifikacijos tobulinimo kurso ir egzamino.', 'Kaip dauguma vairuotojo kvalifikacijų.', 'ADR 8.2.2.8'),
  ('adr', 'adr.a5', 'pl', 'Jak długo ważne jest zaświadczenie ADR kierowcy?', '["1 rok","3 lata","5 lat","Bezterminowo"]'::jsonb, 2, 'Zaświadczenie ADR jest ważne pięć lat. Odnawia się je po kursie doskonalącym i egzaminie.', 'Jak większość kwalifikacji kierowcy.', 'ADR 8.2.2.8'),
  ('adr', 'adr.a5', 'nb', 'Hvor lenge gjelder sjåførens ADR-kompetansebevis?', '["1 år","3 år","5 år","Uten tidsbegrensning"]'::jsonb, 2, 'ADR-kompetansebeviset gjelder i fem år. Det fornyes med repetisjonskurs og eksamen.', 'Som de fleste sjåførkompetanser.', 'ADR 8.2.2.8'),
  ('adr', 'adr.a5', 'da', 'Hvor længe er chaufførens ADR-bevis gyldigt?', '["1 år","3 år","5 år","Tidsubegrænset"]'::jsonb, 2, 'ADR-beviset er gyldigt i fem år. Det fornyes med et genopfriskningskursus og en prøve.', 'Som de fleste chaufførkvalifikationer.', 'ADR 8.2.2.8'),
  ('adr', 'adr.a6', 'fi', 'Milloin ADR-kertauskoulutus kannattaa suorittaa, jotta uusi ajolupa jatkuu suoraan edellisestä?', '["Milloin tahansa voimassaolon aikana","Viimeisen vuoden aikana ennen voimassaolon päättymistä","Vasta voimassaolon päätyttyä","Viiden vuoden välein tammikuussa"]'::jsonb, 1, 'Kun kertauskoulutus ja koe suoritetaan viimeisen vuoden aikana ennen päättymistä, uusi viiden vuoden jakso alkaa edellisen päättymispäivästä.', 'Liian aikaisin suoritettu lyhentää voimassaoloa.', 'ADR 8.2.2.8.2'),
  ('adr', 'adr.a6', 'en', 'When should the ADR refresher be done so the new certificate follows on directly?', '["Any time during validity","Within the last year before expiry","Only after expiry","Every five years in January"]'::jsonb, 1, 'If the refresher and exam are passed within the year before expiry, the new five-year period starts from the old expiry date.', 'Doing it too early shortens the validity.', 'ADR 8.2.2.8.2'),
  ('adr', 'adr.a6', 'et', 'Millal teha ADR-täiendkoolitus, et uus tunnistus jätkuks otse eelmisest?', '["Mis tahes ajal kehtivuse jooksul","Viimase aasta jooksul enne kehtivuse lõppu","Alles pärast kehtivuse lõppu","Iga viie aasta järel jaanuaris"]'::jsonb, 1, 'Kui täienduskoolitus ja eksam sooritatakse lõpule eelneva aasta jooksul, algab uus viieaastane periood vana lõppkuupäevast.', 'Liiga vara tehes lüheneb kehtivus.', 'ADR 8.2.2.8.2'),
  ('adr', 'adr.a6', 'ru', 'Когда проходить повторный курс ДОПОГ, чтобы новое свидетельство продолжило старое?', '["В любое время срока действия","В последний год перед окончанием срока","Только после окончания срока","Раз в пять лет в январе"]'::jsonb, 1, 'Если курс и экзамен пройдены в течение года до окончания срока, новые пять лет отсчитываются от даты окончания старого.', 'Слишком рано — срок сократится.', 'ДОПОГ (ADR) 8.2.2.8.2'),
  ('adr', 'adr.a6', 'sv', 'När ska ADR-repetitionen göras så att det nya intyget tar vid direkt?', '["När som helst under giltighetstiden","Under sista året före utgången","Först efter utgången","Vart femte år i januari"]'::jsonb, 1, 'Klaras repetitionen och provet under året före utgången börjar den nya femårsperioden från det gamla slutdatumet.', 'För tidigt förkortar giltigheten.', 'ADR 8.2.2.8.2'),
  ('adr', 'adr.a6', 'lv', 'Kad jāapgūst ADR atkārtotais kurss, lai jaunā apliecība turpinātos tieši no iepriekšējās?', '["Jebkurā laikā derīguma laikā","Pēdējā gada laikā pirms derīguma beigām","Tikai pēc derīguma beigām","Ik pēc pieciem gadiem janvārī"]'::jsonb, 1, 'Ja kurss un eksāmens nokārtoti gada laikā pirms beigām, jaunais piecu gadu periods sākas no vecās apliecības beigu datuma.', 'Pārāk agri — derīgums saīsinās.', 'ADR 8.2.2.8.2'),
  ('adr', 'adr.a6', 'lt', 'Kada išklausyti ADR kartotinį kursą, kad naujas pažymėjimas tęstų ankstesnį?', '["Bet kada galiojimo metu","Per paskutinius metus iki galiojimo pabaigos","Tik pasibaigus galiojimui","Kas penkerius metus sausį"]'::jsonb, 1, 'Jei kursas ir egzaminas išlaikyti per metus iki pabaigos, naujas penkerių metų laikotarpis prasideda nuo senojo pabaigos datos.', 'Per anksti — galiojimas sutrumpėja.', 'ADR 8.2.2.8.2'),
  ('adr', 'adr.a6', 'pl', 'Kiedy zrobić kurs doskonalący ADR, żeby nowe zaświadczenie przedłużyło stare?', '["W dowolnym momencie ważności","W ostatnim roku przed upływem ważności","Dopiero po upływie ważności","Co pięć lat w styczniu"]'::jsonb, 1, 'Jeśli kurs i egzamin zdano w roku przed upływem ważności, nowe pięć lat liczy się od daty końca starego.', 'Za wcześnie — ważność się skróci.', 'ADR 8.2.2.8.2'),
  ('adr', 'adr.a6', 'nb', 'Når bør ADR-repetisjonen tas, så det nye beviset følger rett etter det gamle?', '["Når som helst i gyldighetstiden","I løpet av siste år før utløp","Først etter utløp","Hvert femte år i januar"]'::jsonb, 1, 'Tas repetisjonen og eksamen i året før utløp, starter den nye femårsperioden fra den gamle utløpsdatoen.', 'For tidlig forkorter gyldigheten.', 'ADR 8.2.2.8.2'),
  ('adr', 'adr.a6', 'da', 'Hvornår skal ADR-genopfriskningen tages, så det nye bevis følger direkte efter det gamle?', '["Når som helst i gyldighedsperioden","Inden for det sidste år før udløb","Først efter udløb","Hvert femte år i januar"]'::jsonb, 1, 'Består du genopfriskningen og prøven i året før udløb, starter den nye femårsperiode fra den gamle udløbsdato.', 'For tidligt forkorter gyldigheden.', 'ADR 8.2.2.8.2'),
  ('adr', 'adr.a7', 'fi', 'Saako ADR-kuljetuksessa tupakoida lastauksen aikana ajoneuvon lähellä?', '["Kyllä, jos tuuli käy poispäin","Kyllä, sähkötupakkaa","Kyllä, ohjaamossa ikkuna kiinni","Ei — ei myöskään sähkötupakkaa"]'::jsonb, 3, 'Tupakointi on kielletty käsittelyn aikana ajoneuvon lähellä ja ajoneuvossa. Kielto koskee myös sähkötupakkaa.', 'Kielto koskee kaikkia vastaavia laitteita.', 'ADR 8.3.5'),
  ('adr', 'adr.a7', 'en', 'May you smoke near the vehicle during loading on an ADR transport?', '["Yes, if the wind blows away","Yes, e-cigarettes","Yes, in the cab with the window shut","No — not e-cigarettes either"]'::jsonb, 3, 'Smoking is prohibited during handling near the vehicle and in it. The ban also covers e-cigarettes.', 'The ban covers all similar devices.', 'ADR 8.3.5'),
  ('adr', 'adr.a7', 'et', 'Kas ADR-veol tohib laadimise ajal sõiduki lähedal suitsetada?', '["Jah, kui tuul puhub eemale","Jah, e-sigaretti","Jah, kabiinis aken kinni","Ei — ka e-sigaretti mitte"]'::jsonb, 3, 'Suitsetamine on keelatud käitlemise ajal sõiduki lähedal ja sõidukis. Keeld kehtib ka e-sigaretile.', 'Keeld kehtib kõigile sarnastele seadmetele.', 'ADR 8.3.5'),
  ('adr', 'adr.a7', 'ru', 'Можно ли курить у машины во время погрузки при перевозке ДОПОГ?', '["Да, если ветер в другую сторону","Да, электронную сигарету","Да, в кабине с закрытым окном","Нет — и электронную тоже"]'::jsonb, 3, 'Курение запрещено во время погрузочно-разгрузочных работ рядом с машиной и в ней. Запрет касается и электронных сигарет.', 'Запрет касается всех похожих устройств.', 'ДОПОГ (ADR) 8.3.5'),
  ('adr', 'adr.a7', 'sv', 'Får du röka nära fordonet vid lastning på en ADR-transport?', '["Ja, om vinden blåser bort","Ja, e-cigarett","Ja, i hytten med stängt fönster","Nej — inte e-cigarett heller"]'::jsonb, 3, 'Rökning är förbjuden vid hantering nära fordonet och i det. Förbudet gäller även e-cigaretter.', 'Förbudet gäller alla liknande anordningar.', 'ADR 8.3.5'),
  ('adr', 'adr.a7', 'lv', 'Vai ADR pārvadājumā drīkst smēķēt pie transportlīdzekļa iekraušanas laikā?', '["Jā, ja vējš pūš prom","Jā, e-cigareti","Jā, kabīnē ar aizvērtu logu","Nē — arī e-cigareti ne"]'::jsonb, 3, 'Smēķēšana ir aizliegta kravas darbu laikā pie transportlīdzekļa un tajā. Aizliegums attiecas arī uz e-cigaretēm.', 'Aizliegums attiecas uz visām līdzīgām ierīcēm.', 'ADR 8.3.5'),
  ('adr', 'adr.a7', 'lt', 'Ar ADR vežimo metu galima rūkyti prie transporto priemonės pakraunant?', '["Taip, jei vėjas pučia į šalį","Taip, elektroninę cigaretę","Taip, kabinoje uždarius langą","Ne — ir elektroninės ne"]'::jsonb, 3, 'Rūkyti draudžiama krovos metu prie transporto priemonės ir joje. Draudimas taikomas ir elektroninėms cigaretėms.', 'Draudimas taikomas visiems panašiems prietaisams.', 'ADR 8.3.5'),
  ('adr', 'adr.a7', 'pl', 'Czy przy przewozie ADR wolno palić przy pojeździe podczas załadunku?', '["Tak, jeśli wiatr wieje w drugą stronę","Tak, e-papierosa","Tak, w kabinie przy zamkniętym oknie","Nie — e-papierosa też nie"]'::jsonb, 3, 'Palenie jest zabronione podczas czynności ładunkowych w pobliżu pojazdu i w nim. Zakaz obejmuje też e-papierosy.', 'Zakaz obejmuje wszystkie podobne urządzenia.', 'ADR 8.3.5'),
  ('adr', 'adr.a7', 'nb', 'Kan du røyke nær kjøretøyet under lasting på en ADR-transport?', '["Ja, hvis vinden blåser bort","Ja, e-sigarett","Ja, i førerhuset med lukket vindu","Nei — heller ikke e-sigarett"]'::jsonb, 3, 'Røyking er forbudt under håndtering nær kjøretøyet og i det. Forbudet gjelder også e-sigaretter.', 'Forbudet gjelder alle lignende innretninger.', 'ADR 8.3.5'),
  ('adr', 'adr.a7', 'da', 'Må du ryge nær køretøjet under læsning på en ADR-transport?', '["Ja, hvis vinden blæser væk","Ja, e-cigaret","Ja, i førerhuset med lukket vindue","Nej — heller ikke e-cigaret"]'::jsonb, 3, 'Rygning er forbudt under håndtering nær køretøjet og i det. Forbuddet gælder også e-cigaretter.', 'Forbuddet gælder alle lignende anordninger.', 'ADR 8.3.5'),
  ('adr', 'adr.a8', 'fi', 'Saako moottori käydä lastauksen ja purun aikana?', '["Ei, ellei moottoria tarvita pumppuun tai muuhun laitteeseen","Kyllä, aina","Kyllä, talvella","Vain tyhjäkäynnillä"]'::jsonb, 0, 'Moottori sammutetaan lastauksen ja purun ajaksi, paitsi jos sitä tarvitaan pumppujen tai muiden laitteiden käyttämiseen tai maan laki sen sallii.', 'Käyvä moottori on syttymislähde.', 'ADR 8.3.6'),
  ('adr', 'adr.a8', 'en', 'May the engine run during loading and unloading?', '["No, unless the engine is needed for a pump or other device","Yes, always","Yes, in winter","Only at idle"]'::jsonb, 0, 'The engine is shut off during loading and unloading, except when it is needed to drive pumps or other devices, or national law allows it.', 'A running engine is an ignition source.', 'ADR 8.3.6'),
  ('adr', 'adr.a8', 'et', 'Kas mootor tohib laadimise ja mahalaadimise ajal töötada?', '["Ei, kui mootorit ei ole vaja pumba või muu seadme jaoks","Jah, alati","Jah, talvel","Ainult tühikäigul"]'::jsonb, 0, 'Mootor seisatakse laadimise ja mahalaadimise ajaks, välja arvatud juhul, kui seda on vaja pumpade või muude seadmete tööks või riigi seadus lubab.', 'Töötav mootor on süüteallikas.', 'ADR 8.3.6'),
  ('adr', 'adr.a8', 'ru', 'Можно ли держать двигатель включённым при погрузке и разгрузке?', '["Нет, если он не нужен для насоса или другого устройства","Да, всегда","Да, зимой","Только на холостых"]'::jsonb, 0, 'Двигатель глушат на время погрузки и разгрузки, кроме случаев, когда он нужен для насосов и других устройств или это разрешает закон страны.', 'Работающий двигатель — источник воспламенения.', 'ДОПОГ (ADR) 8.3.6'),
  ('adr', 'adr.a8', 'sv', 'Får motorn gå vid lastning och lossning?', '["Nej, om motorn inte behövs för en pump eller annan anordning","Ja, alltid","Ja, på vintern","Bara på tomgång"]'::jsonb, 0, 'Motorn stängs av vid lastning och lossning, utom när den behövs för att driva pumpar eller andra anordningar eller nationell lag tillåter det.', 'En gående motor är en tändkälla.', 'ADR 8.3.6'),
  ('adr', 'adr.a8', 'lv', 'Vai dzinējs drīkst darboties iekraušanas un izkraušanas laikā?', '["Nē, ja dzinējs nav vajadzīgs sūknim vai citai ierīcei","Jā, vienmēr","Jā, ziemā","Tikai tukšgaitā"]'::jsonb, 0, 'Iekraušanas un izkraušanas laikā dzinēju izslēdz, izņemot, ja tas vajadzīgs sūkņu vai citu ierīču darbināšanai vai to atļauj valsts likums.', 'Strādājošs dzinējs ir aizdegšanās avots.', 'ADR 8.3.6'),
  ('adr', 'adr.a8', 'lt', 'Ar variklis gali veikti pakrovimo ir iškrovimo metu?', '["Ne, nebent variklis reikalingas siurbliui ar kitam įrenginiui","Taip, visada","Taip, žiemą","Tik laisvąja eiga"]'::jsonb, 0, 'Pakrovimo ir iškrovimo metu variklis išjungiamas, išskyrus atvejus, kai jis reikalingas siurbliams ar kitiems įrenginiams arba tai leidžia šalies įstatymas.', 'Veikiantis variklis — uždegimo šaltinis.', 'ADR 8.3.6'),
  ('adr', 'adr.a8', 'pl', 'Czy silnik może pracować podczas załadunku i rozładunku?', '["Nie, chyba że jest potrzebny do pompy lub innego urządzenia","Tak, zawsze","Tak, zimą","Tylko na biegu jałowym"]'::jsonb, 0, 'Na czas załadunku i rozładunku silnik się wyłącza, chyba że jest potrzebny do napędu pomp lub innych urządzeń albo pozwala na to prawo krajowe.', 'Pracujący silnik to źródło zapłonu.', 'ADR 8.3.6'),
  ('adr', 'adr.a8', 'nb', 'Kan motoren gå under lasting og lossing?', '["Nei, med mindre motoren trengs for en pumpe eller annen innretning","Ja, alltid","Ja, om vinteren","Bare på tomgang"]'::jsonb, 0, 'Motoren slås av under lasting og lossing, unntatt når den trengs for å drive pumper eller andre innretninger eller nasjonal lov tillater det.', 'En motor i gang er en tennkilde.', 'ADR 8.3.6'),
  ('adr', 'adr.a8', 'da', 'Må motoren køre under læsning og losning?', '["Nej, medmindre motoren skal bruges til en pumpe eller anden anordning","Ja, altid","Ja, om vinteren","Kun i tomgang"]'::jsonb, 0, 'Motoren slukkes under læsning og losning, undtagen når den skal drive pumper eller andre anordninger, eller national lov tillader det.', 'En kørende motor er en antændelseskilde.', 'ADR 8.3.6'),
  ('adr', 'adr.a9', 'fi', 'Mitä ADR:n kohdan 1.1.3.6 ”pienet määrät” (1000 pistettä) tarkoittaa?', '["Kuljetus on kokonaan vapaa ADR:stä","Määrä on rajattu 1000 kiloon","Kun määrä kuljetusyksikössä jää rajan alle, osa vaatimuksista ei koske","Kuljettaja saa 1000 pisteen alennuksen"]'::jsonb, 2, 'Pienten määrien vapautuksessa esimerkiksi oransseja kilpiä ja kuljettajan ADR-ajolupaa ei vaadita. Osa vaatimuksista, kuten 2 kg sammutin ja asiakirjat, on silti voimassa.', 'Vapautus on osittainen.', 'ADR 1.1.3.6'),
  ('adr', 'adr.a9', 'en', 'What does ADR 1.1.3.6 “small quantities” (1000 points) mean?', '["The transport is fully exempt from ADR","The quantity is limited to 1000 kg","Below the limit per transport unit, some requirements do not apply","The driver gets a 1000-point discount"]'::jsonb, 2, 'Under the small-quantity exemption, for example orange plates and the driver’s ADR certificate are not required. Some requirements, such as a 2 kg extinguisher and the documents, still apply.', 'The exemption is partial.', 'ADR 1.1.3.6'),
  ('adr', 'adr.a9', 'et', 'Mida tähendab ADR punkt 1.1.3.6 „väikesed kogused“ (1000 punkti)?', '["Vedu on ADR-ist täiesti vaba","Kogus on piiratud 1000 kg-ga","Kui kogus veoüksuses jääb alla piiri, osa nõudeid ei kehti","Juht saab 1000 punkti soodustust"]'::jsonb, 2, 'Väikeste koguste erandi korral ei nõuta näiteks oranže tahvleid ega juhi ADR-tunnistust. Osa nõudeid, nagu 2 kg kustuti ja dokumendid, kehtib siiski.', 'Erand on osaline.', 'ADR 1.1.3.6'),
  ('adr', 'adr.a9', 'ru', 'Что означает пункт ДОПОГ 1.1.3.6 «малые количества» (1000 баллов)?', '["Перевозка полностью освобождена от ДОПОГ","Количество ограничено 1000 кг","Если количество на транспортную единицу ниже предела, часть требований не применяется","Водитель получает скидку 1000 баллов"]'::jsonb, 2, 'При освобождении для малых количеств не требуются, например, оранжевые таблички и свидетельство ДОПОГ водителя. Часть требований, например огнетушитель 2 кг и документы, остаётся.', 'Освобождение частичное.', 'ДОПОГ (ADR) 1.1.3.6'),
  ('adr', 'adr.a9', 'sv', 'Vad betyder ADR 1.1.3.6 ”små mängder” (1000 poäng)?', '["Transporten är helt undantagen från ADR","Mängden är begränsad till 1000 kg","Under gränsen per transportenhet gäller inte en del av kraven","Föraren får 1000 poängs rabatt"]'::jsonb, 2, 'Vid undantaget för små mängder krävs till exempel inte orange skyltar och förarens ADR-intyg. En del krav, som 2 kg släckare och dokumenten, gäller ändå.', 'Undantaget är partiellt.', 'ADR 1.1.3.6'),
  ('adr', 'adr.a9', 'lv', 'Ko nozīmē ADR 1.1.3.6 „mazi daudzumi” (1000 punkti)?', '["Pārvadājums ir pilnībā atbrīvots no ADR","Daudzums ierobežots līdz 1000 kg","Ja daudzums transporta vienībā ir zem robežas, daļa prasību nav jāpilda","Vadītājs saņem 1000 punktu atlaidi"]'::jsonb, 2, 'Mazo daudzumu atbrīvojumā nav vajadzīgas, piemēram, oranžās plāksnes un vadītāja ADR apliecība. Daļa prasību, kā 2 kg ugunsdzēšamais un dokumenti, paliek spēkā.', 'Atbrīvojums ir daļējs.', 'ADR 1.1.3.6'),
  ('adr', 'adr.a9', 'lt', 'Ką reiškia ADR 1.1.3.6 „maži kiekiai“ (1000 taškų)?', '["Vežimas visiškai atleistas nuo ADR","Kiekis ribojamas iki 1000 kg","Jei kiekis transporto vienete mažesnis už ribą, dalis reikalavimų netaikoma","Vairuotojas gauna 1000 taškų nuolaidą"]'::jsonb, 2, 'Taikant mažų kiekių išimtį nereikia, pavyzdžiui, oranžinių lentelių ir vairuotojo ADR pažymėjimo. Dalis reikalavimų, kaip 2 kg gesintuvas ir dokumentai, lieka.', 'Išimtis dalinė.', 'ADR 1.1.3.6'),
  ('adr', 'adr.a9', 'pl', 'Co oznacza ADR 1.1.3.6 „małe ilości” (1000 punktów)?', '["Przewóz jest całkowicie zwolniony z ADR","Ilość jest ograniczona do 1000 kg","Poniżej limitu na jednostkę transportową część wymagań nie obowiązuje","Kierowca dostaje 1000 punktów zniżki"]'::jsonb, 2, 'Przy zwolnieniu dla małych ilości nie wymaga się np. pomarańczowych tablic ani zaświadczenia ADR kierowcy. Część wymagań, jak gaśnica 2 kg i dokumenty, nadal obowiązuje.', 'Zwolnienie jest częściowe.', 'ADR 1.1.3.6'),
  ('adr', 'adr.a9', 'nb', 'Hva betyr ADR 1.1.3.6 «små mengder» (1000 poeng)?', '["Transporten er helt unntatt fra ADR","Mengden er begrenset til 1000 kg","Under grensen per transportenhet gjelder ikke en del av kravene","Sjåføren får 1000 poengs rabatt"]'::jsonb, 2, 'Ved unntaket for små mengder kreves for eksempel ikke oransje skilt og sjåførens ADR-kompetansebevis. En del krav, som 2 kg slukker og dokumentene, gjelder likevel.', 'Unntaket er delvis.', 'ADR 1.1.3.6'),
  ('adr', 'adr.a9', 'da', 'Hvad betyder ADR 1.1.3.6 »små mængder« (1000 point)?', '["Transporten er helt undtaget fra ADR","Mængden er begrænset til 1000 kg","Under grænsen pr. transportenhed gælder en del af kravene ikke","Chaufføren får 1000 points rabat"]'::jsonb, 2, 'Ved undtagelsen for små mængder kræves fx ikke orange skilte og chaufførens ADR-bevis. En del krav, som 2 kg slukker og dokumenterne, gælder stadig.', 'Undtagelsen er delvis.', 'ADR 1.1.3.6'),
  ('adr', 'adr.a10', 'fi', 'Kuljetat kaasupulloja (luokka 2.1). Tarvitaanko silmänhuuhdenestettä?', '["Kyllä, aina","Ei — sitä ei vaadita luokissa 1 ja 2","Vain yli 10 tonnin kuormissa","Vain säiliöautoissa"]'::jsonb, 1, 'Silmänhuuhdenestettä ei vaadita varoituslipukkeiden 1, 1.4, 1.5, 1.6, 2.1, 2.2 ja 2.3 aineille. Muut perusvarusteet tarvitaan.', 'Kaasu ei roisku silmiin kuten neste.', 'ADR 8.1.5'),
  ('adr', 'adr.a10', 'en', 'You carry gas cylinders (class 2.1). Is eye rinsing liquid needed?', '["Yes, always","No — not required for classes 1 and 2","Only for loads over 10 t","Only on tankers"]'::jsonb, 1, 'Eye rinsing liquid is not required for goods with labels 1, 1.4, 1.5, 1.6, 2.1, 2.2 and 2.3. The other basic equipment is needed.', 'A gas does not splash into eyes like a liquid.', 'ADR 8.1.5'),
  ('adr', 'adr.a10', 'et', 'Vead gaasiballoone (klass 2.1). Kas silmaloputusvedelikku on vaja?', '["Jah, alati","Ei — klassidele 1 ja 2 seda ei nõuta","Ainult üle 10 t koormal","Ainult paakautol"]'::jsonb, 1, 'Silmaloputusvedelikku ei nõuta ohumärkidega 1, 1.4, 1.5, 1.6, 2.1, 2.2 ja 2.3 kaupadele. Muu põhivarustus on vajalik.', 'Gaas ei pritsi silma nagu vedelik.', 'ADR 8.1.5'),
  ('adr', 'adr.a10', 'ru', 'Вы везёте газовые баллоны (класс 2.1). Нужна жидкость для промывки глаз?', '["Да, всегда","Нет — для классов 1 и 2 не требуется","Только для грузов свыше 10 т","Только на цистернах"]'::jsonb, 1, 'Жидкость для промывки глаз не требуется для знаков 1, 1.4, 1.5, 1.6, 2.1, 2.2 и 2.3. Остальное базовое оснащение нужно.', 'Газ не брызгает в глаза, как жидкость.', 'ДОПОГ (ADR) 8.1.5'),
  ('adr', 'adr.a10', 'sv', 'Du kör gasflaskor (klass 2.1). Behövs ögonsköljvätska?', '["Ja, alltid","Nej — krävs inte för klass 1 och 2","Bara för laster över 10 t","Bara på tankbilar"]'::jsonb, 1, 'Ögonsköljvätska krävs inte för gods med etiketterna 1, 1.4, 1.5, 1.6, 2.1, 2.2 och 2.3. Övrig grundutrustning behövs.', 'En gas stänker inte i ögonen som en vätska.', 'ADR 8.1.5'),
  ('adr', 'adr.a10', 'lv', 'Tu pārvadā gāzes balonus (2.1 klase). Vai vajag acu skalošanas šķidrumu?', '["Jā, vienmēr","Nē — 1. un 2. klasei nav vajadzīgs","Tikai kravām virs 10 t","Tikai cisternām"]'::jsonb, 1, 'Acu skalošanas šķidrums nav vajadzīgs kravām ar zīmēm 1, 1.4, 1.5, 1.6, 2.1, 2.2 un 2.3. Pārējais pamataprīkojums vajadzīgs.', 'Gāze neiešļācas acīs kā šķidrums.', 'ADR 8.1.5'),
  ('adr', 'adr.a10', 'lt', 'Veži dujų balionus (2.1 klasė). Ar reikia akių plovimo skysčio?', '["Taip, visada","Ne — 1 ir 2 klasėms nereikia","Tik kroviniams virš 10 t","Tik cisternoms"]'::jsonb, 1, 'Akių plovimo skysčio nereikia kroviniams su 1, 1.4, 1.5, 1.6, 2.1, 2.2 ir 2.3 ženklais. Kita pagrindinė įranga reikalinga.', 'Dujos neįtykšta į akis kaip skystis.', 'ADR 8.1.5'),
  ('adr', 'adr.a10', 'pl', 'Przewozisz butle z gazem (klasa 2.1). Czy potrzebny jest płyn do płukania oczu?', '["Tak, zawsze","Nie — nie wymaga się go dla klas 1 i 2","Tylko przy ładunkach powyżej 10 t","Tylko w cysternach"]'::jsonb, 1, 'Płyn do płukania oczu nie jest wymagany dla materiałów z nalepkami 1, 1.4, 1.5, 1.6, 2.1, 2.2 i 2.3. Pozostałe wyposażenie podstawowe jest potrzebne.', 'Gaz nie pryska do oczu jak ciecz.', 'ADR 8.1.5'),
  ('adr', 'adr.a10', 'nb', 'Du frakter gassflasker (klasse 2.1). Trengs øyeskyllevæske?', '["Ja, alltid","Nei — kreves ikke for klasse 1 og 2","Bare for laster over 10 t","Bare på tankbiler"]'::jsonb, 1, 'Øyeskyllevæske kreves ikke for gods med etikettene 1, 1.4, 1.5, 1.6, 2.1, 2.2 og 2.3. Det øvrige grunnutstyret trengs.', 'En gass spruter ikke i øynene som en væske.', 'ADR 8.1.5'),
  ('adr', 'adr.a10', 'da', 'Du transporterer gasflasker (klasse 2.1). Skal der være øjenskyllevæske?', '["Ja, altid","Nej — kræves ikke for klasse 1 og 2","Kun for laster over 10 t","Kun på tankvogne"]'::jsonb, 1, 'Øjenskyllevæske kræves ikke for gods med faresedlerne 1, 1.4, 1.5, 1.6, 2.1, 2.2 og 2.3. Det øvrige grundudstyr skal med.', 'En gas sprøjter ikke i øjnene som en væske.', 'ADR 8.1.5'),
  ('adr', 'adr.a11', 'fi', 'Mitä sammuttimelta vaaditaan ADR-kuljetuksessa?', '["Vain, että se on ohjaamossa","Sen on oltava vähintään 12 kg","Riittää, että se on ostettu viiden vuoden sisällä","Sinetti ja merkintä seuraavasta tarkastuspäivästä, ja sen on oltava helposti saatavilla"]'::jsonb, 3, 'Sammuttimissa on oltava sinetti ja merkintä seuraavan tarkastuksen päivämäärästä. Niiden on oltava helposti miehistön ulottuvilla ja suojattu säältä.', 'Sammutin on tarkastettava säännöllisesti.', 'ADR 8.1.4'),
  ('adr', 'adr.a11', 'en', 'What is required of a fire extinguisher on an ADR transport?', '["Only that it is in the cab","It must be at least 12 kg","It is enough that it was bought within five years","A seal and a marking of the next inspection date, and it must be easily accessible"]'::jsonb, 3, 'Extinguishers must carry a seal and a marking of the next inspection date. They must be easily accessible to the crew and protected from the weather.', 'An extinguisher must be inspected regularly.', 'ADR 8.1.4'),
  ('adr', 'adr.a11', 'et', 'Mida nõutakse tulekustutilt ADR-veol?', '["Ainult, et see oleks kabiinis","See peab olema vähemalt 12 kg","Piisab, kui see on ostetud viie aasta jooksul","Plomm ja järgmise kontrolli kuupäeva märge ning lihtne ligipääs"]'::jsonb, 3, 'Kustutitel peab olema plomm ja järgmise kontrolli kuupäeva märge. Need peavad olema meeskonnale kergesti kättesaadavad ja ilmastiku eest kaitstud.', 'Kustutit kontrollitakse regulaarselt.', 'ADR 8.1.4'),
  ('adr', 'adr.a11', 'ru', 'Что требуется от огнетушителя в перевозке ДОПОГ?', '["Только чтобы он был в кабине","Чтобы был не меньше 12 кг","Достаточно, что куплен в последние пять лет","Пломба и отметка о дате следующей проверки, и легкий доступ"]'::jsonb, 3, 'На огнетушителе должны быть пломба и отметка о дате следующей проверки. Он должен быть легкодоступен экипажу и защищён от погоды.', 'Огнетушитель регулярно проверяют.', 'ДОПОГ (ADR) 8.1.4'),
  ('adr', 'adr.a11', 'sv', 'Vad krävs av en brandsläckare på en ADR-transport?', '["Bara att den finns i hytten","Den ska vara minst 12 kg","Det räcker att den köpts inom fem år","En plomb och en märkning om nästa kontrolldatum, och den ska vara lätt åtkomlig"]'::jsonb, 3, 'Släckarna ska ha en plomb och en märkning om datum för nästa kontroll. De ska vara lätt åtkomliga för besättningen och skyddade mot väder.', 'En släckare ska kontrolleras regelbundet.', 'ADR 8.1.4'),
  ('adr', 'adr.a11', 'lv', 'Kas tiek prasīts ugunsdzēšamajam aparātam ADR pārvadājumā?', '["Tikai, lai tas būtu kabīnē","Tam jābūt vismaz 12 kg","Pietiek, ka nopirkts pēdējos piecos gados","Plomba un nākamās pārbaudes datuma atzīme, un viegli pieejams"]'::jsonb, 3, 'Ugunsdzēšamajiem jābūt ar plombu un nākamās pārbaudes datuma atzīmi. Tiem jābūt viegli pieejamiem apkalpei un aizsargātiem no laikapstākļiem.', 'Aparātu regulāri pārbauda.', 'ADR 8.1.4'),
  ('adr', 'adr.a11', 'lt', 'Ko reikalaujama iš gesintuvo ADR vežime?', '["Tik kad jis būtų kabinoje","Jis turi būti bent 12 kg","Pakanka, kad nupirktas per penkerius metus","Plomba ir kitos patikros datos žymė, ir lengvai pasiekiamas"]'::jsonb, 3, 'Gesintuvai turi turėti plombą ir kitos patikros datos žymę. Jie turi būti lengvai pasiekiami įgulai ir apsaugoti nuo oro sąlygų.', 'Gesintuvas tikrinamas reguliariai.', 'ADR 8.1.4'),
  ('adr', 'adr.a11', 'pl', 'Czego wymaga się od gaśnicy w przewozie ADR?', '["Tylko żeby była w kabinie","Musi mieć co najmniej 12 kg","Wystarczy, że kupiono ją w ciągu pięciu lat","Plomby i oznaczenia daty następnej kontroli oraz łatwego dostępu"]'::jsonb, 3, 'Gaśnice muszą mieć plombę i oznaczenie daty następnej kontroli. Muszą być łatwo dostępne dla załogi i chronione przed pogodą.', 'Gaśnicę sprawdza się regularnie.', 'ADR 8.1.4'),
  ('adr', 'adr.a11', 'nb', 'Hva kreves av en brannslukker på en ADR-transport?', '["Bare at den er i førerhuset","Den må være minst 12 kg","Det holder at den er kjøpt innen fem år","En plombe og merking av neste kontrolldato, og den skal være lett tilgjengelig"]'::jsonb, 3, 'Slukkerne skal ha plombe og merking av dato for neste kontroll. De skal være lett tilgjengelige for mannskapet og beskyttet mot vær.', 'En slukker skal kontrolleres jevnlig.', 'ADR 8.1.4'),
  ('adr', 'adr.a11', 'da', 'Hvad kræves af en ildslukker på en ADR-transport?', '["Kun at den er i førerhuset","Den skal være mindst 12 kg","Det er nok, at den er købt inden for fem år","En plombe og mærkning med næste eftersynsdato, og den skal være let tilgængelig"]'::jsonb, 3, 'Slukkerne skal have en plombe og mærkning med datoen for næste eftersyn. De skal være let tilgængelige for besætningen og beskyttet mod vejret.', 'En slukker skal efterses jævnligt.', 'ADR 8.1.4'),
  ('adr', 'adr.a12', 'fi', 'Mitkä varusteet tarvitaan lisäksi luokan 3 nesteelle (esim. bensiini)?', '["Lapio, viemärin tukkeja ja keräysastia","Pakonaamari","Säteilymittari","Ei mitään lisää"]'::jsonb, 0, 'Varoituslipukkeiden 3, 4.1, 4.3, 8 ja 9 kiinteille aineille ja nesteille tarvitaan lapio, viemärin tukkeja ja muovinen keräysastia.', 'Mieti vuotoa tien pinnalle.', 'ADR 8.1.5.3'),
  ('adr', 'adr.a12', 'en', 'What extra equipment is needed for a class 3 liquid (e.g. petrol)?', '["Shovel, drain seal and collecting container","Escape mask","Radiation meter","Nothing extra"]'::jsonb, 0, 'For solids and liquids with labels 3, 4.1, 4.3, 8 and 9, a shovel, a drain seal and a plastic collecting container are needed.', 'Think of a spill on the road.', 'ADR 8.1.5.3'),
  ('adr', 'adr.a12', 'et', 'Millist lisavarustust on vaja 3. klassi vedelikule (nt bensiin)?', '["Labidas, äravoolu kate ja kogumisnõu","Evakuatsioonimask","Kiirgusmõõtur","Mitte midagi lisaks"]'::jsonb, 0, 'Ohumärkidega 3, 4.1, 4.3, 8 ja 9 tahketele ainetele ja vedelikele on vaja labidat, äravoolu katet ja plastist kogumisnõu.', 'Mõtle lekkele teele.', 'ADR 8.1.5.3'),
  ('adr', 'adr.a12', 'ru', 'Какое дополнительное оснащение нужно для жидкости класса 3 (например, бензина)?', '["Лопата, заглушка для стока и сборная ёмкость","Маска для экстренного выхода","Дозиметр","Ничего дополнительного"]'::jsonb, 0, 'Для твёрдых веществ и жидкостей со знаками 3, 4.1, 4.3, 8 и 9 нужны лопата, заглушка для стока и пластиковая сборная ёмкость.', 'Подумайте о разливе на дорогу.', 'ДОПОГ (ADR) 8.1.5.3'),
  ('adr', 'adr.a12', 'sv', 'Vilken extra utrustning behövs för en vätska i klass 3 (t.ex. bensin)?', '["Spade, brunnstätning och uppsamlingskärl","Flyktmask","Strålningsmätare","Inget extra"]'::jsonb, 0, 'För fasta ämnen och vätskor med etiketterna 3, 4.1, 4.3, 8 och 9 behövs spade, brunnstätning och ett uppsamlingskärl av plast.', 'Tänk på ett spill på vägen.', 'ADR 8.1.5.3'),
  ('adr', 'adr.a12', 'lv', 'Kāds papildu aprīkojums vajadzīgs 3. klases šķidrumam (piem., benzīnam)?', '["Lāpsta, notekas aizsegs un savākšanas tvertne","Evakuācijas maska","Radiācijas mērītājs","Nekas papildus"]'::jsonb, 0, 'Cietām vielām un šķidrumiem ar zīmēm 3, 4.1, 4.3, 8 un 9 vajag lāpstu, notekas aizsegu un plastmasas savākšanas tvertni.', 'Padomā par noplūdi uz ceļa.', 'ADR 8.1.5.3'),
  ('adr', 'adr.a12', 'lt', 'Kokios papildomos įrangos reikia 3 klasės skysčiui (pvz., benzinui)?', '["Kastuvo, nutekamojo šulinio uždangalo ir surinkimo talpos","Evakuacinės kaukės","Radiacijos matuoklio","Nieko papildomai"]'::jsonb, 0, 'Kietosioms medžiagoms ir skysčiams su 3, 4.1, 4.3, 8 ir 9 ženklais reikia kastuvo, šulinio uždangalo ir plastikinės surinkimo talpos.', 'Pagalvok apie išsiliejimą kelyje.', 'ADR 8.1.5.3'),
  ('adr', 'adr.a12', 'pl', 'Jakie dodatkowe wyposażenie jest potrzebne dla cieczy klasy 3 (np. benzyny)?', '["Łopata, osłona studzienki i pojemnik zbiorczy","Maska ucieczkowa","Miernik promieniowania","Nic dodatkowo"]'::jsonb, 0, 'Dla materiałów stałych i ciekłych z nalepkami 3, 4.1, 4.3, 8 i 9 potrzebne są łopata, osłona studzienki i plastikowy pojemnik zbiorczy.', 'Pomyśl o wycieku na drogę.', 'ADR 8.1.5.3'),
  ('adr', 'adr.a12', 'nb', 'Hvilket ekstra utstyr trengs for en væske i klasse 3 (f.eks. bensin)?', '["Spade, slukdekke og oppsamlingsbeholder","Rømningsmaske","Strålingsmåler","Ingenting ekstra"]'::jsonb, 0, 'For faste stoffer og væsker med etikettene 3, 4.1, 4.3, 8 og 9 trengs spade, slukdekke og en oppsamlingsbeholder av plast.', 'Tenk på et utslipp på veien.', 'ADR 8.1.5.3'),
  ('adr', 'adr.a12', 'da', 'Hvilket ekstra udstyr skal bruges til en væske i klasse 3 (fx benzin)?', '["Skovl, afløbsdæksel og opsamlingsbeholder","Flugtmaske","Strålingsmåler","Intet ekstra"]'::jsonb, 0, 'For faste stoffer og væsker med faresedlerne 3, 4.1, 4.3, 8 og 9 skal der bruges skovl, afløbsdæksel og en opsamlingsbeholder af plast.', 'Tænk på et spild på vejen.', 'ADR 8.1.5.3'),
  ('tyoturva', 'tyoturva.w1', 'fi', 'Trukki ajaa lastausalueella, ja sinun on mentävä sen reitin yli. Mitä teet?', '["Kävelen nopeasti yli","Odotan, että trukki pysähtyy itsestään","Otan katsekontaktin kuljettajaan ja varmistan, että hän näkee minut","Kuljen trukin takaa"]'::jsonb, 2, 'Trukinkuljettajan näkyvyys on rajallinen, erityisesti kuorman kanssa. Mene reitille vasta, kun olet varma, että kuljettaja on nähnyt sinut.', 'Se, ettet näe vaaraa, ei tarkoita, että sinut nähdään.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w1', 'en', 'A forklift is moving in the loading area and you need to cross its path. What do you do?', '["Walk across quickly","Wait for the forklift to stop by itself","Make eye contact with the driver and make sure they see you","Pass behind the forklift"]'::jsonb, 2, 'A forklift driver’s view is limited, especially with a load. Enter the path only when you are sure the driver has seen you.', 'Seeing the hazard does not mean you are seen.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w1', 'et', 'Laadimisalal sõidab tõstuk ja sa pead selle teest üle minema. Mida teed?', '["Lähen kiiresti üle","Ootan, et tõstuk ise peatuks","Loon juhiga silmside ja veendun, et ta näeb mind","Lähen tõstuki tagant"]'::jsonb, 2, 'Tõstukijuhi nähtavus on piiratud, eriti koormaga. Mine teele alles siis, kui oled kindel, et juht sind nägi.', 'See, et sa näed ohtu, ei tähenda, et sind nähakse.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w1', 'ru', 'На погрузке ездит погрузчик, вам нужно пересечь его путь. Что делаете?', '["Быстро перехожу","Жду, пока он сам остановится","Ловлю взгляд водителя и убеждаюсь, что он меня видит","Прохожу позади погрузчика"]'::jsonb, 2, 'У водителя погрузчика ограниченный обзор, особенно с грузом. Выходите на его путь, только убедившись, что он вас видит.', 'Вы видите опасность — это не значит, что видят вас.', 'Закон об охране труда 738/2002 (Финляндия)'),
  ('tyoturva', 'tyoturva.w1', 'sv', 'En truck kör på lastområdet och du måste korsa dess väg. Vad gör du?', '["Går snabbt över","Väntar på att trucken stannar av sig själv","Söker ögonkontakt med föraren och ser till att hen ser mig","Går bakom trucken"]'::jsonb, 2, 'En truckförare har begränsad sikt, särskilt med last. Gå ut i vägen först när du är säker på att föraren har sett dig.', 'Att du ser faran betyder inte att du blir sedd.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w1', 'lv', 'Iekraušanas zonā brauc iekrāvējs, un tev jāšķērso tā ceļš. Ko dari?', '["Ātri pāreju pāri","Gaidu, kad tas pats apstāsies","Nodibinu acu kontaktu ar vadītāju un pārliecinos, ka viņš mani redz","Eju aiz iekrāvēja"]'::jsonb, 2, 'Iekrāvēja vadītāja redzamība ir ierobežota, īpaši ar kravu. Ej ceļā tikai tad, kad esi drošs, ka vadītājs tevi redzējis.', 'Tas, ka tu redzi briesmas, nenozīmē, ka redz tevi.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w1', 'lt', 'Pakrovimo zonoje važiuoja krautuvas, ir tau reikia pereiti jo kelią. Ką darai?', '["Greitai pereinu","Laukiu, kol jis pats sustos","Užmezgu akių kontaktą su vairuotoju ir įsitikinu, kad jis mane mato","Einu už krautuvo"]'::jsonb, 2, 'Krautuvo vairuotojo matomumas ribotas, ypač su kroviniu. Eik į jo kelią tik įsitikinęs, kad vairuotojas tave matė.', 'Tai, kad matai pavojų, nereiškia, kad tave mato.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w1', 'pl', 'Na placu jeździ wózek widłowy, a musisz przejść przez jego drogę. Co robisz?', '["Szybko przechodzę","Czekam, aż sam się zatrzyma","Nawiązuję kontakt wzrokowy z operatorem i upewniam się, że mnie widzi","Przechodzę za wózkiem"]'::jsonb, 2, 'Operator wózka ma ograniczoną widoczność, zwłaszcza z ładunkiem. Wejdź na jego drogę dopiero, gdy masz pewność, że cię zobaczył.', 'To, że widzisz zagrożenie, nie znaczy, że ciebie widać.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w1', 'nb', 'En truck kjører på lasteområdet, og du må krysse kjøreveien dens. Hva gjør du?', '["Går raskt over","Venter på at trucken stopper av seg selv","Får øyekontakt med føreren og sikrer at hen ser meg","Går bak trucken"]'::jsonb, 2, 'En truckfører har begrenset sikt, særlig med last. Gå inn i kjøreveien først når du er sikker på at føreren har sett deg.', 'At du ser faren, betyr ikke at du blir sett.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w1', 'da', 'En truck kører på læsseområdet, og du skal krydse dens vej. Hvad gør du?', '["Går hurtigt over","Venter på, at trucken stopper af sig selv","Får øjenkontakt med føreren og sikrer mig, at vedkommende ser mig","Går bag om trucken"]'::jsonb, 2, 'En truckfører har begrænset udsyn, især med last. Gå først ind i dens vej, når du er sikker på, at føreren har set dig.', 'At du ser faren, betyder ikke, at du bliver set.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w2', 'fi', 'Miten poistut ohjaamosta turvallisesti?', '["Hyppään alas","Selkä ajoneuvoa päin, kolme tukipistettä","Kasvot ulospäin askelmia pitkin","Pidän kiinni ovesta"]'::jsonb, 1, 'Laskeudu kasvot ajoneuvoon päin ja pidä aina kolme tukipistettä: kaksi kättä ja jalka tai kaksi jalkaa ja käsi. Hyppääminen on yleinen tapaturmien syy.', 'Kuten tikkailla.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w2', 'en', 'How do you get out of the cab safely?', '["Jump down","Facing the vehicle, with three points of contact","Facing outwards down the steps","Hold on to the door"]'::jsonb, 1, 'Climb down facing the vehicle and always keep three points of contact: two hands and a foot or two feet and a hand. Jumping is a common cause of injury.', 'Like on a ladder.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w2', 'et', 'Kuidas kabiinist ohutult väljuda?', '["Hüppan alla","Näoga sõiduki poole, kolm tugipunkti","Näoga väljapoole mööda astmeid","Hoian uksest kinni"]'::jsonb, 1, 'Laskudes ole näoga sõiduki poole ja hoia alati kolme tugipunkti: kaks kätt ja jalg või kaks jalga ja käsi. Hüppamine on sage vigastuste põhjus.', 'Nagu redelil.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w2', 'ru', 'Как безопасно выходить из кабины?', '["Спрыгнуть","Лицом к машине, с тремя точками опоры","Лицом наружу по ступенькам","Держась за дверь"]'::jsonb, 1, 'Спускайтесь лицом к машине, всегда с тремя точками опоры: две руки и нога или две ноги и рука. Прыжок — частая причина травм.', 'Как на лестнице.', 'Закон об охране труда 738/2002 (Финляндия)'),
  ('tyoturva', 'tyoturva.w2', 'sv', 'Hur kliver du ur hytten säkert?', '["Hoppar ner","Med ansiktet mot fordonet och tre stödpunkter","Med ansiktet utåt längs stegen","Håller i dörren"]'::jsonb, 1, 'Kliv ner med ansiktet mot fordonet och ha alltid tre stödpunkter: två händer och en fot eller två fötter och en hand. Att hoppa är en vanlig orsak till skador.', 'Som på en stege.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w2', 'lv', 'Kā droši izkāpt no kabīnes?', '["Nolecu","Ar seju pret transportlīdzekli, trīs atbalsta punkti","Ar seju uz āru pa pakāpieniem","Turos pie durvīm"]'::jsonb, 1, 'Kāp lejā ar seju pret transportlīdzekli un vienmēr turi trīs atbalsta punktus: divas rokas un kāju vai divas kājas un roku. Lēkšana ir biežs traumu cēlonis.', 'Kā uz kāpnēm.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w2', 'lt', 'Kaip saugiai išlipti iš kabinos?', '["Nušoku","Veidu į transporto priemonę, trys atramos taškai","Veidu į išorę laipteliais","Laikausi durų"]'::jsonb, 1, 'Lipk žemyn veidu į transporto priemonę ir visada išlaikyk tris atramos taškus: dvi rankas ir koją arba dvi kojas ir ranką. Šokinėjimas — dažna traumų priežastis.', 'Kaip ant kopėčių.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w2', 'pl', 'Jak bezpiecznie wysiąść z kabiny?', '["Zeskakuję","Przodem do pojazdu, trzy punkty podparcia","Przodem na zewnątrz po stopniach","Trzymam się drzwi"]'::jsonb, 1, 'Schodź przodem do pojazdu, zawsze z trzema punktami podparcia: dwie ręce i noga albo dwie nogi i ręka. Skakanie to częsta przyczyna urazów.', 'Jak na drabinie.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w2', 'nb', 'Hvordan går du trygt ut av førerhuset?', '["Hopper ned","Med ansiktet mot kjøretøyet og tre kontaktpunkter","Med ansiktet utover ned trinnene","Holder i døra"]'::jsonb, 1, 'Gå ned med ansiktet mot kjøretøyet og ha alltid tre kontaktpunkter: to hender og en fot eller to føtter og en hånd. Å hoppe er en vanlig årsak til skader.', 'Som på en stige.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w2', 'da', 'Hvordan stiger du sikkert ud af førerhuset?', '["Springer ned","Med ansigtet mod køretøjet og tre kontaktpunkter","Med ansigtet udad ned ad trinnene","Holder fast i døren"]'::jsonb, 1, 'Stig ned med ansigtet mod køretøjet og hav altid tre kontaktpunkter: to hænder og en fod eller to fødder og en hånd. At springe er en almindelig årsag til skader.', 'Som på en stige.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w3', 'fi', 'Nosturi siirtää konttia yläpuolellasi. Mikä on oikein?', '["Voin kulkea alta, jos nosto on hidas","Voin kulkea alta kypärä päässä","Voin kulkea alta, jos kuljettaja on nähnyt minut","En mene koskaan riippuvan kuorman alle"]'::jsonb, 3, 'Riippuvan kuorman alle ei mennä koskaan: köysi, lukko tai kontti voi pettää. Kypärä ei suojaa putoavalta kontilta.', 'Kypärä ei kestä konttia.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w3', 'en', 'A crane is moving a container above you. What is right?', '["I may pass under if the lift is slow","I may pass under wearing a helmet","I may pass under if the operator has seen me","I never go under a suspended load"]'::jsonb, 3, 'Never go under a suspended load: a rope, lock or the container can fail. A helmet does not protect against a falling container.', 'A helmet cannot take a container.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w3', 'et', 'Kraana liigutab konteinerit sinu kohal. Mis on õige?', '["Võin alt läbi minna, kui tõstmine on aeglane","Võin alt läbi minna kiiver peas","Võin, kui juht on mind näinud","Ma ei lähe kunagi rippuva koorma alla"]'::jsonb, 3, 'Rippuva koorma alla ei minda kunagi: tross, lukk või konteiner võib alt vedada. Kiiver ei kaitse kukkuva konteineri eest.', 'Kiiver ei pea konteinerile vastu.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w3', 'ru', 'Кран переносит контейнер над вами. Что верно?', '["Можно пройти под ним, если подъём медленный","Можно пройти в каске","Можно, если крановщик меня видел","Никогда не захожу под поднятый груз"]'::jsonb, 3, 'Под поднятый груз не заходят никогда: трос, замок или контейнер могут не выдержать. Каска от падающего контейнера не защитит.', 'Каска не выдержит контейнер.', 'Закон об охране труда 738/2002 (Финляндия)'),
  ('tyoturva', 'tyoturva.w3', 'sv', 'En kran flyttar en container ovanför dig. Vad är rätt?', '["Jag kan gå under om lyftet är långsamt","Jag kan gå under med hjälm","Jag kan gå under om föraren har sett mig","Jag går aldrig under en hängande last"]'::jsonb, 3, 'Gå aldrig under en hängande last: en vajer, ett lås eller containern kan brista. En hjälm skyddar inte mot en fallande container.', 'En hjälm klarar inte en container.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w3', 'lv', 'Celtnis pārvieto konteineru virs tevis. Kas ir pareizi?', '["Varu iet apakšā, ja celšana ir lēna","Varu iet apakšā ar ķiveri","Varu, ja operators mani redzējis","Nekad neeju zem piekārtas kravas"]'::jsonb, 3, 'Zem piekārtas kravas nekad neiet: trose, slēdzene vai konteiners var neizturēt. Ķivere no krītoša konteinera neaizsargā.', 'Ķivere neizturēs konteineru.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w3', 'lt', 'Kranas perkelia konteinerį virš tavęs. Kas teisinga?', '["Galiu praeiti po juo, jei kėlimas lėtas","Galiu praeiti su šalmu","Galiu, jei operatorius mane matė","Niekada neinu po kabančiu kroviniu"]'::jsonb, 3, 'Po kabančiu kroviniu neinama niekada: lynas, spyna ar konteineris gali neatlaikyti. Šalmas nuo krintančio konteinerio neapsaugo.', 'Šalmas neatlaikys konteinerio.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w3', 'pl', 'Dźwig przenosi kontener nad tobą. Co jest prawidłowe?', '["Mogę przejść pod spodem, jeśli podnoszenie jest wolne","Mogę przejść w kasku","Mogę, jeśli operator mnie widział","Nigdy nie wchodzę pod wiszący ładunek"]'::jsonb, 3, 'Pod wiszący ładunek nie wchodzi się nigdy: lina, zamek lub kontener mogą zawieść. Kask nie chroni przed spadającym kontenerem.', 'Kask nie wytrzyma kontenera.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w3', 'nb', 'En kran flytter en container over deg. Hva er riktig?', '["Jeg kan gå under hvis løftet er sakte","Jeg kan gå under med hjelm","Jeg kan gå under hvis føreren har sett meg","Jeg går aldri under en hengende last"]'::jsonb, 3, 'Gå aldri under en hengende last: en vaier, en lås eller containeren kan svikte. En hjelm beskytter ikke mot en fallende container.', 'En hjelm tåler ikke en container.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w3', 'da', 'En kran flytter en container over dig. Hvad er rigtigt?', '["Jeg kan gå under, hvis løftet er langsomt","Jeg kan gå under med hjelm","Jeg kan gå under, hvis føreren har set mig","Jeg går aldrig under en hængende last"]'::jsonb, 3, 'Gå aldrig under en hængende last: en wire, en lås eller containeren kan svigte. En hjelm beskytter ikke mod en faldende container.', 'En hjelm kan ikke klare en container.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w4', 'fi', 'Satamassa konttilukki käsittelee kuormaasi. Missä odotat, jos sataman ohjeet eivät muuta sano?', '["Ohjaamossa tai merkityllä turva-alueella","Auton vieressä, jotta näen kaiken","Konttilukin takana","Kontin päällä"]'::jsonb, 0, 'Monessa satamassa kuljettaja odottaa ohjaamossa tai merkityllä alueella, koska isot koneet eivät näe maassa kulkevaa. Noudata aina sataman omia ohjeita.', 'Isot koneet eivät näe maassa olevaa.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w4', 'en', 'In a port a straddle carrier is handling your load. Where do you wait if the port rules say nothing else?', '["In the cab or in a marked safe area","Next to the truck so I see everything","Behind the straddle carrier","On top of the container"]'::jsonb, 0, 'In many ports the driver waits in the cab or a marked area, because big machines cannot see people on the ground. Always follow the port’s own rules.', 'Big machines cannot see people on the ground.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w4', 'et', 'Sadamas käsitleb konteinerveok sinu veost. Kus ootad, kui sadama reeglid muud ei ütle?', '["Kabiinis või märgistatud ohutsoonis","Auto kõrval, et kõike näha","Konteinerveoki taga","Konteineri peal"]'::jsonb, 0, 'Paljudes sadamates ootab juht kabiinis või märgistatud alal, sest suured masinad ei näe maas liikujaid. Järgi alati sadama enda reegleid.', 'Suured masinad ei näe maas olijaid.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w4', 'ru', 'В порту контейнеровоз работает с вашим грузом. Где вы ждёте, если правила порта не говорят иное?', '["В кабине или в размеченной безопасной зоне","Рядом с машиной, чтобы всё видеть","За контейнеровозом","На контейнере"]'::jsonb, 0, 'Во многих портах водитель ждёт в кабине или в размеченной зоне: большие машины не видят людей на земле. Всегда соблюдайте правила конкретного порта.', 'Большие машины не видят людей на земле.', 'Закон об охране труда 738/2002 (Финляндия)'),
  ('tyoturva', 'tyoturva.w4', 'sv', 'I hamnen hanterar en grensletruck din last. Var väntar du om hamnens regler inte säger annat?', '["I hytten eller i ett markerat säkert område","Bredvid bilen så jag ser allt","Bakom grensletrucken","Uppe på containern"]'::jsonb, 0, 'I många hamnar väntar föraren i hytten eller i ett markerat område, eftersom stora maskiner inte ser folk på marken. Följ alltid hamnens egna regler.', 'Stora maskiner ser inte folk på marken.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w4', 'lv', 'Ostā konteineru pārvadātājs strādā ar tavu kravu. Kur gaidi, ja ostas noteikumi nenosaka citādi?', '["Kabīnē vai marķētā drošā zonā","Blakus auto, lai visu redzētu","Aiz konteineru pārvadātāja","Uz konteinera"]'::jsonb, 0, 'Daudzās ostās vadītājs gaida kabīnē vai marķētā zonā, jo lielās mašīnas neredz cilvēkus uz zemes. Vienmēr ievēro konkrētās ostas noteikumus.', 'Lielās mašīnas neredz cilvēkus uz zemes.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w4', 'lt', 'Uoste konteinerių vežėjas tvarko tavo krovinį. Kur lauki, jei uosto taisyklės nenurodo kitaip?', '["Kabinoje arba pažymėtoje saugioje zonoje","Šalia automobilio, kad viską matyčiau","Už konteinerių vežėjo","Ant konteinerio"]'::jsonb, 0, 'Daugelyje uostų vairuotojas laukia kabinoje ar pažymėtoje zonoje, nes didelės mašinos nemato žmonių ant žemės. Visada laikykis konkretaus uosto taisyklių.', 'Didelės mašinos nemato žmonių ant žemės.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w4', 'pl', 'W porcie nośnik kontenerów obsługuje twój ładunek. Gdzie czekasz, jeśli przepisy portu nie mówią inaczej?', '["W kabinie lub w oznaczonej strefie bezpiecznej","Obok auta, żeby wszystko widzieć","Za nośnikiem","Na kontenerze"]'::jsonb, 0, 'W wielu portach kierowca czeka w kabinie lub w oznaczonej strefie, bo duże maszyny nie widzą ludzi na ziemi. Zawsze stosuj się do przepisów danego portu.', 'Duże maszyny nie widzą ludzi na ziemi.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w4', 'nb', 'I havna håndterer en grensetruck lasten din. Hvor venter du hvis havnas regler ikke sier noe annet?', '["I førerhuset eller i et merket sikkert område","Ved siden av bilen så jeg ser alt","Bak grensetrucken","Oppå containeren"]'::jsonb, 0, 'I mange havner venter sjåføren i førerhuset eller i et merket område, fordi store maskiner ikke ser folk på bakken. Følg alltid havnas egne regler.', 'Store maskiner ser ikke folk på bakken.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w4', 'da', 'På havnen håndterer en straddle carrier din last. Hvor venter du, hvis havnens regler ikke siger andet?', '["I førerhuset eller i et afmærket sikkert område","Ved siden af bilen, så jeg kan se alt","Bag straddle carrieren","Oven på containeren"]'::jsonb, 0, 'På mange havne venter chaufføren i førerhuset eller i et afmærket område, fordi store maskiner ikke kan se folk på jorden. Følg altid havnens egne regler.', 'Store maskiner kan ikke se folk på jorden.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w5', 'fi', 'Kuorma melkein kaatui päällesi, mutta kukaan ei loukkaantunut. Mitä teet?', '["En mitään, koska mitään ei tapahtunut","Kerron asiasta kollegoille tauolla","Ilmoitan läheltä piti -tilanteesta työnantajalle tai kohteen vastuuhenkilölle","Otan kuvan somea varten"]'::jsonb, 2, 'Läheltä piti -ilmoitus on keino estää seuraava tapaturma. Ilmoita työnantajalle ja kohteen vastuuhenkilölle.', 'Seuraavalla kerralla joku voi loukkaantua.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w5', 'en', 'A load nearly fell on you, but no one was hurt. What do you do?', '["Nothing, nothing happened","Tell colleagues at the break","Report the near miss to the employer or the site’s responsible person","Take a photo for social media"]'::jsonb, 2, 'A near-miss report is how the next accident is prevented. Report it to the employer and the site’s responsible person.', 'Next time someone may get hurt.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w5', 'et', 'Koorem peaaegu kukkus sulle peale, kuid keegi ei saanud viga. Mida teed?', '["Mitte midagi, midagi ei juhtunud","Räägin kolleegidele pausil","Teatan ohujuhtumist tööandjale või objekti vastutajale","Teen foto sotsiaalmeedia jaoks"]'::jsonb, 2, 'Ohujuhtumist teatamine aitab ära hoida järgmise õnnetuse. Teata tööandjale ja objekti vastutajale.', 'Järgmisel korral võib keegi viga saada.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w5', 'ru', 'Груз чуть не упал на вас, но никто не пострадал. Что делаете?', '["Ничего, ничего же не случилось","Рассказываю коллегам на перерыве","Сообщаю о почти-происшествии работодателю или ответственному на объекте","Снимаю для соцсетей"]'::jsonb, 2, 'Сообщение о почти-происшествии помогает предотвратить следующую травму. Сообщите работодателю и ответственному на объекте.', 'В следующий раз кто-то может пострадать.', 'Закон об охране труда 738/2002 (Финляндия)'),
  ('tyoturva', 'tyoturva.w5', 'sv', 'En last höll på att falla över dig, men ingen skadades. Vad gör du?', '["Ingenting, inget hände","Berättar för kollegor på rasten","Rapporterar tillbudet till arbetsgivaren eller platsens ansvariga","Tar ett foto till sociala medier"]'::jsonb, 2, 'En tillbudsrapport är sättet att förebygga nästa olycka. Rapportera till arbetsgivaren och platsens ansvariga.', 'Nästa gång kan någon skadas.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w5', 'lv', 'Krava gandrīz uzkrita tev virsū, bet neviens necieta. Ko dari?', '["Neko, nekas nenotika","Pastāstu kolēģiem pārtraukumā","Ziņoju par gandrīz notikušo negadījumu darba devējam vai objekta atbildīgajai personai","Nofotografēju sociālajiem tīkliem"]'::jsonb, 2, 'Ziņojums par gandrīz notikušu negadījumu palīdz novērst nākamo traumu. Ziņo darba devējam un objekta atbildīgajai personai.', 'Nākamreiz kāds var ciest.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w5', 'lt', 'Krovinys vos neužkrito ant tavęs, bet niekas nenukentėjo. Ką darai?', '["Nieko, juk nieko neatsitiko","Papasakoju kolegoms per pertrauką","Pranešu apie beveik įvykusį incidentą darbdaviui ar objekto atsakingam asmeniui","Nufotografuoju socialiniams tinklams"]'::jsonb, 2, 'Pranešimas apie beveik įvykusį incidentą padeda išvengti kitos traumos. Pranešk darbdaviui ir objekto atsakingam asmeniui.', 'Kitą kartą kas nors gali nukentėti.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w5', 'pl', 'Ładunek prawie na ciebie spadł, ale nikt nie ucierpiał. Co robisz?', '["Nic, nic się nie stało","Mówię kolegom na przerwie","Zgłaszam zdarzenie potencjalnie wypadkowe pracodawcy lub osobie odpowiedzialnej na miejscu","Robię zdjęcie do mediów społecznościowych"]'::jsonb, 2, 'Zgłoszenie zdarzenia potencjalnie wypadkowego pozwala zapobiec kolejnemu wypadkowi. Zgłoś je pracodawcy i osobie odpowiedzialnej na miejscu.', 'Następnym razem ktoś może ucierpieć.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w5', 'nb', 'En last holdt på å falle over deg, men ingen ble skadet. Hva gjør du?', '["Ingenting, ingenting skjedde","Forteller kolleger i pausen","Melder nestenulykken til arbeidsgiveren eller den ansvarlige på stedet","Tar et bilde til sosiale medier"]'::jsonb, 2, 'En melding om nestenulykke er måten å forebygge neste ulykke på. Meld til arbeidsgiveren og den ansvarlige på stedet.', 'Neste gang kan noen bli skadet.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w5', 'da', 'En last var lige ved at falde ned over dig, men ingen kom til skade. Hvad gør du?', '["Ingenting, der skete jo intet","Fortæller det til kolleger i pausen","Rapporterer nærved-ulykken til arbejdsgiveren eller den ansvarlige på stedet","Tager et billede til sociale medier"]'::jsonb, 2, 'En rapport om en nærved-ulykke er måden at forebygge den næste ulykke på. Rapportér til arbejdsgiveren og den ansvarlige på stedet.', 'Næste gang kan nogen komme til skade.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w6', 'fi', 'Aukaiset takaovia, ja epäilet, että kuorma on siirtynyt matkalla. Mitä teet?', '["Avaan ovet nopeasti selkä vapaana","Avaan varovasti ja seison oven sivussa, en sen edessä","Avaan ovet lastaajan puolesta","Painan ovia olalla, kun avaan"]'::jsonb, 1, 'Siirtynyt kuorma voi painaa ovia ja pudota ulos, kun ne avautuvat. Avaa hitaasti ja seiso sivussa putoamisalueen ulkopuolella.', 'Mihin kuorma putoaa, jos se putoaa?', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w6', 'en', 'You are opening the rear doors and suspect the load has shifted. What do you do?', '["Open the doors fast and step back","Open carefully and stand to the side of the door, not in front","Let the loader open them","Push the doors with my shoulder while opening"]'::jsonb, 1, 'A shifted load can press on the doors and fall out when they open. Open slowly and stand to the side, outside the fall zone.', 'Where would the load land if it fell?', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w6', 'et', 'Avad tagauksi ja kahtlustad, et koorem on teel nihkunud. Mida teed?', '["Avan kiiresti ja astun tagasi","Avan ettevaatlikult ja seisan ukse kõrval, mitte ees","Lasen laadijal avada","Surun ust õlaga avamise ajal"]'::jsonb, 1, 'Nihkunud koorem võib ustele suruda ja avamisel välja kukkuda. Ava aeglaselt ja seisa kõrval, kukkumisalast väljas.', 'Kuhu koorem kukuks?', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w6', 'ru', 'Вы открываете задние двери и подозреваете, что груз сместился. Что делаете?', '["Быстро открываю и отхожу","Открываю медленно и стою сбоку от двери, не перед ней","Пусть открывает грузчик","Придерживаю двери плечом"]'::jsonb, 1, 'Сместившийся груз может давить на двери и выпасть при открытии. Открывайте медленно и стойте сбоку, вне зоны падения.', 'Куда упадёт груз, если упадёт?', 'Закон об охране труда 738/2002 (Финляндия)'),
  ('tyoturva', 'tyoturva.w6', 'sv', 'Du öppnar bakdörrarna och misstänker att lasten har förskjutits. Vad gör du?', '["Öppnar snabbt och backar","Öppnar försiktigt och står vid sidan av dörren, inte framför","Låter lastaren öppna","Trycker på dörren med axeln medan jag öppnar"]'::jsonb, 1, 'En förskjuten last kan trycka på dörrarna och falla ut när de öppnas. Öppna långsamt och stå vid sidan, utanför fallzonen.', 'Var skulle lasten hamna om den föll?', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w6', 'lv', 'Tu atver aizmugures durvis un tev ir aizdomas, ka krava ceļā pārvietojusies. Ko dari?', '["Atveru ātri un atkāpjos","Atveru uzmanīgi un stāvu durvju sānos, ne priekšā","Ļauju atvērt iekrāvējam","Atverot spiežu durvis ar plecu"]'::jsonb, 1, 'Pārvietojusies krava var spiest uz durvīm un izkrist, tās atverot. Atver lēni un stāvi sānos, ārpus krišanas zonas.', 'Kur krava nokristu?', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w6', 'lt', 'Atidarai galines duris ir įtari, kad krovinys kelyje pasislinko. Ką darai?', '["Atidarau greitai ir atsitraukiu","Atidarau atsargiai ir stoviu durų šone, ne priešais","Leidžiu atidaryti krovikui","Atidarydamas spaudžiu duris petimi"]'::jsonb, 1, 'Pasislinkęs krovinys gali spausti duris ir iškristi joms atsidarius. Atidaryk lėtai ir stovėk šone, už kritimo zonos.', 'Kur nukristų krovinys?', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w6', 'pl', 'Otwierasz tylne drzwi i podejrzewasz, że ładunek się przesunął. Co robisz?', '["Otwieram szybko i odskakuję","Otwieram ostrożnie i stoję z boku drzwi, nie przed nimi","Niech otworzy magazynier","Przytrzymuję drzwi barkiem przy otwieraniu"]'::jsonb, 1, 'Przesunięty ładunek może napierać na drzwi i wypaść przy otwarciu. Otwieraj powoli i stój z boku, poza strefą upadku.', 'Gdzie spadłby ładunek?', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w6', 'nb', 'Du åpner bakdørene og mistenker at lasten har forskjøvet seg. Hva gjør du?', '["Åpner raskt og går bakover","Åpner forsiktig og står ved siden av døra, ikke foran","Lar lasteren åpne","Presser døra med skulderen mens jeg åpner"]'::jsonb, 1, 'En forskjøvet last kan presse på dørene og falle ut når de åpnes. Åpne sakte og stå til siden, utenfor fallsonen.', 'Hvor ville lasten havne hvis den falt?', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w6', 'da', 'Du åbner bagdørene og mistænker, at lasten har flyttet sig. Hvad gør du?', '["Åbner hurtigt og træder tilbage","Åbner forsigtigt og står ved siden af døren, ikke foran","Lader læsseren åbne","Presser døren med skulderen, mens jeg åbner"]'::jsonb, 1, 'En forskudt last kan trykke på dørene og falde ud, når de åbnes. Åbn langsomt og stå til siden, uden for faldzonen.', 'Hvor ville lasten lande, hvis den faldt?', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w7', 'fi', 'Perävaunun katolle on kertynyt lunta. Miten toimit?', '["Kiipeän katolle takaovien kautta","Ajan, lumi putoaa itsestään","Pyydän kollegaa pitämään tikkaita","Käytän kohteen tasoa, putoamissuojausta tai lumenpudotuslaitetta"]'::jsonb, 3, 'Perävaunun katolta putoaminen on vakava tapaturma. Katolle ei mennä ilman tasoa tai putoamissuojausta; monella kohteella on lumenpudotuslaite. Katolta putoava lumi voi myös vaarantaa muut liikkujat.', 'Katto on korkealla ja liukas.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w7', 'en', 'Snow has built up on the trailer roof. How do you act?', '["Climb onto the roof via the rear doors","Drive off, the snow will fall by itself","Ask a colleague to hold the ladder","Use the site’s platform, fall protection or snow scraper gantry"]'::jsonb, 3, 'A fall from a trailer roof is a serious injury. Do not go on the roof without a platform or fall protection; many sites have a snow-clearing gantry. Snow falling off can also endanger other road users.', 'The roof is high and slippery.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w7', 'et', 'Haagise katusele on kogunenud lund. Kuidas toimid?', '["Ronin tagauste kaudu katusele","Sõidan, lumi kukub ise","Palun kolleegil redelit hoida","Kasutan objekti platvormi, kukkumiskaitset või lumeeemaldusseadet"]'::jsonb, 3, 'Haagise katuselt kukkumine on raske õnnetus. Katusele ei minda ilma platvormi või kukkumiskaitseta; paljudel objektidel on lumeeemaldusseade. Katuselt kukkuv lumi võib ohustada ka teisi liiklejaid.', 'Katus on kõrgel ja libe.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w7', 'ru', 'На крыше прицепа скопился снег. Как поступаете?', '["Лезу на крышу через задние двери","Еду, снег сам упадёт","Прошу коллегу подержать лестницу","Пользуюсь площадкой, страховкой или снегоочистительной рамой на объекте"]'::jsonb, 3, 'Падение с крыши прицепа — тяжёлая травма. На крышу не лезут без площадки или страховки; на многих объектах есть рама для сброса снега. Снег с крыши опасен и для других на дороге.', 'Крыша высокая и скользкая.', 'Закон об охране труда 738/2002 (Финляндия)'),
  ('tyoturva', 'tyoturva.w7', 'sv', 'Det har samlats snö på trailerns tak. Hur gör du?', '["Klättrar upp på taket via bakdörrarna","Kör, snön faller av sig själv","Ber en kollega hålla stegen","Använder platsens plattform, fallskydd eller snöskrapa"]'::jsonb, 3, 'Ett fall från trailerns tak är en allvarlig olycka. Gå inte upp på taket utan plattform eller fallskydd; många platser har en snöskrapa. Snö som faller av kan också vara farlig för andra trafikanter.', 'Taket är högt och halt.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w7', 'lv', 'Uz piekabes jumta sakrājies sniegs. Kā rīkojies?', '["Uzkāpju uz jumta pa aizmugures durvīm","Braucu, sniegs pats nokritīs","Palūdzu kolēģim paturēt kāpnes","Izmantoju objekta platformu, kritiena aizsardzību vai sniega noņemšanas iekārtu"]'::jsonb, 3, 'Kritiens no piekabes jumta ir smaga trauma. Uz jumta nekāp bez platformas vai kritiena aizsardzības; daudzos objektos ir sniega noņemšanas iekārta. No jumta krītošs sniegs var apdraudēt arī citus satiksmes dalībniekus.', 'Jumts ir augsts un slidens.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w7', 'lt', 'Ant priekabos stogo susikaupė sniego. Kaip elgiesi?', '["Užlipu ant stogo per galines duris","Važiuoju, sniegas pats nukris","Paprašau kolegos palaikyti kopėčias","Naudoju objekto platformą, apsaugą nuo kritimo ar sniego valymo įrenginį"]'::jsonb, 3, 'Kritimas nuo priekabos stogo — sunki trauma. Ant stogo nelipama be platformos ar apsaugos nuo kritimo; daugelyje objektų yra sniego valymo įrenginys. Nuo stogo krentantis sniegas gali kelti pavojų ir kitiems eismo dalyviams.', 'Stogas aukštas ir slidus.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w7', 'pl', 'Na dachu naczepy zebrał się śnieg. Co robisz?', '["Wchodzę na dach przez tylne drzwi","Jadę, śnieg sam spadnie","Proszę kolegę o przytrzymanie drabiny","Korzystam z pomostu, zabezpieczenia przed upadkiem lub zgarniacza śniegu na miejscu"]'::jsonb, 3, 'Upadek z dachu naczepy to ciężki wypadek. Nie wchodzi się na dach bez pomostu lub zabezpieczenia przed upadkiem; w wielu miejscach jest zgarniacz śniegu. Spadający z dachu śnieg zagraża też innym uczestnikom ruchu.', 'Dach jest wysoko i jest śliski.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w7', 'nb', 'Det har samlet seg snø på trailertaket. Hvordan går du fram?', '["Klatrer opp på taket via bakdørene","Kjører, snøen faller av seg selv","Ber en kollega holde stigen","Bruker stedets plattform, fallsikring eller snøskrape"]'::jsonb, 3, 'Et fall fra trailertaket er en alvorlig ulykke. Ikke gå opp på taket uten plattform eller fallsikring; mange steder har snøskrape. Snø som faller av kan også sette andre trafikanter i fare.', 'Taket er høyt og glatt.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w7', 'da', 'Der har samlet sig sne på trailerens tag. Hvordan gør du?', '["Klatrer op på taget via bagdørene","Kører, sneen falder af sig selv","Beder en kollega holde stigen","Bruger stedets platform, faldsikring eller sneskraber"]'::jsonb, 3, 'Et fald fra trailerens tag er en alvorlig ulykke. Gå ikke op på taget uden platform eller faldsikring; mange steder har en sneskraber. Sne, der falder af, kan også bringe andre trafikanter i fare.', 'Taget er højt og glat.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w8', 'fi', 'Kenen vastuulla on työturvallisuus lastauspaikalla, kun olet vieraalla kohteella?', '["Työnantajalla ja kohteen haltijalla, mutta myös sinun on noudatettava ohjeita","Vain omalla työnantajallasi","Vain kohteen haltijalla","Ei kenelläkään, jos olet siellä vain hetken"]'::jsonb, 0, 'Yhteisellä työpaikalla vastuu jakautuu: kohteen haltija ja työnantajat vastaavat järjestelyistä, ja työntekijän on noudatettava annettuja ohjeita.', 'Kaikilla on osuutensa.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w8', 'en', 'Who is responsible for safety at a loading site when you are at someone else’s premises?', '["The employer and the site operator, and you must follow the instructions too","Only your own employer","Only the site operator","No one, if you are there only briefly"]'::jsonb, 0, 'At a shared workplace the responsibility is shared: the site operator and the employers are responsible for the arrangements, and the worker must follow the instructions given.', 'Everyone has a part.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w8', 'et', 'Kes vastutab ohutuse eest laadimiskohas, kui oled võõral objektil?', '["Tööandja ja objekti valdaja, ja ka sina pead juhiseid järgima","Ainult sinu tööandja","Ainult objekti valdaja","Mitte keegi, kui oled seal lühidalt"]'::jsonb, 0, 'Ühisel töökohal jaguneb vastutus: objekti valdaja ja tööandjad vastutavad korralduse eest ning töötaja peab järgima antud juhiseid.', 'Igaühel on oma osa.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w8', 'ru', 'Кто отвечает за безопасность на погрузке, когда вы на чужом объекте?', '["Работодатель и владелец объекта, и вы тоже обязаны соблюдать инструкции","Только ваш работодатель","Только владелец объекта","Никто, если вы там ненадолго"]'::jsonb, 0, 'На общем рабочем месте ответственность делится: владелец объекта и работодатели отвечают за организацию, а работник обязан соблюдать данные инструкции.', 'У каждого своя часть.', 'Закон об охране труда 738/2002 (Финляндия)'),
  ('tyoturva', 'tyoturva.w8', 'sv', 'Vem ansvarar för säkerheten på en lastplats när du är hos någon annan?', '["Arbetsgivaren och platsens innehavare, och du måste också följa instruktionerna","Bara din egen arbetsgivare","Bara platsens innehavare","Ingen, om du bara är där en kort stund"]'::jsonb, 0, 'På en gemensam arbetsplats delas ansvaret: platsens innehavare och arbetsgivarna ansvarar för arrangemangen, och arbetstagaren ska följa givna instruktioner.', 'Alla har sin del.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w8', 'lv', 'Kas atbild par drošību iekraušanas vietā, kad esi svešā objektā?', '["Darba devējs un objekta valdītājs, un arī tev jāievēro instrukcijas","Tikai tavs darba devējs","Tikai objekta valdītājs","Neviens, ja esi tur īsu brīdi"]'::jsonb, 0, 'Kopīgā darba vietā atbildība dalās: objekta valdītājs un darba devēji atbild par organizāciju, un darbiniekam jāievēro dotās instrukcijas.', 'Katram ir sava daļa.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w8', 'lt', 'Kas atsako už saugą pakrovimo vietoje, kai esi svetimame objekte?', '["Darbdavys ir objekto valdytojas, ir tu turi laikytis nurodymų","Tik tavo darbdavys","Tik objekto valdytojas","Niekas, jei esi trumpai"]'::jsonb, 0, 'Bendroje darbo vietoje atsakomybė dalijasi: objekto valdytojas ir darbdaviai atsako už organizavimą, o darbuotojas privalo laikytis nurodymų.', 'Kiekvienas turi savo dalį.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w8', 'pl', 'Kto odpowiada za bezpieczeństwo przy załadunku, gdy jesteś na cudzym terenie?', '["Pracodawca i gospodarz terenu, a ty też musisz przestrzegać instrukcji","Tylko twój pracodawca","Tylko gospodarz terenu","Nikt, jeśli jesteś tam krótko"]'::jsonb, 0, 'Na wspólnym miejscu pracy odpowiedzialność się dzieli: gospodarz terenu i pracodawcy odpowiadają za organizację, a pracownik musi przestrzegać instrukcji.', 'Każdy ma swoją część.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w8', 'nb', 'Hvem har ansvaret for sikkerheten på en lasteplass når du er hos andre?', '["Arbeidsgiveren og stedets innehaver, og du må også følge instruksene","Bare din egen arbeidsgiver","Bare stedets innehaver","Ingen, hvis du bare er der kort"]'::jsonb, 0, 'På en felles arbeidsplass deles ansvaret: stedets innehaver og arbeidsgiverne har ansvar for ordningene, og arbeidstakeren skal følge gitte instrukser.', 'Alle har sin del.', 'Työturvallisuuslaki 738/2002'),
  ('tyoturva', 'tyoturva.w8', 'da', 'Hvem har ansvaret for sikkerheden på en læsseplads, når du er hos andre?', '["Arbejdsgiveren og stedets ejer, og du skal også følge anvisningerne","Kun din egen arbejdsgiver","Kun stedets ejer","Ingen, hvis du kun er der kort"]'::jsonb, 0, 'På et fælles arbejdssted deles ansvaret: stedets ejer og arbejdsgiverne har ansvar for indretningen, og medarbejderen skal følge de givne anvisninger.', 'Alle har deres del.', 'Työturvallisuuslaki 738/2002'),
  ('ensiapu', 'ensiapu.e1', 'fi', 'Mikä on hätänumero Suomessa ja muualla EU:ssa?', '["911","112","110","118"]'::jsonb, 1, '112 toimii koko EU:ssa, myös ilman SIM-korttia. Kerro mitä tapahtui ja missä, ja vastaa kysymyksiin.', 'Sama numero kaikkialla EU:ssa.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e1', 'en', 'What is the emergency number in Finland and the rest of the EU?', '["911","112","110","118"]'::jsonb, 1, '112 works across the EU, even without a SIM card. Say what happened and where, and answer the questions.', 'The same number everywhere in the EU.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e1', 'et', 'Milline on hädaabinumber Soomes ja mujal ELis?', '["911","112","110","118"]'::jsonb, 1, '112 töötab kogu ELis, ka ilma SIM-kaardita. Ütle, mis ja kus juhtus, ning vasta küsimustele.', 'Sama number kogu ELis.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e1', 'ru', 'Какой экстренный номер в Финляндии и по всему ЕС?', '["911","112","110","118"]'::jsonb, 1, '112 работает по всему ЕС, даже без SIM-карты. Скажите, что и где случилось, и отвечайте на вопросы.', 'Один номер по всему ЕС.', 'Рекомендации по реанимации (ERC)'),
  ('ensiapu', 'ensiapu.e1', 'sv', 'Vilket är nödnumret i Finland och resten av EU?', '["911","112","110","118"]'::jsonb, 1, '112 fungerar i hela EU, även utan SIM-kort. Berätta vad som hänt och var, och svara på frågorna.', 'Samma nummer i hela EU.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e1', 'lv', 'Kāds ir ārkārtas numurs Somijā un citur ES?', '["911","112","110","118"]'::jsonb, 1, '112 darbojas visā ES, arī bez SIM kartes. Pastāsti, kas un kur notika, un atbildi uz jautājumiem.', 'Tas pats numurs visā ES.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e1', 'lt', 'Koks pagalbos numeris Suomijoje ir kitur ES?', '["911","112","110","118"]'::jsonb, 1, '112 veikia visoje ES, net be SIM kortelės. Pasakyk, kas ir kur nutiko, ir atsakyk į klausimus.', 'Tas pats numeris visoje ES.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e1', 'pl', 'Jaki jest numer alarmowy w Finlandii i w całej UE?', '["911","112","110","118"]'::jsonb, 1, '112 działa w całej UE, nawet bez karty SIM. Powiedz, co i gdzie się stało, i odpowiadaj na pytania.', 'Ten sam numer w całej UE.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e1', 'nb', 'Hva er nødnummeret i Finland og resten av EU?', '["911","112","110","118"]'::jsonb, 1, '112 virker i hele EU, også uten SIM-kort. Si hva som skjedde og hvor, og svar på spørsmålene.', 'Samme nummer i hele EU.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e1', 'da', 'Hvad er alarmnummeret i Finland og resten af EU?', '["911","112","110","118"]'::jsonb, 1, '112 virker i hele EU, også uden SIM-kort. Sig, hvad der er sket og hvor, og svar på spørgsmålene.', 'Samme nummer i hele EU.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e2', 'fi', 'Aikuinen on tajuton eikä hengitä normaalisti. Mitä teet?', '["Käännän hänet kylkiasentoon","Odotan, että hän herää","Soitan 112 ja aloitan painelu-puhalluselvytyksen 30:2","Annan juotavaa"]'::jsonb, 2, 'Jos aikuinen ei herää eikä hengitä normaalisti, hälytä apua ja aloita elvytys heti: 30 painallusta ja 2 puhallusta.', 'Aika ratkaisee.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e2', 'en', 'An adult is unconscious and not breathing normally. What do you do?', '["Put them in the recovery position","Wait for them to wake up","Call 112 and start CPR 30:2","Give them something to drink"]'::jsonb, 2, 'If an adult does not wake and is not breathing normally, call for help and start CPR at once: 30 compressions and 2 breaths.', 'Time decides.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e2', 'et', 'Täiskasvanu on teadvuseta ega hinga normaalselt. Mida teed?', '["Panen ta külili","Ootan, et ta ärkaks","Helistan 112 ja alustan elustamist 30:2","Annan juua"]'::jsonb, 2, 'Kui täiskasvanu ei ärka ega hinga normaalselt, kutsu abi ja alusta kohe elustamist: 30 survet ja 2 hingamist.', 'Aeg otsustab.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e2', 'ru', 'Взрослый без сознания и не дышит нормально. Что делаете?', '["Кладу на бок","Жду, пока очнётся","Звоню 112 и начинаю реанимацию 30:2","Даю попить"]'::jsonb, 2, 'Если взрослый не приходит в себя и не дышит нормально, вызовите помощь и сразу начните реанимацию: 30 нажатий и 2 вдоха.', 'Решает время.', 'Рекомендации по реанимации (ERC)'),
  ('ensiapu', 'ensiapu.e2', 'sv', 'En vuxen är medvetslös och andas inte normalt. Vad gör du?', '["Lägger personen i stabilt sidoläge","Väntar på att personen vaknar","Ringer 112 och börjar HLR 30:2","Ger något att dricka"]'::jsonb, 2, 'Om en vuxen inte vaknar och inte andas normalt, larma och börja HLR direkt: 30 kompressioner och 2 inblåsningar.', 'Tiden avgör.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e2', 'lv', 'Pieaugušais ir bezsamaņā un neelpo normāli. Ko dari?', '["Noguldu viņu sānu stāvoklī","Gaidu, kad pamodīsies","Zvanu 112 un sāku atdzīvināšanu 30:2","Iedodu padzerties"]'::jsonb, 2, 'Ja pieaugušais nemostas un neelpo normāli, izsauc palīdzību un nekavējoties sāc atdzīvināšanu: 30 kompresijas un 2 ieelpas.', 'Izšķir laiks.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e2', 'lt', 'Suaugęs žmogus be sąmonės ir nekvėpuoja normaliai. Ką darai?', '["Paguldau ant šono","Laukiu, kol atsigaus","Skambinu 112 ir pradedu gaivinimą 30:2","Duodu atsigerti"]'::jsonb, 2, 'Jei suaugęs neatsibunda ir nekvėpuoja normaliai, kviesk pagalbą ir iškart pradėk gaivinimą: 30 paspaudimų ir 2 įpūtimai.', 'Lemia laikas.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e2', 'pl', 'Dorosły jest nieprzytomny i nie oddycha prawidłowo. Co robisz?', '["Układam go w pozycji bocznej","Czekam, aż się ocknie","Dzwonię na 112 i zaczynam resuscytację 30:2","Daję mu pić"]'::jsonb, 2, 'Jeśli dorosły nie reaguje i nie oddycha prawidłowo, wezwij pomoc i od razu zacznij resuscytację: 30 uciśnięć i 2 oddechy.', 'Decyduje czas.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e2', 'nb', 'En voksen er bevisstløs og puster ikke normalt. Hva gjør du?', '["Legger personen i stabilt sideleie","Venter på at personen våkner","Ringer 112 og starter HLR 30:2","Gir noe å drikke"]'::jsonb, 2, 'Hvis en voksen ikke våkner og ikke puster normalt, varsle og start HLR med en gang: 30 kompresjoner og 2 innblåsninger.', 'Tiden avgjør.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e2', 'da', 'En voksen er bevidstløs og trækker ikke vejret normalt. Hvad gør du?', '["Lægger personen i aflåst sideleje","Venter på, at personen vågner","Ringer 112 og starter hjerte-lunge-redning 30:2","Giver noget at drikke"]'::jsonb, 2, 'Hvis en voksen ikke vågner og ikke trækker vejret normalt, så alarmér og start genoplivning med det samme: 30 tryk og 2 indblæsninger.', 'Tiden afgør.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e3', 'fi', 'Millä tahdilla painelet elvytyksessä?', '["60–80 minuutissa","100–120 minuutissa","140–160 minuutissa","Niin nopeasti kuin jaksat"]'::jsonb, 1, 'Painelutahti on 100–120 kertaa minuutissa, ja rintakehän annetaan palautua painallusten välissä.', 'Noin kaksi painallusta sekunnissa.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e3', 'en', 'At what rate do you give chest compressions?', '["60–80 per minute","100–120 per minute","140–160 per minute","As fast as you can"]'::jsonb, 1, 'The rate is 100–120 compressions a minute, letting the chest come back up between them.', 'About two compressions a second.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e3', 'et', 'Millise sagedusega teed elustamisel rindkere surveid?', '["60–80 minutis","100–120 minutis","140–160 minutis","Nii kiiresti kui jaksad"]'::jsonb, 1, 'Sagedus on 100–120 survet minutis ja rindkere peab survete vahel taastuma.', 'Umbes kaks survet sekundis.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e3', 'ru', 'С какой частотой делать нажатия при реанимации?', '["60–80 в минуту","100–120 в минуту","140–160 в минуту","Как можно быстрее"]'::jsonb, 1, 'Частота — 100–120 нажатий в минуту, между нажатиями грудная клетка должна распрямиться.', 'Примерно два нажатия в секунду.', 'Рекомендации по реанимации (ERC)'),
  ('ensiapu', 'ensiapu.e3', 'sv', 'I vilken takt ger du bröstkompressioner?', '["60–80 per minut","100–120 per minut","140–160 per minut","Så fort du orkar"]'::jsonb, 1, 'Takten är 100–120 kompressioner per minut, och bröstkorgen ska få återgå mellan dem.', 'Ungefär två kompressioner per sekund.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e3', 'lv', 'Kādā tempā veic krūškurvja kompresijas?', '["60–80 minūtē","100–120 minūtē","140–160 minūtē","Tik ātri, cik vari"]'::jsonb, 1, 'Temps ir 100–120 kompresijas minūtē, starp tām ļaujot krūškurvim atjaunoties.', 'Aptuveni divas kompresijas sekundē.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e3', 'lt', 'Kokiu dažniu atlieki krūtinės paspaudimus?', '["60–80 per minutę","100–120 per minutę","140–160 per minutę","Kuo greičiau"]'::jsonb, 1, 'Dažnis — 100–120 paspaudimų per minutę, tarp jų leidžiant krūtinei atsitiesti.', 'Maždaug du paspaudimai per sekundę.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e3', 'pl', 'W jakim tempie uciskasz klatkę piersiową?', '["60–80 na minutę","100–120 na minutę","140–160 na minutę","Tak szybko, jak dasz radę"]'::jsonb, 1, 'Tempo to 100–120 uciśnięć na minutę, a między nimi klatka piersiowa ma wrócić do pozycji.', 'Mniej więcej dwa uciśnięcia na sekundę.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e3', 'nb', 'I hvilket tempo gir du brystkompresjoner?', '["60–80 i minuttet","100–120 i minuttet","140–160 i minuttet","Så fort du klarer"]'::jsonb, 1, 'Tempoet er 100–120 kompresjoner i minuttet, og brystkassen skal få komme tilbake mellom dem.', 'Omtrent to kompresjoner i sekundet.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e3', 'da', 'I hvilket tempo giver du hjertemassage?', '["60–80 i minuttet","100–120 i minuttet","140–160 i minuttet","Så hurtigt du kan"]'::jsonb, 1, 'Tempoet er 100–120 tryk i minuttet, og brystkassen skal have lov at komme tilbage mellem dem.', 'Cirka to tryk i sekundet.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e4', 'fi', 'Kuinka syvälle aikuisen rintakehää painetaan elvytyksessä?', '["1–2 cm","3–4 cm","5–6 cm","8–10 cm"]'::jsonb, 2, 'Aikuisen rintakehää painetaan 5–6 cm syvyyteen rintalastan keskeltä.', 'Syvemmälle kuin moni luulee.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e4', 'en', 'How deep do you compress an adult’s chest in CPR?', '["1–2 cm","3–4 cm","5–6 cm","8–10 cm"]'::jsonb, 2, 'An adult’s chest is compressed 5–6 cm deep in the middle of the breastbone.', 'Deeper than many think.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e4', 'et', 'Kui sügavale surutakse täiskasvanu rindkere elustamisel?', '["1–2 cm","3–4 cm","5–6 cm","8–10 cm"]'::jsonb, 2, 'Täiskasvanu rindkere surutakse rinnaku keskelt 5–6 cm sügavusele.', 'Sügavamale, kui paljud arvavad.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e4', 'ru', 'На какую глубину нажимать на грудь взрослого при реанимации?', '["1–2 см","3–4 см","5–6 см","8–10 см"]'::jsonb, 2, 'Грудь взрослого продавливают на 5–6 см в центре грудины.', 'Глубже, чем многие думают.', 'Рекомендации по реанимации (ERC)'),
  ('ensiapu', 'ensiapu.e4', 'sv', 'Hur djupt trycker du en vuxens bröstkorg vid HLR?', '["1–2 cm","3–4 cm","5–6 cm","8–10 cm"]'::jsonb, 2, 'En vuxens bröstkorg trycks ner 5–6 cm mitt på bröstbenet.', 'Djupare än många tror.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e4', 'lv', 'Cik dziļi atdzīvināšanā spiež pieaugušā krūškurvi?', '["1–2 cm","3–4 cm","5–6 cm","8–10 cm"]'::jsonb, 2, 'Pieaugušā krūškurvi spiež 5–6 cm dziļi krūšu kaula vidū.', 'Dziļāk, nekā daudzi domā.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e4', 'lt', 'Kaip giliai gaivinant spaudžiama suaugusiojo krūtinė?', '["1–2 cm","3–4 cm","5–6 cm","8–10 cm"]'::jsonb, 2, 'Suaugusiojo krūtinė spaudžiama 5–6 cm gyliu krūtinkaulio viduryje.', 'Giliau, nei daugelis mano.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e4', 'pl', 'Jak głęboko uciska się klatkę piersiową dorosłego?', '["1–2 cm","3–4 cm","5–6 cm","8–10 cm"]'::jsonb, 2, 'Klatkę piersiową dorosłego uciska się na 5–6 cm na środku mostka.', 'Głębiej, niż wielu myśli.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e4', 'nb', 'Hvor dypt trykker du brystkassen hos en voksen ved HLR?', '["1–2 cm","3–4 cm","5–6 cm","8–10 cm"]'::jsonb, 2, 'Brystkassen hos en voksen trykkes 5–6 cm ned midt på brystbeinet.', 'Dypere enn mange tror.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e4', 'da', 'Hvor dybt trykker du brystkassen ned på en voksen ved genoplivning?', '["1–2 cm","3–4 cm","5–6 cm","8–10 cm"]'::jsonb, 2, 'Brystkassen på en voksen trykkes 5–6 cm ned midt på brystbenet.', 'Dybere, end mange tror.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e5', 'fi', 'Loukkaantunut on tajuton mutta hengittää normaalisti. Mitä teet?', '["Käännän hänet kylkiasentoon ja seuraan hengitystä","Aloitan painelun","Nostan hänet istumaan","Jätän hänet selälleen ja lähden hakemaan apua"]'::jsonb, 0, 'Kylkiasento pitää hengitystiet auki. Seuraa hengitystä jatkuvasti ja aloita elvytys, jos se loppuu.', 'Hengitystie on pidettävä auki.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e5', 'en', 'An injured person is unconscious but breathing normally. What do you do?', '["Put them in the recovery position and watch the breathing","Start chest compressions","Sit them up","Leave them on their back and go for help"]'::jsonb, 0, 'The recovery position keeps the airway open. Keep watching the breathing and start CPR if it stops.', 'The airway must be kept open.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e5', 'et', 'Kannatanu on teadvuseta, kuid hingab normaalselt. Mida teed?', '["Pööran ta külili ja jälgin hingamist","Alustan rindkere surveid","Tõstan ta istuma","Jätan ta selili ja lähen abi otsima"]'::jsonb, 0, 'Külili asend hoiab hingamisteed avatuna. Jälgi pidevalt hingamist ja alusta elustamist, kui see lakkab.', 'Hingamisteed peavad jääma avatuks.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e5', 'ru', 'Пострадавший без сознания, но дышит нормально. Что делаете?', '["Поворачиваю на бок и слежу за дыханием","Начинаю нажатия на грудь","Сажаю его","Оставляю на спине и иду за помощью"]'::jsonb, 0, 'Устойчивое боковое положение держит дыхательные пути открытыми. Следите за дыханием и начните реанимацию, если оно прекратится.', 'Дыхательные пути должны быть открыты.', 'Рекомендации по реанимации (ERC)'),
  ('ensiapu', 'ensiapu.e5', 'sv', 'En skadad person är medvetslös men andas normalt. Vad gör du?', '["Lägger personen i stabilt sidoläge och övervakar andningen","Börjar bröstkompressioner","Sätter personen upp","Lämnar personen på rygg och hämtar hjälp"]'::jsonb, 0, 'Stabilt sidoläge håller luftvägen fri. Fortsätt övervaka andningen och börja HLR om den upphör.', 'Luftvägen ska hållas fri.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e5', 'lv', 'Cietušais ir bezsamaņā, bet elpo normāli. Ko dari?', '["Pagriežu viņu stabilā sānu stāvoklī un vēroju elpošanu","Sāku krūškurvja kompresijas","Pieceļu sēdus","Atstāju uz muguras un eju pēc palīdzības"]'::jsonb, 0, 'Stabilais sānu stāvoklis uztur elpceļus brīvus. Nepārtraukti vēro elpošanu un sāc atdzīvināšanu, ja tā apstājas.', 'Elpceļiem jābūt brīviem.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e5', 'lt', 'Nukentėjusysis be sąmonės, bet kvėpuoja normaliai. Ką darai?', '["Paguldau į stabilią šoninę padėtį ir stebiu kvėpavimą","Pradedu krūtinės paspaudimus","Pasodinu","Palieku ant nugaros ir einu pagalbos"]'::jsonb, 0, 'Stabili šoninė padėtis palaiko kvėpavimo takus atvirus. Nuolat stebėk kvėpavimą ir pradėk gaivinimą, jei jis sustoja.', 'Kvėpavimo takai turi būti atviri.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e5', 'pl', 'Poszkodowany jest nieprzytomny, ale oddycha prawidłowo. Co robisz?', '["Układam go w pozycji bocznej i obserwuję oddech","Zaczynam uciskanie klatki","Sadzam go","Zostawiam na plecach i idę po pomoc"]'::jsonb, 0, 'Pozycja boczna bezpieczna utrzymuje drożność dróg oddechowych. Stale obserwuj oddech i zacznij resuscytację, jeśli ustanie.', 'Drogi oddechowe muszą być drożne.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e5', 'nb', 'En skadd person er bevisstløs, men puster normalt. Hva gjør du?', '["Legger personen i stabilt sideleie og følger med på pusten","Starter brystkompresjoner","Setter personen opp","Lar personen ligge på ryggen og henter hjelp"]'::jsonb, 0, 'Stabilt sideleie holder luftveiene åpne. Følg med på pusten hele tiden, og start HLR hvis den stopper.', 'Luftveiene må holdes åpne.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e5', 'da', 'En tilskadekommen er bevidstløs, men trækker vejret normalt. Hvad gør du?', '["Lægger personen i aflåst sideleje og holder øje med vejrtrækningen","Starter hjertemassage","Sætter personen op","Lader personen ligge på ryggen og henter hjælp"]'::jsonb, 0, 'Aflåst sideleje holder luftvejene frie. Hold hele tiden øje med vejrtrækningen, og start genoplivning, hvis den stopper.', 'Luftvejene skal holdes frie.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e6', 'fi', 'Käsivarresta vuotaa runsaasti verta. Mikä on ensimmäinen toimenpide?', '["Annan juotavaa","Pesen haavan vedellä","Odotan ambulanssia koskematta","Painan vuotokohtaa suoraan ja kohotan raajaa"]'::jsonb, 3, 'Runsas verenvuoto tyrehdytetään painamalla suoraan vuotokohtaa. Kohota raaja ja sido paineside. Hälytä apua.', 'Paine pysäyttää vuodon.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e6', 'en', 'An arm is bleeding heavily. What is the first action?', '["Give them a drink","Wash the wound with water","Wait for the ambulance without touching","Press directly on the wound and raise the limb"]'::jsonb, 3, 'Heavy bleeding is stopped by pressing directly on the wound. Raise the limb and apply a pressure bandage. Call for help.', 'Pressure stops the bleeding.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e6', 'et', 'Käsivarrest jookseb palju verd. Mis on esimene tegevus?', '["Annan juua","Pesen haava veega","Ootan kiirabi midagi puudutamata","Surun otse haavale ja tõstan jäseme"]'::jsonb, 3, 'Tugev verejooks peatatakse otse haavale surudes. Tõsta jäse ja pane survesidemega. Kutsu abi.', 'Surve peatab verejooksu.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e6', 'ru', 'Из руки сильно идёт кровь. Первое действие?', '["Даю попить","Промываю рану водой","Жду скорую, ничего не трогая","Прижимаю рану и поднимаю руку"]'::jsonb, 3, 'Сильное кровотечение останавливают прямым давлением на рану. Поднимите конечность и наложите давящую повязку. Вызовите помощь.', 'Давление останавливает кровь.', 'Рекомендации по реанимации (ERC)'),
  ('ensiapu', 'ensiapu.e6', 'sv', 'En arm blöder kraftigt. Vad är första åtgärden?', '["Ger något att dricka","Tvättar såret med vatten","Väntar på ambulansen utan att röra","Trycker direkt på såret och höjer armen"]'::jsonb, 3, 'Kraftig blödning stoppas genom att trycka direkt på såret. Höj armen och lägg ett tryckförband. Larma.', 'Tryck stoppar blödningen.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e6', 'lv', 'No rokas stipri tek asinis. Kāda ir pirmā rīcība?', '["Iedodu padzerties","Nomazgāju brūci ar ūdeni","Gaidu ātro palīdzību neaiztiekot","Spiežu tieši uz brūces un paceļu roku"]'::jsonb, 3, 'Stipru asiņošanu aptur, spiežot tieši uz brūces. Pacel ekstremitāti un uzliec spiedošo pārsēju. Izsauc palīdzību.', 'Spiediens aptur asiņošanu.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e6', 'lt', 'Iš rankos smarkiai bėga kraujas. Koks pirmas veiksmas?', '["Duodu atsigerti","Nuplaunu žaizdą vandeniu","Laukiu greitosios nieko neliesdamas","Spaudžiu tiesiai žaizdą ir pakeliu ranką"]'::jsonb, 3, 'Stiprus kraujavimas stabdomas spaudžiant tiesiai žaizdą. Pakelk galūnę ir uždėk spaudžiamąjį tvarstį. Kviesk pagalbą.', 'Spaudimas sustabdo kraujavimą.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e6', 'pl', 'Z ręki mocno leci krew. Jaka jest pierwsza czynność?', '["Daję pić","Myję ranę wodą","Czekam na karetkę, nic nie dotykając","Uciskam bezpośrednio ranę i unoszę kończynę"]'::jsonb, 3, 'Silny krwotok tamuje się uciskiem bezpośrednio na ranę. Unieś kończynę i załóż opatrunek uciskowy. Wezwij pomoc.', 'Ucisk zatrzymuje krwawienie.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e6', 'nb', 'En arm blør kraftig. Hva er første tiltak?', '["Gir noe å drikke","Vasker såret med vann","Venter på ambulansen uten å røre","Trykker direkte på såret og løfter armen"]'::jsonb, 3, 'Kraftig blødning stoppes ved å trykke direkte på såret. Løft armen og legg trykkbandasje. Varsle.', 'Trykk stopper blødningen.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e6', 'da', 'En arm bløder kraftigt. Hvad er den første handling?', '["Giver noget at drikke","Vasker såret med vand","Venter på ambulancen uden at røre","Trykker direkte på såret og løfter armen"]'::jsonb, 3, 'Kraftig blødning standses ved at trykke direkte på såret. Løft armen, og læg en trykforbinding. Alarmér.', 'Tryk stopper blødningen.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e7', 'fi', 'Kollega poltti kätensä kuumaan pakoputkeen. Mitä teet ensin?', '["Levitän voita tai rasvaa","Jäähdytän viileällä vedellä noin 20 minuuttia","Puhkaisen rakot","Laitan jäätä suoraan iholle"]'::jsonb, 1, 'Palovamma jäähdytetään heti viileällä vedellä noin 20 minuuttia. Rasvaa ja jäätä ei laiteta, eikä rakkoja puhkaista.', 'Vesi vie lämmön pois.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e7', 'en', 'A colleague burned a hand on a hot exhaust. What do you do first?', '["Spread butter or grease","Cool it with cool water for about 20 minutes","Burst the blisters","Put ice straight on the skin"]'::jsonb, 1, 'A burn is cooled at once with cool water for about 20 minutes. No grease or ice, and blisters are not burst.', 'Water takes the heat away.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e7', 'et', 'Kolleeg põletas käe kuuma väljalasketoru vastu. Mida teed kõigepealt?', '["Määrin võid või rasva","Jahutan jaheda veega umbes 20 minutit","Torkan villid katki","Panen jää otse nahale"]'::jsonb, 1, 'Põletust jahutatakse kohe jaheda veega umbes 20 minutit. Rasva ega jääd ei panda ja ville katki ei torgata.', 'Vesi viib soojuse ära.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e7', 'ru', 'Коллега обжёг руку о горячую выхлопную трубу. Что сделаете сначала?', '["Намажу маслом или жиром","Охлажу прохладной водой около 20 минут","Проколю пузыри","Приложу лёд прямо к коже"]'::jsonb, 1, 'Ожог сразу охлаждают прохладной водой около 20 минут. Жир и лёд не используют, пузыри не прокалывают.', 'Вода забирает тепло.', 'Рекомендации по реанимации (ERC)'),
  ('ensiapu', 'ensiapu.e7', 'sv', 'En kollega brände handen på ett varmt avgasrör. Vad gör du först?', '["Stryker på smör eller fett","Kyler med svalt vatten i cirka 20 minuter","Sticker hål på blåsorna","Lägger is direkt på huden"]'::jsonb, 1, 'En brännskada kyls direkt med svalt vatten i cirka 20 minuter. Inget fett eller is, och blåsorna punkteras inte.', 'Vattnet för bort värmen.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e7', 'lv', 'Kolēģis apdedzināja roku pret karstu izpūtēju. Ko dari vispirms?', '["Uzsmērēju sviestu vai taukus","Atdzesēju ar vēsu ūdeni aptuveni 20 minūtes","Pārduru pūšļus","Uzlieku ledu tieši uz ādas"]'::jsonb, 1, 'Apdegumu nekavējoties dzesē ar vēsu ūdeni aptuveni 20 minūtes. Taukus un ledu neliek, pūšļus nepārdur.', 'Ūdens aizvada siltumu.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e7', 'lt', 'Kolega nusidegino ranką į karštą išmetimo vamzdį. Ką darai pirmiausia?', '["Užtepu sviesto ar riebalų","Vėsinu vėsiu vandeniu apie 20 minučių","Pradūriu pūsles","Dedu ledą tiesiai ant odos"]'::jsonb, 1, 'Nudegimas iškart vėsinamas vėsiu vandeniu apie 20 minučių. Riebalų ir ledo nededama, pūslės nepraduriamos.', 'Vanduo nuneša šilumą.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e7', 'pl', 'Kolega oparzył dłoń o gorącą rurę wydechową. Co robisz najpierw?', '["Smaruję masłem lub tłuszczem","Chłodzę chłodną wodą około 20 minut","Przekłuwam pęcherze","Przykładam lód prosto na skórę"]'::jsonb, 1, 'Oparzenie od razu chłodzi się chłodną wodą przez około 20 minut. Bez tłuszczu i lodu, a pęcherzy się nie przekłuwa.', 'Woda odbiera ciepło.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e7', 'nb', 'En kollega brente hånden på et varmt eksosrør. Hva gjør du først?', '["Smører på smør eller fett","Kjøler med kjølig vann i cirka 20 minutter","Stikker hull på blemmene","Legger is rett på huden"]'::jsonb, 1, 'En brannskade kjøles med en gang med kjølig vann i cirka 20 minutter. Ikke fett eller is, og blemmer stikkes ikke hull på.', 'Vannet tar bort varmen.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e7', 'da', 'En kollega brændte hånden på et varmt udstødningsrør. Hvad gør du først?', '["Smører smør eller fedt på","Køler med køligt vand i cirka 20 minutter","Prikker hul på vablerne","Lægger is direkte på huden"]'::jsonb, 1, 'En forbrænding køles straks med køligt vand i cirka 20 minutter. Intet fedt eller is, og vabler prikkes ikke hul på.', 'Vandet fjerner varmen.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e8', 'fi', 'Elvytyksen aikana paikalle tuodaan defibrillaattori. Mitä teet?', '["Käynnistän sen ja noudatan sen ohjeita, painelu jatkuu tauotta","Lopetan painelun, kunnes ambulanssi tulee","En koske siihen ilman koulutusta","Käytän sitä vain, jos potilas hengittää"]'::jsonb, 0, 'Defibrillaattori opastaa äänellä. Kiinnitä elektrodit, noudata ohjeita ja pidä painelutauot mahdollisimman lyhyinä.', 'Laite neuvoo itse.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e8', 'en', 'During CPR a defibrillator (AED) is brought. What do you do?', '["Switch it on and follow its instructions, keeping compressions going","Stop compressions until the ambulance comes","Not touch it without training","Use it only if the patient is breathing"]'::jsonb, 0, 'An AED guides you by voice. Attach the pads, follow the instructions and keep pauses in compressions as short as possible.', 'The device guides you itself.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e8', 'et', 'Elustamise ajal tuuakse kohale defibrillaator. Mida teed?', '["Lülitan sisse ja järgin selle juhiseid, surved jätkuvad","Lõpetan surved kuni kiirabi tulekuni","Ma ei puutu seda ilma koolituseta","Kasutan ainult siis, kui kannatanu hingab"]'::jsonb, 0, 'Defibrillaator juhendab häälega. Kinnita elektroodid, järgi juhiseid ja hoia survete pausid võimalikult lühikesed.', 'Seade juhendab ise.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e8', 'ru', 'Во время реанимации приносят дефибриллятор. Что делаете?', '["Включаю и следую его указаниям, нажатия без долгих пауз","Прекращаю нажатия до приезда скорой","Не трогаю без обучения","Использую, только если пострадавший дышит"]'::jsonb, 0, 'Дефибриллятор подсказывает голосом. Наклейте электроды, следуйте указаниям и делайте паузы в нажатиях как можно короче.', 'Прибор подсказывает сам.', 'Рекомендации по реанимации (ERC)'),
  ('ensiapu', 'ensiapu.e8', 'sv', 'Under HLR kommer någon med en hjärtstartare. Vad gör du?', '["Slår på den och följer instruktionerna, kompressionerna fortsätter","Slutar med kompressionerna tills ambulansen kommer","Rör den inte utan utbildning","Använder den bara om personen andas"]'::jsonb, 0, 'Hjärtstartaren ger röstinstruktioner. Fäst elektroderna, följ instruktionerna och håll pauserna i kompressionerna så korta som möjligt.', 'Apparaten guidar själv.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e8', 'lv', 'Atdzīvināšanas laikā atnes defibrilatoru. Ko dari?', '["Ieslēdzu un sekoju tā norādījumiem, kompresijas turpinās","Pārtraucu kompresijas līdz ātrās palīdzības ierašanās","Neaiztieku bez apmācības","Lietoju tikai tad, ja cietušais elpo"]'::jsonb, 0, 'Defibrilators vada ar balsi. Piestiprini elektrodus, seko norādījumiem un turi kompresiju pauzes pēc iespējas īsas.', 'Ierīce vada pati.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e8', 'lt', 'Gaivinant atneša defibriliatorių. Ką darai?', '["Įjungiu ir vykdau jo nurodymus, paspaudimai tęsiasi","Nutraukiu paspaudimus, kol atvyks greitoji","Neliečiu be mokymų","Naudoju tik jei nukentėjusysis kvėpuoja"]'::jsonb, 0, 'Defibriliatorius nurodo balsu. Priklijuok elektrodus, vykdyk nurodymus ir paspaudimų pertraukas daryk kuo trumpesnes.', 'Prietaisas nurodo pats.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e8', 'pl', 'Podczas resuscytacji przyniesiono defibrylator (AED). Co robisz?', '["Włączam go i wykonuję polecenia, uciskanie trwa dalej","Przerywam uciskanie do przyjazdu karetki","Nie dotykam go bez szkolenia","Używam go tylko, jeśli poszkodowany oddycha"]'::jsonb, 0, 'AED prowadzi głosem. Przyklej elektrody, wykonuj polecenia i rób jak najkrótsze przerwy w uciśnięciach.', 'Urządzenie samo prowadzi.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e8', 'nb', 'Under HLR kommer noen med en hjertestarter. Hva gjør du?', '["Slår den på og følger instruksjonene, kompresjonene fortsetter","Stopper kompresjonene til ambulansen kommer","Rører den ikke uten opplæring","Bruker den bare hvis personen puster"]'::jsonb, 0, 'Hjertestarteren gir taleinstruksjoner. Fest elektrodene, følg instruksjonene og hold pausene i kompresjonene så korte som mulig.', 'Apparatet veileder selv.', 'Käypä hoito: Elvytys / ERC'),
  ('ensiapu', 'ensiapu.e8', 'da', 'Under genoplivning kommer nogen med en hjertestarter. Hvad gør du?', '["Tænder den og følger anvisningerne, hjertemassagen fortsætter","Stopper hjertemassagen, til ambulancen kommer","Rører den ikke uden uddannelse","Bruger den kun, hvis personen trækker vejret"]'::jsonb, 0, 'Hjertestarteren guider med tale. Sæt elektroderne på, følg anvisningerne, og hold pauserne i hjertemassagen så korte som muligt.', 'Apparatet guider selv.', 'Käypä hoito: Elvytys / ERC'),
  ('tieturva', 'tieturva.r1', 'fi', 'Auto hajoaa maantiellä. Mitä teet ensin?', '["Nousen heti ulos katsomaan vikaa","Hätävilkut päälle ja ajan, jos mahdollista, turvalliseen paikkaan tien sivuun","Soitan työnantajalle ajokaistalla","Asetan kolmion ennen kuin pysähdyn"]'::jsonb, 1, 'Ensin varoitetaan muita ja pyritään pois ajokaistalta. Vasta sitten noustaan ulos huomiovaatteet päällä.', 'Ensin muut liikkujat, sitten vika.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r1', 'en', 'Your truck breaks down on a main road. What do you do first?', '["Get out at once to look at the fault","Hazard lights on and, if possible, move to a safe place off the lane","Call the employer while in the lane","Place the triangle before stopping"]'::jsonb, 1, 'First warn others and get out of the traffic lane. Only then get out, wearing hi-vis.', 'Other road users first, then the fault.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r1', 'et', 'Auto läheb maanteel rikki. Mida teed kõigepealt?', '["Lähen kohe välja riket vaatama","Ohutuled sisse ja võimalusel sõidan ohutusse kohta sõidurajalt välja","Helistan tööandjale sõidurajal seistes","Panen kolmnurga enne peatumist"]'::jsonb, 1, 'Kõigepealt hoiatatakse teisi ja minnakse sõidurajalt ära. Alles siis väljutakse, helkurriietus seljas.', 'Kõigepealt teised liiklejad, siis rike.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r1', 'ru', 'Машина сломалась на трассе. Что делаете сначала?', '["Сразу выхожу посмотреть","Включаю аварийку и, если можно, съезжаю в безопасное место с полосы","Звоню работодателю, стоя на полосе","Ставлю знак до остановки"]'::jsonb, 1, 'Сначала предупреждают других и уходят с полосы движения. Только потом выходят — в светоотражающей одежде.', 'Сначала другие участники движения, потом поломка.', 'Закон о дорожном движении 729/2018 (Финляндия)'),
  ('tieturva', 'tieturva.r1', 'sv', 'Bilen går sönder på en landsväg. Vad gör du först?', '["Kliver ut direkt och tittar på felet","Varningsblinkers på och, om möjligt, flyttar till en säker plats utanför körfältet","Ringer arbetsgivaren i körfältet","Ställer ut triangeln innan jag stannar"]'::jsonb, 1, 'Först varnas andra och fordonet flyttas ut ur körfältet. Först därefter kliver du ut, med varselkläder på.', 'Först andra trafikanter, sedan felet.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r1', 'lv', 'Auto salūzt uz šosejas. Ko dari vispirms?', '["Uzreiz izkāpju paskatīties bojājumu","Ieslēdzu avārijas gaismas un, ja iespējams, nobraucu drošā vietā ārpus joslas","Zvanu darba devējam, stāvot joslā","Novietoju trīsstūri pirms apstāšanās"]'::jsonb, 1, 'Vispirms brīdina citus un nobrauc no braukšanas joslas. Tikai tad izkāpj, ar atstarojošu apģērbu.', 'Vispirms citi satiksmes dalībnieki, tad bojājums.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r1', 'lt', 'Automobilis sugenda magistralėje. Ką darai pirmiausia?', '["Iškart išlipu pažiūrėti gedimo","Įjungiu avarinę signalizaciją ir, jei įmanoma, nuvažiuoju į saugią vietą nuo eismo juostos","Skambinu darbdaviui stovėdamas juostoje","Pastatau ženklą prieš sustodamas"]'::jsonb, 1, 'Pirmiausia įspėjami kiti ir pasitraukiama iš eismo juostos. Tik tada išlipama, apsivilkus atšvaitinius drabužius.', 'Pirmiausia kiti eismo dalyviai, tada gedimas.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r1', 'pl', 'Ciężarówka psuje się na drodze krajowej. Co robisz najpierw?', '["Od razu wysiadam obejrzeć usterkę","Włączam awaryjne i jeśli się da, zjeżdżam w bezpieczne miejsce poza pas","Dzwonię do pracodawcy, stojąc na pasie","Stawiam trójkąt przed zatrzymaniem"]'::jsonb, 1, 'Najpierw ostrzega się innych i zjeżdża z pasa ruchu. Dopiero potem wysiada się w odzieży ostrzegawczej.', 'Najpierw inni uczestnicy ruchu, potem usterka.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r1', 'nb', 'Bilen får motorstopp på en hovedvei. Hva gjør du først?', '["Går ut med en gang for å se på feilen","Nødblink på og, om mulig, kjører til et trygt sted ut av kjørefeltet","Ringer arbeidsgiveren mens jeg står i feltet","Setter ut trekanten før jeg stopper"]'::jsonb, 1, 'Først varsles andre, og kjøretøyet flyttes ut av kjørefeltet. Først da går du ut, med synlighetsklær.', 'Først andre trafikanter, så feilen.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r1', 'da', 'Bilen bryder sammen på en landevej. Hvad gør du først?', '["Stiger ud med det samme for at se på fejlen","Katastrofeblink til og om muligt kører til et sikkert sted uden for vognbanen","Ringer til arbejdsgiveren, mens jeg holder i vognbanen","Stiller trekanten op, før jeg standser"]'::jsonb, 1, 'Først advares andre, og køretøjet flyttes ud af vognbanen. Først derefter stiger du ud, iført synlighedstøj.', 'Først andre trafikanter, så fejlen.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r2', 'fi', 'Milloin puet huomiovaatteet pysähtyessäsi tien varteen?', '["Kun olet asettanut kolmion","Vain pimeällä","Ennen kuin nouset ulos ohjaamosta","Vain moottoritiellä"]'::jsonb, 2, 'Huomiovaate puetaan jo ohjaamossa, jotta olet näkyvä heti, kun astut tielle.', 'Näkyvyys ensin, sitten ulos.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r2', 'en', 'When do you put on hi-vis clothing when you stop at the roadside?', '["After placing the triangle","Only in the dark","Before getting out of the cab","Only on a motorway"]'::jsonb, 2, 'Put hi-vis on already in the cab, so you are visible as soon as you step onto the road.', 'Visibility first, then out.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r2', 'et', 'Millal paned helkurriietuse selga, kui peatud tee ääres?', '["Pärast kolmnurga paigaldamist","Ainult pimedas","Enne kabiinist väljumist","Ainult kiirteel"]'::jsonb, 2, 'Helkurriietus pannakse selga juba kabiinis, et oleksid nähtav kohe, kui teele astud.', 'Kõigepealt nähtavus, siis välja.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r2', 'ru', 'Когда надевать светоотражающую одежду при остановке на обочине?', '["После установки знака","Только в темноте","До того, как выйти из кабины","Только на автомагистрали"]'::jsonb, 2, 'Светоотражающую одежду надевают ещё в кабине, чтобы вас было видно с первого шага на дорогу.', 'Сначала видимость, потом наружу.', 'Закон о дорожном движении 729/2018 (Финляндия)'),
  ('tieturva', 'tieturva.r2', 'sv', 'När tar du på varselkläder när du stannar vid vägkanten?', '["Efter att ha ställt ut triangeln","Bara i mörker","Innan jag kliver ur hytten","Bara på motorväg"]'::jsonb, 2, 'Varselkläderna tas på redan i hytten, så att du syns så fort du kliver ut på vägen.', 'Synlighet först, sedan ut.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r2', 'lv', 'Kad uzvelc atstarojošo apģērbu, apstājoties ceļa malā?', '["Pēc trīsstūra novietošanas","Tikai tumsā","Pirms izkāpšanas no kabīnes","Tikai uz automaģistrāles"]'::jsonb, 2, 'Atstarojošo apģērbu uzvelk jau kabīnē, lai tevi redzētu, tiklīdz izkāp uz ceļa.', 'Vispirms redzamība, tad ārā.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r2', 'lt', 'Kada apsivelki atšvaitinius drabužius, sustojęs pakelėje?', '["Pastatęs ženklą","Tik tamsoje","Prieš išlipdamas iš kabinos","Tik automagistralėje"]'::jsonb, 2, 'Atšvaitiniai drabužiai apsivelkami dar kabinoje, kad būtum matomas vos išlipęs į kelią.', 'Pirmiausia matomumas, tada lauk.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r2', 'pl', 'Kiedy zakładasz odzież ostrzegawczą, zatrzymując się na poboczu?', '["Po ustawieniu trójkąta","Tylko po ciemku","Przed wyjściem z kabiny","Tylko na autostradzie"]'::jsonb, 2, 'Odzież ostrzegawczą zakłada się już w kabinie, żebyś był widoczny od pierwszego kroku na drogę.', 'Najpierw widoczność, potem na zewnątrz.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r2', 'nb', 'Når tar du på synlighetsklær når du stopper i veikanten?', '["Etter å ha satt ut trekanten","Bare i mørket","Før jeg går ut av førerhuset","Bare på motorvei"]'::jsonb, 2, 'Synlighetsklærne tas på allerede i førerhuset, så du synes med en gang du går ut i veien.', 'Synlighet først, så ut.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r2', 'da', 'Hvornår tager du synlighedstøj på, når du standser i vejkanten?', '["Efter at have stillet trekanten op","Kun i mørke","Før jeg stiger ud af førerhuset","Kun på motorvej"]'::jsonb, 2, 'Synlighedstøjet tages på allerede i førerhuset, så du ses, så snart du træder ud på vejen.', 'Synlighed først, så ud.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r3', 'fi', 'Mihin varoituskolmio asetetaan?', '["Riittävän kauas ajoneuvon taakse, jotta lähestyvä ehtii reagoida; nopeassa liikenteessä kauemmas","Ajoneuvon viereen","Ajoneuvon eteen","Mihin tahansa, pääasia että se on näkyvissä"]'::jsonb, 0, 'Kolmio asetetaan niin kauas, että lähestyvä ehtii huomata vaaran ja hidastaa. Mitä suurempi nopeus ja huonompi näkyvyys, sitä kauemmas.', 'Lähestyvällä on oltava aikaa jarruttaa.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r3', 'en', 'Where do you place the warning triangle?', '["Far enough behind the vehicle for approaching traffic to react; further in fast traffic","Next to the vehicle","In front of the vehicle","Anywhere, as long as it is visible"]'::jsonb, 0, 'The triangle goes far enough back for approaching traffic to notice the hazard and slow down. The higher the speed and the poorer the visibility, the further.', 'Approaching traffic needs time to brake.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r3', 'et', 'Kuhu ohukolmnurk paigaldatakse?', '["Piisavalt kaugele sõiduki taha, et lähenejad jõuaksid reageerida; kiires liikluses kaugemale","Sõiduki kõrvale","Sõiduki ette","Ükskõik kuhu, peaasi et on näha"]'::jsonb, 0, 'Kolmnurk pannakse nii kaugele, et lähenejad jõuaksid ohtu märgata ja aeglustada. Mida suurem kiirus ja halvem nähtavus, seda kaugemale.', 'Lähenejal peab olema aega pidurdada.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r3', 'ru', 'Где ставить знак аварийной остановки?', '["Достаточно далеко позади, чтобы приближающиеся успели среагировать; при быстром движении дальше","Рядом с машиной","Перед машиной","Где угодно, лишь бы виден"]'::jsonb, 0, 'Знак ставят так далеко, чтобы приближающиеся успели заметить опасность и замедлиться. Чем выше скорость и хуже видимость, тем дальше.', 'Приближающимся нужно время на торможение.', 'Закон о дорожном движении 729/2018 (Финляндия)'),
  ('tieturva', 'tieturva.r3', 'sv', 'Var ställer du varningstriangeln?', '["Tillräckligt långt bakom fordonet för att mötande trafik ska hinna reagera; längre bort i snabb trafik","Bredvid fordonet","Framför fordonet","Var som helst, bara den syns"]'::jsonb, 0, 'Triangeln ställs så långt bak att trafiken bakifrån hinner upptäcka faran och sakta ner. Ju högre hastighet och sämre sikt, desto längre bort.', 'Trafiken bakifrån behöver tid att bromsa.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r3', 'lv', 'Kur novieto avārijas zīmi?', '["Pietiekami tālu aiz transportlīdzekļa, lai tuvojošies paspētu reaģēt; ātrā satiksmē tālāk","Blakus transportlīdzeklim","Transportlīdzekļa priekšā","Jebkur, galvenais, lai redzama"]'::jsonb, 0, 'Zīmi novieto tik tālu, lai tuvojošies paspētu pamanīt bīstamību un samazināt ātrumu. Jo lielāks ātrums un sliktāka redzamība, jo tālāk.', 'Tuvojošajiem vajag laiku bremzēšanai.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r3', 'lt', 'Kur pastatomas avarinio sustojimo ženklas?', '["Pakankamai toli už automobilio, kad artėjantys spėtų sureaguoti; greitame eisme toliau","Šalia automobilio","Prieš automobilį","Bet kur, svarbu, kad matytųsi"]'::jsonb, 0, 'Ženklas statomas taip toli, kad artėjantys spėtų pastebėti pavojų ir sulėtinti. Kuo didesnis greitis ir prastesnis matomumas, tuo toliau.', 'Artėjantiems reikia laiko stabdyti.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r3', 'pl', 'Gdzie ustawiasz trójkąt ostrzegawczy?', '["Odpowiednio daleko za pojazdem, by nadjeżdżający zdążyli zareagować; przy szybkim ruchu dalej","Obok pojazdu","Przed pojazdem","Gdziekolwiek, byle był widoczny"]'::jsonb, 0, 'Trójkąt stawia się tak daleko, by nadjeżdżający zdążyli zauważyć zagrożenie i zwolnić. Im większa prędkość i gorsza widoczność, tym dalej.', 'Nadjeżdżający potrzebują czasu na hamowanie.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r3', 'nb', 'Hvor setter du varseltrekanten?', '["Langt nok bak kjøretøyet til at trafikken bakfra rekker å reagere; lenger bak i høy fart","Ved siden av kjøretøyet","Foran kjøretøyet","Hvor som helst, bare den synes"]'::jsonb, 0, 'Trekanten settes så langt bak at trafikken bakfra rekker å oppdage faren og senke farten. Jo høyere fart og dårligere sikt, desto lenger bak.', 'Trafikken bakfra trenger tid til å bremse.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r3', 'da', 'Hvor stiller du advarselstrekanten?', '["Langt nok bag køretøjet til, at den kommende trafik kan nå at reagere; længere væk ved høj fart","Ved siden af køretøjet","Foran køretøjet","Hvor som helst, bare den kan ses"]'::jsonb, 0, 'Trekanten stilles så langt tilbage, at trafikken bagfra kan nå at opdage faren og sænke farten. Jo højere fart og dårligere udsyn, jo længere væk.', 'Trafikken bagfra skal have tid til at bremse.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r4', 'fi', 'Auto pysähtyy moottoritien pientareelle. Missä ihmisten on turvallisinta odottaa?', '["Ohjaamossa turvavyöt kiinni","Auton edessä pientareella","Auton takana, jotta näkyvät","Kaiteen takana, sivussa ajoneuvosta"]'::jsonb, 3, 'Moottoritiellä ajoneuvoon voi osua takaa. Turvallisinta on odottaa kaiteen takana, sivussa ajoneuvosta, ei sen edessä tai takana.', 'Mihin takaa tuleva auto osuisi?', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r4', 'en', 'The truck stops on a motorway hard shoulder. Where is it safest for people to wait?', '["In the cab with belts on","In front of the truck on the shoulder","Behind the truck, to be seen","Behind the barrier, to the side of the vehicle"]'::jsonb, 3, 'On a motorway the vehicle can be hit from behind. It is safest to wait behind the barrier, to the side of the vehicle, not in front of or behind it.', 'Where would a car from behind hit?', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r4', 'et', 'Auto peatub kiirtee teepeenral. Kus on inimestel kõige ohutum oodata?', '["Kabiinis, turvavööd kinni","Auto ees teepeenral","Auto taga, et olla nähtav","Piirde taga, sõidukist kõrval"]'::jsonb, 3, 'Kiirteel võidakse sõidukile tagant otsa sõita. Kõige ohutum on oodata piirde taga, sõidukist kõrval, mitte selle ees ega taga.', 'Kuhu tagant tulev auto tabaks?', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r4', 'ru', 'Машина остановилась на обочине автомагистрали. Где людям безопаснее всего ждать?', '["В кабине, пристегнувшись","Перед машиной на обочине","Позади машины, чтобы быть на виду","За ограждением, в стороне от машины"]'::jsonb, 3, 'На автомагистрали в машину могут врезаться сзади. Безопаснее всего ждать за ограждением, в стороне, а не перед машиной или позади неё.', 'Куда ударит машина сзади?', 'Закон о дорожном движении 729/2018 (Финляндия)'),
  ('tieturva', 'tieturva.r4', 'sv', 'Bilen stannar på motorvägens vägren. Var är det säkrast att vänta?', '["I hytten med bältet på","Framför bilen på vägrenen","Bakom bilen för att synas","Bakom räcket, vid sidan av fordonet"]'::jsonb, 3, 'På motorväg kan fordonet bli påkört bakifrån. Säkrast är att vänta bakom räcket, vid sidan av fordonet, inte framför eller bakom det.', 'Var skulle en bil bakifrån träffa?', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r4', 'lv', 'Auto apstājas uz automaģistrāles nomales. Kur cilvēkiem visdrošāk gaidīt?', '["Kabīnē ar piesprādzētām jostām","Auto priekšā uz nomales","Aiz auto, lai būtu redzami","Aiz barjeras, sānis no transportlīdzekļa"]'::jsonb, 3, 'Uz automaģistrāles transportlīdzeklim var uzbraukt no aizmugures. Visdrošāk gaidīt aiz barjeras, sānis, nevis priekšā vai aizmugurē.', 'Kur trāpītu auto no aizmugures?', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r4', 'lt', 'Automobilis sustoja automagistralės kelkraštyje. Kur žmonėms saugiausia laukti?', '["Kabinoje prisisegus","Prieš automobilį kelkraštyje","Už automobilio, kad matytųsi","Už atitvaro, šone nuo transporto priemonės"]'::jsonb, 3, 'Automagistralėje į transporto priemonę gali įvažiuoti iš galo. Saugiausia laukti už atitvaro, šone, o ne priešais ar už jos.', 'Kur atsitrenktų automobilis iš galo?', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r4', 'pl', 'Ciężarówka zatrzymuje się na pasie awaryjnym autostrady. Gdzie ludziom najbezpieczniej czekać?', '["W kabinie z zapiętymi pasami","Przed pojazdem na poboczu","Za pojazdem, żeby być widocznym","Za barierą, z boku pojazdu"]'::jsonb, 3, 'Na autostradzie w pojazd może uderzyć ktoś z tyłu. Najbezpieczniej czekać za barierą, z boku, a nie przed pojazdem ani za nim.', 'Gdzie uderzyłby samochód z tyłu?', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r4', 'nb', 'Bilen stopper i veiskulderen på motorveien. Hvor er det tryggest å vente?', '["I førerhuset med beltet på","Foran bilen på skulderen","Bak bilen for å synes","Bak rekkverket, ved siden av kjøretøyet"]'::jsonb, 3, 'På motorvei kan kjøretøyet bli påkjørt bakfra. Tryggest er å vente bak rekkverket, ved siden av kjøretøyet, ikke foran eller bak det.', 'Hvor ville en bil bakfra treffe?', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r4', 'da', 'Bilen standser i nødsporet på motorvejen. Hvor er det sikrest at vente?', '["I førerhuset med sele på","Foran bilen i nødsporet","Bag bilen for at blive set","Bag autoværnet, til siden for køretøjet"]'::jsonb, 3, 'På motorvejen kan køretøjet blive ramt bagfra. Det sikreste er at vente bag autoværnet, til siden for køretøjet, ikke foran eller bag det.', 'Hvor ville en bil bagfra ramme?', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r5', 'fi', 'Tietyömaalla liikenteenohjaaja näyttää pysähtymismerkkiä, mutta liikennevalo on vihreä. Kumpaa noudatat?', '["Liikennevaloa","Liikenteenohjaajaa","Kumpaakaan, ajan varovasti","Liikennemerkkiä"]'::jsonb, 1, 'Liikenteenohjaajan merkki on ensisijainen liikennevaloihin ja -merkkeihin nähden.', 'Ihminen paikan päällä näkee tilanteen.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r5', 'en', 'At roadworks a traffic controller signals stop, but the traffic light is green. Which do you follow?', '["The traffic light","The traffic controller","Neither, I drive carefully","The road sign"]'::jsonb, 1, 'A traffic controller’s signal takes precedence over traffic lights and signs.', 'The person on site sees the situation.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r5', 'et', 'Teetöödel näitab liiklusreguleerija peatumismärki, kuid foor on roheline. Keda järgid?', '["Foori","Liiklusreguleerijat","Mitte kumbagi, sõidan ettevaatlikult","Liiklusmärki"]'::jsonb, 1, 'Liiklusreguleerija märguanne on esmatähtis foori ja liiklusmärkide suhtes.', 'Inimene kohapeal näeb olukorda.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r5', 'ru', 'На дорожных работах регулировщик показывает «стоп», а светофор зелёный. Кому подчиняетесь?', '["Светофору","Регулировщику","Никому, еду осторожно","Знаку"]'::jsonb, 1, 'Сигнал регулировщика имеет приоритет над светофором и знаками.', 'Человек на месте видит ситуацию.', 'Закон о дорожном движении 729/2018 (Финляндия)'),
  ('tieturva', 'tieturva.r5', 'sv', 'Vid vägarbete visar en trafikvakt stopp, men trafikljuset är grönt. Vad följer du?', '["Trafikljuset","Trafikvakten","Ingetdera, jag kör försiktigt","Vägmärket"]'::jsonb, 1, 'En trafikvakts tecken har företräde framför trafikljus och vägmärken.', 'Människan på platsen ser läget.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r5', 'lv', 'Ceļa darbos satiksmes regulētājs rāda apstāšanās signālu, bet luksofors ir zaļš. Kam paklausi?', '["Luksoforam","Satiksmes regulētājam","Nevienam, braucu uzmanīgi","Ceļa zīmei"]'::jsonb, 1, 'Satiksmes regulētāja signālam ir prioritāte pār luksoforiem un ceļa zīmēm.', 'Cilvēks uz vietas redz situāciju.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r5', 'lt', 'Kelio darbuose eismo reguliuotojas rodo sustoti, bet šviesoforas žalias. Kuo vadovaujiesi?', '["Šviesoforu","Eismo reguliuotoju","Nei vienu, važiuoju atsargiai","Kelio ženklu"]'::jsonb, 1, 'Eismo reguliuotojo signalas turi pirmenybę prieš šviesoforus ir ženklus.', 'Žmogus vietoje mato situaciją.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r5', 'pl', 'Przy robotach drogowych kierujący ruchem daje znak stop, a światło jest zielone. Czego słuchasz?', '["Sygnalizatora","Kierującego ruchem","Niczego, jadę ostrożnie","Znaku"]'::jsonb, 1, 'Sygnały kierującego ruchem mają pierwszeństwo przed sygnalizacją świetlną i znakami.', 'Człowiek na miejscu widzi sytuację.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r5', 'nb', 'Ved veiarbeid gir trafikkdirigenten stopptegn, men trafikklyset er grønt. Hva følger du?', '["Trafikklyset","Trafikkdirigenten","Ingen av dem, jeg kjører forsiktig","Trafikkskiltet"]'::jsonb, 1, 'Tegn fra en trafikkdirigent går foran trafikklys og skilt.', 'Mennesket på stedet ser situasjonen.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r5', 'da', 'Ved vejarbejde giver trafikregulanten stoptegn, men lyset er grønt. Hvad følger du?', '["Lyssignalet","Trafikregulanten","Ingen af dem, jeg kører forsigtigt","Færdselstavlen"]'::jsonb, 1, 'Tegn fra en trafikregulant går forud for lyssignaler og færdselstavler.', 'Personen på stedet kan se situationen.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r6', 'fi', 'Pimeällä ja lähivaloilla tummiin pukeutunut ihminen tien reunalla huomataan vasta noin…', '["300 metrin päästä","150 metrin päästä","50 metrin päästä","10 metrin päästä"]'::jsonb, 2, 'Lähivaloilla tummiin pukeutunut erottuu vasta noin 50 metrin päästä, heijastin tai huomiovaate noin 150 metrin päästä tai kauempaa.', 'Paljon lähempää kuin luulisi.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r6', 'en', 'In the dark with dipped headlights, a person in dark clothes at the roadside is noticed only at about…', '["300 m","150 m","50 m","10 m"]'::jsonb, 2, 'With dipped headlights a person in dark clothes stands out only at about 50 m; with a reflector or hi-vis, at about 150 m or more.', 'Much closer than you would think.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r6', 'et', 'Pimedas lähitulede valgel märgatakse tumedas riietuses inimest tee ääres alles umbes…', '["300 m kauguselt","150 m kauguselt","50 m kauguselt","10 m kauguselt"]'::jsonb, 2, 'Lähitulede valgel eristub tumedas riietuses inimene alles umbes 50 m kauguselt, helkuri või helkurriietusega umbes 150 m või kaugemalt.', 'Palju lähemalt, kui arvaks.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r6', 'ru', 'В темноте при ближнем свете человека в тёмной одежде на обочине замечают только примерно с…', '["300 м","150 м","50 м","10 м"]'::jsonb, 2, 'При ближнем свете человека в тёмной одежде видно лишь метров с 50; со световозвращателем или в жилете — со 150 м и дальше.', 'Гораздо ближе, чем кажется.', 'Закон о дорожном движении 729/2018 (Финляндия)'),
  ('tieturva', 'tieturva.r6', 'sv', 'I mörker med halvljus upptäcks en person i mörka kläder vid vägkanten först på ungefär…', '["300 m","150 m","50 m","10 m"]'::jsonb, 2, 'Med halvljus syns en person i mörka kläder först på cirka 50 m; med reflex eller varselkläder på cirka 150 m eller mer.', 'Mycket närmare än man tror.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r6', 'lv', 'Tumsā ar tuvajām gaismām cilvēku tumšā apģērbā ceļa malā pamana tikai aptuveni no…', '["300 m","150 m","50 m","10 m"]'::jsonb, 2, 'Ar tuvajām gaismām cilvēks tumšā apģērbā izceļas tikai no aptuveni 50 m; ar atstarotāju vai atstarojošu apģērbu — no aptuveni 150 m vai tālāk.', 'Daudz tuvāk, nekā šķiet.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r6', 'lt', 'Tamsoje, šviečiant artimosioms šviesoms, tamsiai apsirengusį žmogų pakelėje pastebi tik maždaug iš…', '["300 m","150 m","50 m","10 m"]'::jsonb, 2, 'Šviečiant artimosioms šviesoms tamsiai apsirengęs žmogus išsiskiria tik maždaug iš 50 m; su atšvaitu ar atšvaitine liemene — maždaug iš 150 m ar toliau.', 'Daug arčiau, nei atrodo.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r6', 'pl', 'Po ciemku na światłach mijania osobę w ciemnym ubraniu na poboczu widać dopiero z około…', '["300 m","150 m","50 m","10 m"]'::jsonb, 2, 'Na światłach mijania osobę w ciemnym ubraniu widać dopiero z około 50 m; z odblaskiem lub w kamizelce — z około 150 m lub więcej.', 'Dużo bliżej, niż się wydaje.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r6', 'nb', 'I mørket med nærlys oppdages en person i mørke klær i veikanten først på omtrent…', '["300 m","150 m","50 m","10 m"]'::jsonb, 2, 'Med nærlys synes en person i mørke klær først på cirka 50 m; med refleks eller synlighetsklær på cirka 150 m eller mer.', 'Mye nærmere enn man skulle tro.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r6', 'da', 'I mørke med nærlys opdages en person i mørkt tøj i vejkanten først på omkring…', '["300 m","150 m","50 m","10 m"]'::jsonb, 2, 'Med nærlys ses en person i mørkt tøj først på cirka 50 m; med refleks eller synlighedstøj på cirka 150 m eller mere.', 'Meget tættere på, end man skulle tro.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r7', 'fi', 'Rengas puhkeaa kapealla tiellä ilman piennarta. Mitä teet?', '["Ajan hitaasti turvalliseen paikkaan tai hälytän tiepalvelun, en vaihda rengasta liikenteen keskellä","Vaihdan renkaan heti paikalla","Jätän auton ja lähden kävellen","Pyydän ohiajavia hiljentämään"]'::jsonb, 0, 'Renkaanvaihto ajokaistalla on hengenvaarallista. Siirry turvalliseen paikkaan tai kutsu apua ja varoita muita.', 'Oma turvallisuus ensin.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r7', 'en', 'A tyre bursts on a narrow road with no shoulder. What do you do?', '["Drive slowly to a safe place or call roadside assistance, not change the tyre in traffic","Change the tyre on the spot","Leave the truck and walk off","Wave passing traffic to slow down"]'::jsonb, 0, 'Changing a tyre in a traffic lane is life-threatening. Move to a safe place or call for help, and warn others.', 'Your own safety first.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r7', 'et', 'Kitsal teel ilma teepeenrata läheb rehv katki. Mida teed?', '["Sõidan aeglaselt ohutusse kohta või kutsun teeabi, rehvi liikluse keskel ei vaheta","Vahetan rehvi kohapeal","Jätan auto ja lähen jalgsi","Palun möödujatel aeglustada"]'::jsonb, 0, 'Rehvi vahetamine sõidurajal on eluohtlik. Liigu ohutusse kohta või kutsu abi ja hoiata teisi.', 'Kõigepealt oma ohutus.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r7', 'ru', 'Лопнула шина на узкой дороге без обочины. Что делаете?', '["Медленно еду до безопасного места или вызываю техпомощь, а не меняю колесо в потоке","Меняю колесо прямо на месте","Бросаю машину и ухожу пешком","Машу проезжающим, чтобы сбавили"]'::jsonb, 0, 'Замена колеса на полосе смертельно опасна. Переместитесь в безопасное место или вызовите помощь и предупредите других.', 'Сначала собственная безопасность.', 'Закон о дорожном движении 729/2018 (Финляндия)'),
  ('tieturva', 'tieturva.r7', 'sv', 'Ett däck exploderar på en smal väg utan vägren. Vad gör du?', '["Kör sakta till en säker plats eller ringer vägassistans, byter inte däck mitt i trafiken","Byter däcket på plats","Lämnar bilen och går därifrån","Vinkar åt trafiken att sakta ner"]'::jsonb, 0, 'Att byta däck i körfältet är livsfarligt. Flytta till en säker plats eller larma, och varna andra.', 'Din egen säkerhet först.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r7', 'lv', 'Uz šaura ceļa bez nomales pārplīst riepa. Ko dari?', '["Lēni braucu līdz drošai vietai vai izsaucu ceļa palīdzību, riepu satiksmes vidū nemainu","Nomainu riepu turpat","Atstāju auto un aizeju kājām","Mājot garāmbraucējiem, lai samazina ātrumu"]'::jsonb, 0, 'Riepas maiņa braukšanas joslā ir dzīvībai bīstama. Pārvietojies uz drošu vietu vai izsauc palīdzību un brīdini citus.', 'Vispirms paša drošība.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r7', 'lt', 'Siaurame kelyje be kelkraščio sprogo padanga. Ką darai?', '["Lėtai nuvažiuoju į saugią vietą arba kviečiu kelių pagalbą, padangos eismo viduryje nekeičiu","Keičiu padangą vietoje","Palieku automobilį ir einu pėsčias","Mojuoju pravažiuojantiems, kad sulėtintų"]'::jsonb, 0, 'Keisti padangą eismo juostoje pavojinga gyvybei. Pasitrauk į saugią vietą arba kviesk pagalbą ir įspėk kitus.', 'Pirmiausia savo saugumas.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r7', 'pl', 'Na wąskiej drodze bez pobocza pęka opona. Co robisz?', '["Jadę powoli w bezpieczne miejsce albo wzywam pomoc drogową, nie zmieniam koła na środku ruchu","Zmieniam koło na miejscu","Zostawiam auto i odchodzę pieszo","Macham przejeżdżającym, żeby zwolnili"]'::jsonb, 0, 'Wymiana koła na pasie ruchu zagraża życiu. Przemieść się w bezpieczne miejsce lub wezwij pomoc i ostrzeż innych.', 'Najpierw własne bezpieczeństwo.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r7', 'nb', 'Et dekk eksploderer på en smal vei uten skulder. Hva gjør du?', '["Kjører sakte til et trygt sted eller ringer veihjelp, bytter ikke dekk midt i trafikken","Bytter dekket på stedet","Forlater bilen og går","Vinker til trafikken om å senke farten"]'::jsonb, 0, 'Å bytte dekk i kjørefeltet er livsfarlig. Flytt deg til et trygt sted eller varsle, og varsle andre.', 'Din egen sikkerhet først.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r7', 'da', 'Et dæk eksploderer på en smal vej uden rabat. Hvad gør du?', '["Kører langsomt til et sikkert sted eller ringer efter vejhjælp, skifter ikke dæk midt i trafikken","Skifter dækket på stedet","Forlader bilen og går","Vinker til trafikken om at sætte farten ned"]'::jsonb, 0, 'At skifte dæk i vognbanen er livsfarligt. Flyt dig til et sikkert sted eller tilkald hjælp, og advar andre.', 'Din egen sikkerhed først.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r8', 'fi', 'Missä seisot, kun joudut tekemään töitä ajoneuvon vieressä tien reunalla?', '["Ajoneuvon liikenteen puoleisella sivulla","Liikenteestä poispäin olevalla puolella, kasvot tulevaa liikennettä kohti","Ajoneuvon takana","Ajokaistalla, jotta näen paremmin"]'::jsonb, 1, 'Seiso sillä puolella, jossa ajoneuvo suojaa sinua liikenteeltä, ja niin, että näet tulevan liikenteen ja ehdit väistää.', 'Anna ajoneuvon suojata sinua.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r8', 'en', 'Where do you stand when you have to work beside the vehicle at the roadside?', '["On the traffic side of the vehicle","On the side away from traffic, facing oncoming traffic","Behind the vehicle","In the lane, to see better"]'::jsonb, 1, 'Stand on the side where the vehicle shields you from traffic, and so that you see the oncoming traffic and can step away.', 'Let the vehicle shield you.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r8', 'et', 'Kus seisad, kui pead töötama sõiduki kõrval tee ääres?', '["Sõiduki liikluspoolsel küljel","Liiklusest eemal oleval küljel, näoga tuleva liikluse poole","Sõiduki taga","Sõidurajal, et paremini näha"]'::jsonb, 1, 'Seisa küljel, kus sõiduk kaitseb sind liikluse eest, ja nii, et näed lähenevat liiklust ning jõuad eest ära.', 'Lase sõidukil end kaitsta.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r8', 'ru', 'Где стоять, если приходится работать у машины на обочине?', '["Со стороны движения","С дальней от движения стороны, лицом к потоку","Позади машины","На полосе, чтобы лучше видеть"]'::jsonb, 1, 'Стойте с той стороны, где машина закрывает вас от потока, и так, чтобы видеть приближающиеся машины и успеть отойти.', 'Пусть машина вас закрывает.', 'Закон о дорожном движении 729/2018 (Финляндия)'),
  ('tieturva', 'tieturva.r8', 'sv', 'Var står du när du måste arbeta vid fordonet i vägkanten?', '["På fordonets trafiksida","På sidan bort från trafiken, med ansiktet mot mötande trafik","Bakom fordonet","I körfältet för att se bättre"]'::jsonb, 1, 'Stå på den sida där fordonet skyddar dig mot trafiken, och så att du ser trafiken som kommer och kan kliva undan.', 'Låt fordonet skydda dig.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r8', 'lv', 'Kur stāvi, ja jāstrādā pie transportlīdzekļa ceļa malā?', '["Transportlīdzekļa satiksmes pusē","Pusē prom no satiksmes, ar seju pret tuvojošos satiksmi","Aiz transportlīdzekļa","Braukšanas joslā, lai labāk redzētu"]'::jsonb, 1, 'Stāvi pusē, kur transportlīdzeklis tevi aizsedz no satiksmes, un tā, lai redzētu tuvojošos satiksmi un paspētu atkāpties.', 'Ļauj transportlīdzeklim tevi aizsargāt.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r8', 'lt', 'Kur stovi, kai tenka dirbti prie transporto priemonės pakelėje?', '["Transporto priemonės eismo pusėje","Pusėje nuo eismo, veidu į artėjantį eismą","Už transporto priemonės","Eismo juostoje, kad geriau matytum"]'::jsonb, 1, 'Stovėk toje pusėje, kur transporto priemonė tave dengia nuo eismo, ir taip, kad matytum artėjantį eismą ir spėtum pasitraukti.', 'Leisk transporto priemonei tave apsaugoti.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r8', 'pl', 'Gdzie stoisz, gdy musisz pracować przy pojeździe na poboczu?', '["Od strony ruchu","Po stronie z dala od ruchu, twarzą do nadjeżdżających","Za pojazdem","Na pasie, żeby lepiej widzieć"]'::jsonb, 1, 'Stań po tej stronie, gdzie pojazd osłania cię od ruchu, i tak, byś widział nadjeżdżające pojazdy i zdążył się odsunąć.', 'Niech pojazd cię osłania.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r8', 'nb', 'Hvor står du når du må jobbe ved kjøretøyet i veikanten?', '["På kjøretøyets trafikkside","På siden bort fra trafikken, med ansiktet mot trafikken som kommer","Bak kjøretøyet","I kjørefeltet for å se bedre"]'::jsonb, 1, 'Stå på den siden der kjøretøyet skjermer deg fra trafikken, og slik at du ser trafikken som kommer og kan trekke deg unna.', 'La kjøretøyet skjerme deg.', 'Tieliikennelaki 729/2018'),
  ('tieturva', 'tieturva.r8', 'da', 'Hvor står du, når du skal arbejde ved køretøjet i vejkanten?', '["På køretøjets trafikside","På siden væk fra trafikken, med ansigtet mod den kommende trafik","Bag køretøjet","I vognbanen for at se bedre"]'::jsonb, 1, 'Stå på den side, hvor køretøjet skærmer dig mod trafikken, og så du kan se den kommende trafik og træde til side.', 'Lad køretøjet skærme dig.', 'Tieliikennelaki 729/2018')
